[980] = {name = "Bane of Agony", additional_info = "{25 Mana} {30 yd range}\nInstant\n[q]Afflicts the target with agony, causing 72 Shadow damage over 24 sec. This damage is dealt slowly at first, and builds up as the Bane reaches its full duration. Only one Bane per Warlock can be active on any one target."},
