[1022] = {name = "Blessing of Protection", additional_info = "{25 Mana} {30 yd range}\n{Instant} {5 min cooldown}\n[q]A targeted party member is protected from all physical attacks for 6 sec, but during that time they cannot attack or use physical abilities. Players may only have one Blessing on them per Paladin at any one time. Applies Forbearance for 1 min. Cannot be cast while Forbearance is active."},
