[14514] = {name = "Blink", additional_info = "75 Mana\nInstant\n[q]Teleports the caster 20 yd. forward unless something is in the way. Also frees the caster from any bonds."},
[14515] = {name = "Dominate Mind", additional_info = "{30 Mana} {20 yd range}\n2 sec cast\n[q]Takes control of a humanoid enemy up to level 25 for 15 sec."},
[14516] = {name = "Strike", additional_info = "Melee Range\nNext Melee\nRequires Melee Weapon\n[q]Strikes at an enemy, inflicting increased melee damage."},
[14517] = {name = "Crusader Strike", additional_info = "{40 Mana} {Melee Range}\nInstant\nRequires Melee Weapon\n[q]Inflicts 27 damage to an enemy and increases the Holy damage it takes by 10 per Crusader Strike. Can be applied up to 5 times. Lasts 30 sec."},
[14518] = {name = "Crusader Strike", additional_info = "{40 Mana} {Melee Range}\nInstant\nRequires Melee Weapon\n[q]Inflicts 50 damage to an enemy and increases the Holy damage it takes by 20 per Crusader Strike. Can be applied up to 5 times. Lasts 30 sec."},
[14520] = {name = "Mental Agility", additional_info = "[q]Reduces the mana cost of your Smite, Holy Fire, and instant cast spells by 10%."},
[14521] = {name = "Meditation", additional_info = "[q]Allows 50% of your Mana regeneration to continue while casting."},
[14522] = {name = "Unbreakable Will", additional_info = "[q]Reduces the duration of Stun, Fear, and Silence effects inflicted on you by 30%."},
[14523] = {name = "Silent Resolve", additional_info = "[q]Reduces the threat generated by your Holy spells by 30% and reduces the duration of Stun, Fear, and Silence effects inflicted on you by 15%."},
[14524] = {name = "Wand Specialization", additional_info = "[q]Increases your damage with Wands by 25%."},
[14530] = {name = "Speed", additional_info = "Instant\n[q]Increases run speed by 40% for 10 sec."},
[14531] = {name = "Martyrdom", additional_info = "[q]Gives you a 0% chance to gain Focused Casting for 6 sec after being the victim of a melee or ranged critical strike. The Focused Casting effect prevents you from losing casting time when taking damage and increases your resistance to Interrupt effects by 20%."},
[14532] = {name = "Creeper Venom", additional_info = "2 sec cast\n[q]Increases the Physical damage taken by nearby enemies by 30% for 5 min."},
[14533] = {name = "Disjunction", additional_info = "Instant\n[q]Increases the Fire, Frost, and Arcane damage that nearby enemies take by 50% for 5 min."},
[14534] = {name = "Barbed Sting", additional_info = "Instant\n[q]Increases the time between nearby enemies' attacks by 54% for 5 min."},
[14535] = {name = "Dredge Sickness", additional_info = "Instant\n[q]Reduces all attributes of nearby enemies by 25% for 5 min."},
[14537] = {name = "Six Demon Bag", additional_info = "30 yd range\nInstant\n[q]Blasts enemies in front of you with the power of wind, fire, all that kind of thing!"},
[14538] = {name = "Aural Shock", additional_info = "Instant\n[q]Reduces the casting speed of nearby enemies by 35% for 5 min."},
[14539] = {name = "Putrid Enzyme", additional_info = "Instant\n[q]Increases the Nature damage taken by nearby enemies by 50% and increases the Shadow damage they take by 50%. Lasts 5 min."},
