[16992] = {name = "[q3]Frostguard", additional_info = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nArcanite Bar (18), Blue Sapphire (8), Azerothian Diamond (8), Essence of Water (4), Dense Grinding Stone (2), Enchanted Leather (4)\n[q3]Frostguard\n(2)\nBinds when equipped\nUnique-EquippedOne-Hand Sword\n81 - 151 Damage Speed 2.80\n(41.43 damage per second)\nDurability 90 / 90\n58\n[q2]Chance on hit: Slows the target's movement speed by 30% and increases the time between their attacks by 25% for 5 sec."},
[16993] = {name = "[q3]Masterwork Stormhammer", additional_info = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nEnchanted Thorium Bar (20), Huge Emerald (8), Large Opal (8), Essence of Earth (6), Enchanted Leather (4)\n[q3]Masterwork Stormhammer\n(2)\nBinds when equipped\nOne-Hand Mace\n46 - 86 Damage Speed 1.60\n(41.25 damage per second)\nDurability 90 / 90\n57\n[q2]Chance on hit: Blasts up to 3 targets for 105 to 145 Nature damage."},
