[20177] = {name = "Reckoning", additional_info = "[q]Gives you a 0% chance to gain an extra attack after Blocking a melee attack and a 0% chance to gain an extra attack after being the victim of a non-periodic critical strike."},
[20178] = {name = "Reckoning", additional_info = "Instant\n[q]Grants extra attacks after blocking."},
