[20194] = {name = "Improved Blessing of Salvation", additional_info = "[q]Increases the duration of your Blessing of Salvation by 5 min."},
[20195] = {name = "Improved Blessing of Salvation", additional_info = "[q]Increases the duration of your Blessing of Salvation by 10 min."},
[20196] = {name = "One-Handed Weapon Specialization", additional_info = "[q]Increases the damage you deal with one-handed melee weapons by 2%."},
[20201] = {name = "Arcanite Rod", additional_info = "45 sec cast\nTools: Blacksmith Hammer\nReagents:\nArcanite Bar (3), Dense Grinding Stone\n(2)\nCrafting Reagent\n[q]\"Needed by Enchanters.\""},
[20203] = {name = "Fire Nova", additional_info = "Instant\nTools: Fire Totem\n[q]Inflicts Fire damage to nearby enemies."},
[20205] = {name = "Spiritual Focus", additional_info = "[q]Gives your Flash of Light, Holy Light, and Light's Vigil spells a 14% chance to not lose casting time when you take damage."},
[20210] = {name = "Illumination", additional_info = "[q]After getting a critical effect from your Flash of Light, Holy Light, Light's Vigil, or Holy Shock heal spell you have a 0% chance to gain Mana equal to 50% of the base cost of the spell."},
[20216] = {name = "Divine Favor", additional_info = "4% of base mana\n{Instant} {2 min cooldown}\n[q]When activated, gives your next Flash of Light, Holy Light, or Holy Shock spell a 100% critical effect chance."},
[20217] = {name = "Blessing of Kings", additional_info = "{8% of base mana} {30 yd range}\nInstant\n[q]Places a Blessing on the friendly target, increasing total stats by 10% for 1 hour. Players may only have one Blessing on them per Paladin at any one time."},
[20218] = {name = "Sanctity Aura", additional_info = "Instant\n[q]Increases Holy damage done by party members within 30 yards by 10%. Players may only have one Aura on them per Paladin at any one time."},
[20219] = {name = "Gnomish Engineer", additional_info = "Instant\n[q]Allows an engineer to make fantastic, yet unreliable gnomish devices."},
