[20229] = {name = "Blast Wave", additional_info = "Instant\n[q]Inflicts 694 to 806 Fire damage to nearby enemies and reduces their movement speed by 50% for 8 sec."},
[20230] = {name = "Retaliation", additional_info = "{Instant} {15 min cooldown}\nRequires Battle Stance\n[q]Instantly counterattack any enemy that strikes you in melee for 15 sec. Melee attacks made from behind cannot be counterattacked. A maximum of 30 attacks will cause retaliation."},
[20231] = {name = "Seal of Fury", additional_info = "100 yd range\nInstant\n[q]Deals additional Holy damage on melee attack."},
[20232] = {name = "Judgement of Fury", additional_info = "100 yd range\nInstant\n[q]Taunts the target to attack you."},
[20237] = {name = "Healing Light", additional_info = "[q]Increases the amount healed by your Holy Light, Flash of Light, and Holy Shock spells by 4%."},
[20240] = {name = "Retaliation", additional_info = "{1 Rage} {Melee Range}\nInstant\n[q]Designer note: This costs 1 rage to prevent its damage from generating rage."},
[20243] = {name = "Devastate", additional_info = "{15 Rage} {Melee Range}\nInstant\n[q]Sunder the target's armor causing the Sunder Armor effect. In addition, causes 120% of weapon damage plus 58 for each application of Sunder Armor on the target. The Sunder Armor effect can stack up to 5 times."},
[20244] = {name = "Improved Blessing of Wisdom", additional_info = "[q]Increases the effect of your Blessing of Wisdom spell by 10%."},
[20245] = {name = "Improved Blessing of Wisdom", additional_info = "[q]Increases the effect of your Blessing of Wisdom spell by 20%."},
[20249] = {name = "Improved Flash of Light", additional_info = "[q]Increases the critical effect chance of your Flash of Light spell by 2%."},
[20250] = {name = "Improved Flash of Light", additional_info = "[q]Increases the critical effect chance of your Flash of Light spell by 4%."},
[20251] = {name = "Improved Flash of Light", additional_info = "[q]Increases the critical effect chance of your Flash of Light spell by 6%."},
[20252] = {name = "Intercept", additional_info = "{10 Rage} {8 - 25 yd range}\n{Instant} {30 sec cooldown}\nRequires Berserker Stance\n[q]Charge an enemy, causing 25 damage and stunning it for 3 sec."},
[20253] = {name = "Intercept Stun", additional_info = "8 - 25 yd range\nInstant\nRequires Battle Stance"},
[20254] = {name = "Improved Concentration Aura", additional_info = "[q]Increases the effect of your Concentration Aura by an additional 15%, and your Concentration Aura also reduces the duration of Silence and Interrupt effects on your party members by 30%."},
