[20271] = {name = "Judgement", additional_info = "{6% of base mana} {10 yd range}\n{Instant} {10 sec cooldown}\n[q]Unleash the energy of a Seal spell upon an enemy. Does not consume the Seal. Refer to individual Seals for Judgement effect."},
