[384135] = {name = "Rune of Fortune", additional_info = "Instant\n[q]Grants all raid members the chance to discover additional rewards from Kel'Thuzad and his lieutenants.\n\n This effect stacks and lasts for an entire week."},
[384255] = {name = "Changing Talents", additional_info = "Unlimited range\n5 sec cast\n[q]Apply changes to your talents."},
[398061] = {name = "Bracers of Redirection", additional_info = "[q]Gain 1 combo point whenever you avoid any attack or spell from an enemy target that is not your current target.\n(1s cooldown)"},
[398115] = {name = "Inoculation Belt", additional_info = "Instant\n[q]Take 1% damage to remove a disease or poison effect from yourself."},
[398117] = {name = "Pockets of Treats", additional_info = "20 yd range\nInstant\n[q]Open the bag of treats and palm it into your target's pocket, increasing the damage of Beasts against this target by 20."},
[398196] = {name = "Quick Draw", additional_info = "{25 Energy} {20 yd range}\n{Instant} {10 sec cooldown}\nRequires Ranged Weapon\n[q]Draw your ranged weapon and fire a quick shot at an enemy, causing normal ranged weapon damage and reducing the target's movement speed by 50% for 6 sec. Awards 1 combo point.\n\n Quick Draw benefits from all talents and effects that trigger from or modify Sinister Strike."},
[398197] = {name = "Quick Draw", additional_info = "[q]Gain the Quick Draw ability:\n\n\nDraw your ranged weapon and fire a quick shot at an enemy, causing normal ranged weapon damage and reducing the target's movement speed by 50% for 6 sec. Awards 1 combo point.\n\n Quick Draw benefits from all talents and effects that trigger from or modify Sinister Strike."},
[398198] = {name = "Storm of Swords", additional_info = "{20 Energy} {/ 1 to 5 Combo Points 100 yd range}\nInstant\n[q]Finishing move that increases parry chance. Lasts longer and increases parry chance per combo point:\n 1 point : 10 seconds, 12% Parry\n 2 points: 15 seconds, 14% Parry\n 3 points: 20 seconds, 16% Parry\n 4 points: 25 seconds, 18% Parry\n 5 points: 30 seconds, 20% Parry"},
[398199] = {name = "Hubris Tunic", additional_info = nil},
[398538] = {name = "Runecarve Bracer - Minor Deflect", additional_info = "5 sec cast\nRequires Bracers\nTools: Runed Copper Rod\nReagents:\nLesser Magic Essence , Strange Dust\n[q]Permanently enchant bracers so that the defense skill of the wearer is increased by 1."},
[398603] = {name = "Runecarving", additional_info = "Instant\n[q]Affix powerful runes to your armor."},
[398604] = {name = "Runecarving", additional_info = nil},
[399954] = {name = "Chest Rune Ability", additional_info = "Instant\n[q]Equip a Chest slot item with a Rune engraved to activate an ability in this slot."},
[399956] = {name = "Mutilate", additional_info = "{60 Energy} {Melee Range}\nInstant\n[q]Instantly attacks with both weapons for 75% weapon damage plus an additional 25 with each weapon. Damage increased by 20% against Poisoned targets. Awards 2 Combo Points."},
[399960] = {name = "Mutilate", additional_info = nil},
[399961] = {name = "Mutilate", additional_info = nil},
[399962] = {name = "Mutilate", additional_info = "[q]Gain the Mutilate ability:\n\n\n Instantly attacks with both weapons for 75% weapon damage plus an additional 24.75 with each weapon. Damage increased by 20% against Poisoned targets. Awards 2 Combo Points."},
[399965] = {name = "Deadly Brew", additional_info = "[q]Grants several improvements to your poisons:\n\n When you inflict any other poison on a target, you also inflict Deadly Poison.\n\n If your weapon does not have a poison applied, it has a chance to trigger Instant Poison as if Instant Poison were applied.\n\n Deadly Poison and Instant Poison now gain increased damage from your Attack Power.\n\n Your Deadly Poison can now be active on targets affected by another Rogue's Deadly Poison."},
[399966] = {name = "Legs Rune Ability", additional_info = "Instant\n[q]Equip a Legs slot item with a Rune engraved to activate an ability in this slot."},
[399967] = {name = "Hands Rune Ability", additional_info = "Instant\n[q]Equip a Hands slot item with a Rune engraved to activate an ability in this slot."},
[399968] = {name = "Envenom", additional_info = "[q]Gain the Envenom ability:"},
[399969] = {name = "Deadly Brew", additional_info = "[q]Gain the Deadly Brew ability:\n\n\n Grants several improvements to your poisons:\n\n When you inflict any other poison on a target, you also inflict Deadly Poison.\n\n If your weapon does not have a poison applied, it has a chance to trigger Instant Poison as if Instant Poison were applied.\n\n Deadly Poison and Instant Poison now gain increased damage from your Attack Power.\n\n Your Deadly Poison can now be active on targets affected by another Rogue's Deadly Poison."},
[399985] = {name = "Shadowstrike", additional_info = "{20 Energy} {25 yd range}\nInstant\nRequires Melee Weapon\nRequires Stealth\n[q]Teleport behind your target and strike, causing 150% weapon damage to the target. Must be stealthed. Awards 1 combo point."},
[399986] = {name = "Shuriken Toss", additional_info = "{30 Energy} {25 yd range}\n{Instant} {20 sec cooldown}\n[q]Throw a shuriken at your enemy dealing damage equal to 50% of your Attack Power, and also strike up to 4 additional nearby targets. Awards 1 combo point per target hit."},
[400009] = {name = "Between the Eyes", additional_info = "{35 Energy} {/ 1 to 5 Combo Points 20 yd range}\n20 sec cooldown\nRequires Ranged Weapon\n[q]Ranged Finishing move that causes damage per combo point, increased by Attack Power, and Stuns the target:\n\n 1 point:  [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] to [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] damage, 1 sec Stun\n 2 points: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] to [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] damage, 2 sec Stun\n 3 points: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] to [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] damage, 3 sec Stun\n 4 points: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] to [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] damage, 4 sec Stun\n 5 points: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] to [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] damage, 5 sec Stun\n\n Cooldown shared with Kidney Shot."},
[400012] = {name = "Blade Dance", additional_info = "{25 Energy} {/ 1 to 5 Combo Points 100 yd range}\nInstant\n[q]Finishing move that increases your Parry chance by 10% and grants 4 Attack Power for each point of your defense skill beyond ( 60 * 5). Lasts longer per combo point:\n\n 1 point : 14 seconds\n 2 points: 18 seconds\n 3 points: 22 seconds\n 4 points: 26 seconds\n 5 points: 30 seconds"},
[400014] = {name = "Just a Flesh Wound", additional_info = "[q]You take 30% reduced Physical damage while Blade Dance is active, reduced by an additional 1% for every 12 of your Defense skill beyond ( 60 * 5). Additionally, your chance to Dodge is multiplied by 50%, you have 6% reduced chance to be critically hit by melee attacks, you deal 20% less damage, the threat generated by all your actions is massively increased, and your Feint ability is replaced with Tease, which Taunts the target to attack you.\n\n\nTaunts the target to attack you, but has no effect if the target is already attacking you."},
[400015] = {name = "Rolling with the Punches", additional_info = nil},
[400016] = {name = "Rolling with the Punches", additional_info = "[q]Each time you Dodge or Parry, you gain 6% increased Health, stacking up to 5 times."},
[400023] = {name = "Cheat Death", additional_info = "Instant\n[q]Any attack which would otherwise kill you will instead reduce you to 10% of your maximum health. In addition, all damage taken will be reduced by up to 90% for 3 sec. This effect cannot occur more than once per minute."},
