[400573] = {name = "Arcane Blast", additional_info = "{Instant} {3 min cooldown}\n[q]Blasts the target with energy, dealing Arcane damage. Each time you cast Arcane Blast, the damage of all other spells is increased by 10% and mana cost of Arcane Blast is increased by 175%. Effect stacks up to 4 times and lasts 8 sec."},
