[402832] = {name = "Prayer of Mending", additional_info = "[q]Gain the Prayer of Mending ability:\n\n\nPlaces a spell on the target that heals them for [(172 + (Healing * 0.42899999 )) * ( 1 * 1 )] the next time they take damage or receive non-periodic healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time per caster."},
[402833] = {name = "Shadow Word: Death", additional_info = "[q]Gain the Shadow Word: Death ability:\n\n\nA word of dark binding that inflicts [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 320 / 100] to [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 372 / 100] Shadow damage to the target. If the target is not killed by Shadow Word: Death, the caster takes damage equal to 50% of the damage attempted against the target."},
