[402837] = {name = "Binding Heal", additional_info = "[q]Gain the Binding Heal ability:\n\n\nHeals a friendly target and the caster for 236 to 284. Low threat."},
[402838] = {name = "Shared Pain", additional_info = "[q]Gain the Shared Pain ability:\n\n\nYour Shadow Word: Pain now also afflicts up to 2 additional nearby targets within 15 yards."},
