[403619] = {name = "Fel Armor", additional_info = "28% of base mana\nInstant\n[q]Surrounds the caster with fel energy, increasing spell damage and healing by 1 plus additional spell damage and healing equal to 50% of your Spirit. In addition, you regain 2% of your maximum health every 5 sec. Only one type of Armor spell can be active on the Warlock at any time. Lasts 30 min."},
[403628] = {name = "Shadow Bolt Volley", additional_info = "[q]Your Shadow Bolt now strikes up to 5 targets within a chain distance of 10 yards, but for 5% reduced damage."},
[403629] = {name = "Chaos Bolt", additional_info = "{7% of base mana} {30 yd range}\n{2.5 sec cast} {12 sec cooldown}\n[q]Sends a bolt of chaotic fire at the enemy, dealing [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100] to [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] Chaos damage. Chaos Bolt always hits, cannot be resisted, and its knowledge causes all your Fire spells to pierce through absorption effects. Chaos Bolt gains a high chance to be resisted when used against monsters 4 or more levels above your level."},
[403630] = {name = "Chaos Bolt", additional_info = nil},
