[403789] = {name = "Metamorphosis", additional_info = "100% of base mana\nInstant\n[q]Transform into a Demon, increasing Armor by 500%, Health by 15%, reducing the chance you will be critically hit by 6%, increasing your threat by 77%, increasing mana gained from Life Tap by 100%, but reducing all damage you deal by 15%. Metamorphosis transforms the functionality of some abilities and grants new ones:\n\n Searing Pain: Now instant.\n\n Shadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to 10 nearby enemies, but has a 6 sec cooldown.\n\n Fear: Replaced with Menace.\n\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\n Demon Charge\n\n\nCharge an enemy and stun it for 1 sec. Cannot be used in combat.\n\n Demonic Howl\n\n\nForces all nearby enemies to focus attacks on you for 6 sec."},
[403816] = {name = "Metamorphosis", additional_info = "[q]Transform into a Demon, increasing Armor by 500%, reducing the chance you will be critically hit by 6%, increasing your threat by 77%, increasing mana gained from Life Tap by 100%, and transforming the functionality of some of your abilities:\n\n Searing Pain: Now instant.\n\n Shadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to 500 nearby enemies.\n\n Curse of Recklessness: Now also taunts your target to attack you for until canceled.\n\n Howl of Terror: Now also forces all nearby enemies to attack you for until canceled, but cooldown increased to 10 minutes."},
[403828] = {name = "Menace", additional_info = "Melee Range\n{Instant} {10 sec cooldown}\n[q]Taunts the target to attack you, but has no effect if the target is already attacking you."},
[403835] = {name = "Shadow Cleave", additional_info = "{12 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Punish up to 10 nearby enemies with a Shadow lash, dealing 3 to 6 to each.\n\n Shadow Cleave benefits from and triggers most talents and effects that Shadow Bolt benefits from and triggers. [ S03 - Tuning and Overrides Passive - All Classes : Hitting a target with Shadow Cleave also grants you 4 Spell Damage for each point of your defense skill beyond ( 5 * 5). Lasts 15 sec ]"},
[403839] = {name = "Shadow Cleave", additional_info = "{20 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Punish up to 10 nearby enemies with a Shadow lash, dealing 8 to 13 to each.\n\n Shadow Cleave benefits from and triggers most talents and effects that Shadow Bolt benefits from and triggers. [ S03 - Tuning and Overrides Passive - All Classes : Hitting a target with Shadow Cleave also grants you 4 Spell Damage for each point of your defense skill beyond ( 11 * 5). Lasts 15 sec ]"},
