[403844] = {name = "Shadow Cleave", additional_info = "{132 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Punish up to 10 nearby enemies with a Shadow lash, dealing 116 to 157 to each.\n\n Shadow Cleave benefits from and triggers most talents and effects that Shadow Bolt benefits from and triggers. [ S03 - Tuning and Overrides Passive - All Classes : Hitting a target with Shadow Cleave also grants you 4 Spell Damage for each point of your defense skill beyond ( 49 * 5). Lasts 15 sec ]"},
[403848] = {name = "Shadow Cleave", additional_info = "{157 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Punish up to 10 nearby enemies with a Shadow lash, dealing 151 to 203 to each.\n\n Shadow Cleave benefits from and triggers most talents and effects that Shadow Bolt benefits from and triggers. [ S03 - Tuning and Overrides Passive - All Classes : Hitting a target with Shadow Cleave also grants you 4 Spell Damage for each point of your defense skill beyond ( 57 * 5). Lasts 15 sec ]"},
[403851] = {name = "Shadow Cleave", additional_info = "{185 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Punish up to 10 nearby enemies with a Shadow lash, dealing 193 to 258 to each.\n\n Shadow Cleave benefits from and triggers most talents and effects that Shadow Bolt benefits from and triggers. [ S03 - Tuning and Overrides Passive - All Classes : Hitting a target with Shadow Cleave also grants you 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec ]"},
[403852] = {name = "Shadow Cleave", additional_info = "{190 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Punish up to 10 nearby enemies with a Shadow lash, dealing 203 to 271 to each.\n\n Shadow Cleave benefits from and triggers most talents and effects that Shadow Bolt benefits from and triggers. [ S03 - Tuning and Overrides Passive - All Classes : Hitting a target with Shadow Cleave also grants you 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec ]"},
[403858] = {name = "Haunt", additional_info = "[q]Gain the Haunt ability:\n\n\nSend a ghostly soul to assault your current target, dealing 115 to 135 damage, and increasing all Shadow damage over time you deal to that target by 10% for 12 sec. When Haunt expires for any reason you will be healed for 100% of the damage it dealt to your target."},
[403860] = {name = "Chaos Bolt", additional_info = "[q]Gain the Chaos Bolt ability:\n\n\nSends a bolt of chaotic fire at the enemy, dealing [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100] to [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] Chaos damage. Chaos Bolt always hits, cannot be resisted, and its knowledge causes all your Fire spells to pierce through absorption effects. Chaos Bolt gains a high chance to be resisted when used against monsters 4 or more levels above your level."},
[403863] = {name = "Soul Siphon", additional_info = "[q]Gain the Soul Siphon ability:\n\n\nIncreases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by 20%."},
[403868] = {name = "Master Channeler", additional_info = "[q]Gain the Master Channeler ability:\n\n\nYour Drain Life is no longer channeled, lasts 15 sec with a 15 sec cooldown, costs 100% more mana, and heals you for 50% more each time it deals damage."},
[403871] = {name = "Shadow Bolt Volley", additional_info = "[q]Gain the Shadow Bolt Volley ability:\n\n\nYour Shadow Bolt now strikes up to 5 targets within a chain distance of 10 yards, but for 5% reduced damage."},
[403872] = {name = "Lake of Fire", additional_info = "[q]Gain the Lake of Fire ability:\n\n\nYour Rain of Fire is no longer channeled, but gains a 8 sec cooldown."},
[403873] = {name = "Metamorphosis", additional_info = "[q]Gain the Metamorphosis ability:\n\n\nTransform into a Demon, increasing Armor by 500%, Health by 15%, reducing the chance you will be critically hit by 6%, increasing your threat by 77%, increasing mana gained from Life Tap by 100%, but reducing all damage you deal by 15%. Metamorphosis transforms the functionality of some abilities and grants new ones:\n\n Searing Pain: Now instant.\n\n Shadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to 10 nearby enemies, but has a 6 sec cooldown.\n\n Fear: Replaced with Menace.\n\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\n Demon Charge\n\n\nCharge an enemy and stun it for 1 sec. Cannot be used in combat.\n\n Demonic Howl\n\n\nForces all nearby enemies to focus attacks on you for 6 sec."},
[403919] = {name = "Engrave Gloves - Haunt", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Haunt rune:\n\n\nSend a ghostly soul to assault your current target, dealing 115 to 135 damage, and increasing all Shadow damage over time you deal to that target by 10% for 12 sec. When Haunt expires for any reason you will be healed for 100% of the damage it dealt to your target."},
[403920] = {name = "Engrave Cloak - Soul Siphon", additional_info = "3 sec cast\nRequires Cloak\n[q]Engrave your cloak with the Soul Siphon rune:\n\n\nIncreases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by 20%."},
[403925] = {name = "Engrave Gloves - Chaos Bolt", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Chaos Bolt rune:\n\n\nSends a bolt of chaotic fire at the enemy, dealing [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100] to [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] Chaos damage. Chaos Bolt always hits, cannot be resisted, and its knowledge causes all your Fire spells to pierce through absorption effects. Chaos Bolt gains a high chance to be resisted when used against monsters 4 or more levels above your level."},
[403932] = {name = "Engrave Chest - Master Channeler", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Master Channeler rune:\n\n\nYour Drain Life is no longer channeled, lasts 15 sec with a 15 sec cooldown, costs 100% more mana, and heals you for 50% more each time it deals damage."},
[403936] = {name = "Engrave Gloves - Shadow Bolt Volley", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Shadow Bolt Volley rune:\n\n\nYour Shadow Bolt now strikes up to 5 targets within a chain distance of 10 yards, but for 5% reduced damage."},
[403937] = {name = "Engrave Chest - Lake of Fire", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Lake of Fire rune:\n\n\nYour Rain of Fire is no longer channeled, but gains a 8 sec cooldown."},
[403938] = {name = "Engrave Gloves - Metamorphosis", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Metamorphosis rune:\n\n\nTransform into a Demon, increasing Armor by 500%, Health by 15%, reducing the chance you will be critically hit by 6%, increasing your threat by 77%, increasing mana gained from Life Tap by 100%, but reducing all damage you deal by 15%. Metamorphosis transforms the functionality of some abilities and grants new ones:\n\n Searing Pain: Now instant.\n\n Shadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to 10 nearby enemies, but has a 6 sec cooldown.\n\n Fear: Replaced with Menace.\n\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\n Demon Charge\n\n\nCharge an enemy and stun it for 1 sec. Cannot be used in combat.\n\n Demonic Howl\n\n\nForces all nearby enemies to focus attacks on you for 6 sec."},
