[407627] = {name = "Righteous Fury", additional_info = "Instant\n[q]Increases the threat generated by your Holy spells by 80% and gives you mana when healed by other friendly targets' spells equal to 25% of the amount healed. Additionally, damage which takes you below 35% health is reduced by 20%. Lasts until canceled."},
