[407778] = {name = "Divine Storm", additional_info = "12% of base mana\n{Instant} {10 sec cooldown}\nRequires Melee Weapon\n[q]An instant weapon attack that causes 110% of weapon damage to up to 4 enemies within 8 yards. The Divine Storm heals up to 3 party or raid members totaling 25% of the damage caused."},
[407782] = {name = "Divine Storm", additional_info = "100 yd range\nInstant\n[q]Divine Storm damage heals friendly targets."},
[407784] = {name = "Divine Storm", additional_info = "Unlimited range\nInstant\n[q]Divine Storm damage dealt heals nearby friendly targets."},
[407788] = {name = "Avenging Wrath", additional_info = "8% of base mana\n{Instant} {3 min cooldown}\n[q]Increases all damage and healing caused by 20% for 20 sec. Causes Forbearance and cannot be used while Forebearance is active."},
[407791] = {name = "Aku'mai's Rage", additional_info = "Instant\n[q]Increases the Physical damage dealt by the caster by 25 and speeds its attacks by 30% for 15 sec."},
[407794] = {name = "Triple Puncture", additional_info = "Melee Range\nInstant\n[q]Inflicts Physical damage to an enemy every 3 sec. for 15 sec.\n(1s cooldown)"},
[407798] = {name = "Seal of Martyrdom", additional_info = "4% of base mana\nInstant\n[q]Fills you with holy spirit for 30 sec, causing each of your melee attacks to deal 50% weapon damage to your target, but you lose health equal to 10% of the damage inflicted. While this seal is active, your party and raid members within 40 yards each gain mana equal to 65% of damage you take from this seal.\n\n Unleashing this Seal's energy will judge an enemy, instantly causing 85% weapon damage at the cost of health equal to 10% of the damage inflicted.\n\n This ability's Seal and Judgement benefit from talents and effects that modify the Seal or Judgement of Seal of Righteousness."},
[407799] = {name = "Seal of Martyrdom", additional_info = nil},
[407800] = {name = "Seal of Martyrdom", additional_info = "Instant\n[q]Seal of Martyrdom damage also damages the Paladin."},
[407802] = {name = "Seal of Martyrdom", additional_info = "40 yd range\nInstant\n[q]Gaining mana from damage received by the Paladin."},
[407803] = {name = "Judgement of Martyrdom", additional_info = nil},
[407804] = {name = "Divine Sacrifice", additional_info = "{Instant} {2 min cooldown}\n[q]30% of all damage taken by party members within 30 yards is redirected to the Paladin for 10 sec. Damage which reduces the Paladin below 20% health will break the effect and grant the paladin 10% increased damage and healing done for 10 sec. Divine Sacrifice cannot be used while you are under the effects of Blessing of Protection, Divine Shield, or Divine Protection, and prevents you from being targeted by those abilities while it is active."},
[407805] = {name = "Sacrifice Redeemed", additional_info = "{Instant} {3 min cooldown}\n[q]Damage and healing increased after your sacrifice."},
[407811] = {name = "Cleave", additional_info = "Melee Range\nNext Melee\n[q]Inflicts weapon damage plus 23 to 27 to an enemy and its nearest allies, affecting up to 3 targets."},
[407812] = {name = "Immunity to Freezing Arrow", additional_info = nil},
[407813] = {name = "Frost Arrow", additional_info = "5 - 30 yd range\n1 sec cast\nRequires Ranged Weapon\n[q]Shoots at an enemy, inflicting Physical damage."},
[407819] = {name = "Frost Arrow", additional_info = "50 yd range\n1.5 sec cast\nRequires Ranged Weapon\n[q]Shoots at an enemy, inflicting Physical damage."},
[407821] = {name = "Frost Arrow", additional_info = "50 yd range\nInstant\nRequires Ranged Weapon\n[q]Shoots at an enemy, inflicting Physical damage."},
[407822] = {name = "Frost Arrow", additional_info = nil},
[407880] = {name = "Inspiration Exemplar", additional_info = "2% of base mana\nInstant\n[q]Your inspiring presence periodically dispels Fear and Sleep effects on nearby party members."},
[407881] = {name = "Inspiration Exemplar", additional_info = "Instant\n[q]Your inspiring presence periodically dispels Fear and Sleep effects on nearby party members."},
[407957] = {name = "Avenging Wrath", additional_info = nil},
[407973] = {name = "Wild Strike", additional_info = "100 yd range\nInstant\n[q]Extra Attack."},
[407975] = {name = "Wild Strikes", additional_info = "Instant\n[q]Party members within 100 yards gain increased combat ferocity. Each melee hit has a 20% chance of granting the attacker an extra attack with 20% additional Attack Power. No effect if the party member is already benefitting from Windfury Totem.\n(Proc chance: 20%, 1.5s cooldown)"},
[407977] = {name = "Wild Strikes", additional_info = "[q]While you are in Cat Form, Bear Form, or Dire Bear Form, party or raid members within 100 yards gain increased combat ferocity. Each melee hit has a 20% chance of granting the attacker an extra attack with 20% additional Attack Power. No effect if the target is already benefitting from Windfury Totem."},
[407988] = {name = "Savage Roar", additional_info = "{25 Energy} {/ 1 to 5 Combo Points 100 yd range}\nInstant\n[q]Requires Cat Form\n Finishing move that increases Physical damage done by 30% while in Cat Form. Lasts longer per combo point:\n 1 point : (14 + 0 ) seconds\n 2 points: (19 + 0 ) seconds\n 3 points: (24 + 0 ) seconds\n 4 points: (29 + 0 ) seconds\n 5 points: (34 + 0 ) seconds"},
[407989] = {name = "Savage Roar", additional_info = "Instant\nRequires Cat Form\n[q]Finishing move that increases physical damage done by 30%. Lasts longer per combo point:\n 1 point : 14 seconds\n 2 points: 19 seconds\n 3 points: 24 seconds\n 4 points: 29 seconds\n 5 points: 34 seconds"},
[407995] = {name = "Primal Bite", additional_info = "{20 Rage} {Melee Range}\n{Instant} {6 sec cooldown}\nRequires Bear Form, Dire Bear Form\n[q]Bite the target, dealing 100% normal damage plus 26 and generating a high amount of threat."},
[408013] = {name = "Blackfathom Elite Spawner", additional_info = nil},
[408014] = {name = "Spawn Blackfathom Elite", additional_info = nil},
[408024] = {name = "Survival Instincts", additional_info = "{Instant} {3 min cooldown}\n[q]When activated, this grants you 30% of your maximum health and increases all non-Physical healing you deal by 20% for 20 sec. After the effect expires, the health is lost. Useable in all forms except Moonkin Form.\n\n In addition, you regenerate 3 rage every time you dodge while in Bear Form or Dire Bear Form, 10 energy while in Cat Form, or 1% of your maximum mana while in any other form."},
[408025] = {name = "Survival Instincts", additional_info = nil},
[408035] = {name = "Damien Kane - Trade Souls for Rune", additional_info = nil},
[408120] = {name = "Wild Growth", additional_info = "{550 Mana} {40 yd range}\n{Instant} {6 sec cooldown}\n[q]Heals the target and their party for 336 over 7 sec. Party members must be within 43.5 yards of target. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration."},
[408124] = {name = "Lifebloom", additional_info = "{14% of base mana} {40 yd range}\nInstant\n[q]Heals the target for [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] over 7 sec. When Lifebloom completes its duration or is dispelled, the target instantly heals for [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] and the Druid regains half the cost of the spell. This effect can stack up to 3 times on the same target.\n(2s cooldown)"},
[408245] = {name = "Lifebloom", additional_info = "40 yd range\nInstant\n[q]Heals the target over 7 sec. When Lifebloom completes its duration or is dispelled, the target instantly heals. This effect can stack up to 3 times on the same target."},
[408246] = {name = "Lifebloom", additional_info = "Instant\n[q]Gaining mana when Lifebloom expires."},
[408247] = {name = "Nourish", additional_info = "{26% of base mana} {40 yd range}\n2 sec cast\n[q]Heals a friendly target for [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] to [189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)]. Heals for an additional 20% if you have a Rejuvenation, Regrowth, Lifebloom, or Wild Growth effect active on the target. This spell benefits from and triggers all effects associated with Healing Touch or Regrowth."},
[408248] = {name = "Eclipse", additional_info = "[q]Your Wrath spell reduces the cast time of your next 2 Starfire spells by 0.03 sec. Stores up to 4 charges. Lasts 15 sec."},
[408255] = {name = "Eclipse", additional_info = nil},
[408258] = {name = "Dreamstate", additional_info = "[q]Your damaging non-periodic spell critical strikes grant you 50% of your mana regeneration while casting for 8 sec."},
[408261] = {name = "Dreamstate", additional_info = "Instant\n[q]Allows 50% of your Mana regeneration to continue while casting."},
[408307] = {name = "Nature's Fury", additional_info = "{Instant} {2 min cooldown}\n[q]Increases your healing power by 90% of your Nature spell damage for 30 sec."},
[408309] = {name = "Grace of Elune", additional_info = "{Instant} {2 min cooldown}\n[q]Increases your spell damage by 55% of the difference between your healing power and spell damage. Lasts 30 sec."},
[408339] = {name = "Fire Nova", additional_info = "[q]Your Fire Nova Totem spell is replaced with Fire Nova, which causes your current Fire totem to emit damage at its location."},
