[408481] = {name = "Chain Lightning", additional_info = "30 yd range\nInstant\n[q]Hurls a lightning bolt at the enemy, dealing 51 to 58 Nature damage and then jumping to additional nearby enemies. Each jump reduces the damage by 30%. Affects 3 total targets."},
