[408490] = {name = "Lava Burst", additional_info = "{165 Mana} {30 yd range}\n{2.5 sec cast} {10 sec cooldown}\n[q]You hurl molten lava at the target, dealing 150 to 192 Fire damage. If your Flame Shock is on the target, Lava Burst deals 20% increased damage."},
[408491] = {name = "Lava Burst", additional_info = "30 yd range\nInstant\n[q]You hurl molten lava at the target, dealing 50 to 64 Fire damage. If your Flame Shock is on the target, Lava Burst deals 20% increased damage."},
[408496] = {name = "Dual Wield Specialization", additional_info = "[q]Increases your chance to hit with both spells and melee attacks by 5% while dual wielding, your Stormstrike ability now hits with both weapons while dual wielding, and increases the damage done by your offhand weapon by 60%."},
[408498] = {name = "Maelstrom Weapon", additional_info = "[q]When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 20%. Stacks up to 5 times. Lasts 30 sec."},
[408501] = {name = "Maelstrom Ready!", additional_info = nil},
[408505] = {name = "Maelstrom Weapon", additional_info = "Instant\n[q]Reduces the cast time and Mana cost of your next Lightning Bolt spell.\n[q]Modifies Cast Time -19%:\nLightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt\n\nModifies Power Cost -19%:\nLightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt , Lightning Bolt"},
[408507] = {name = "Lava Lash", additional_info = "{1% of base mana} {Melee Range}\n{Instant} {6 sec cooldown}\nRequires Melee Weapon\n[q]You charge your off-hand weapon with lava, instantly dealing 100% off-hand Weapon damage. Damage is increased by 100% if your off-hand weapon is enchanted with Flametongue."},
[408510] = {name = "Water Shield", additional_info = "{Instant} {15 sec cooldown}\n[q]The caster is surrounded by 3 globes of water. When a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, 2% of maximum mana is restored to the caster, expending one water globe. Only one globe will activate every few seconds. Lasts 10 min.\n\n Only one Elemental Shield can be active on the Shaman at any one time.\n(3.5s cooldown)"},
[408511] = {name = "Water Shield", additional_info = "Instant\n[q]Gaining mana when hit while Water Shield is active."},
[408514] = {name = "Earth Shield", additional_info = "{5% of base mana} {40 yd range}\nInstant\n[q]Protects the target with an earthen shield, reducing casting or channeling time lost when damaged by 30% and causing attacks to heal the shielded target for [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100]. This effect can only occur once every few seconds. 9 charges. Lasts 10 min. Earth Shield can only be placed on one target at a time.\n(3.5s cooldown)"},
[408519] = {name = "Earth Shield", additional_info = "Unlimited range\nInstant\n[q]Healed by Earth Shield."},
[408521] = {name = "Riptide", additional_info = "{245 Mana} {40 yd range}\n{Instant} {6 sec cooldown}\n[q]Heals a friendly target for 486 to 534, an additional 445 over 15 sec, and increases the effectiveness of your Chain Heal casts directly on that target by 25%."},
[408524] = {name = "Shield Mastery", additional_info = "[q]Each time you Block, you regenerate mana equal to 8% of your maximum mana and you gain Armor equal to 30% of your shield's armor value, stacking up to 5 times. You also always gain 10% increased chance to Block and 15% increased Block value.\n\n In addition, each time you use a Shock ability, you gain 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec."},
[408525] = {name = "Shield Mastery", additional_info = "Instant\n[q]Increases armor by 30% of your shield's Armor value for 15 sec, stacking up to 7 times."},
[408531] = {name = "Way of Earth", additional_info = "[q]While Rockbiter Weapon is active on your main hand weapon and you have a shield equipped, you deal 65% increased threat, gain 30% increased health, take 10% reduced damage, gain 6% reduced chance to be critically hit by melee attacks, and Earth Shock taunts targets to attack you and has a separate cooldown from other Shock spells but has its range reduced to melee range. However, the range of your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells is reduced by 20 yards."},
[408680] = {name = "Way of Earth", additional_info = "Instant\n[q]While Rockbiter Weapon is active on your main hand weapon, you deal 65% increased threat, gain 30% increased health, take 10% reduced damage, gain 6% reduced chance to be critically hit by melee attacks, and Earth Shock taunts targets to attack you and has a separate cooldown from other Shock spells."},
[408681] = {name = "Earth Shock", additional_info = "{30 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Instantly shocks the target with concussive force, causing 22 to 24 Nature damage. It also interrupts spellcasting and prevents any spell in that school from being cast for 2 sec. Causes a high amount of threat and taunts the target."},
[408683] = {name = "Earth Shock", additional_info = "{50 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Instantly shocks the target with concussive force, causing 41 to 43 Nature damage. It also interrupts spellcasting and prevents any spell in that school from being cast for 2 sec. Causes a high amount of threat and taunts the target."},
[408685] = {name = "Earth Shock", additional_info = "{85 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Instantly shocks the target with concussive force, causing 79 to 83 Nature damage. It also interrupts spellcasting and prevents any spell in that school from being cast for 2 sec. Causes a high amount of threat and taunts the target."},
[408687] = {name = "Earth Shock", additional_info = "{145 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Instantly shocks the target with concussive force, causing 160 to 168 Nature damage. It also interrupts spellcasting and prevents any spell in that school from being cast for 2 sec. Causes a high amount of threat and taunts the target."},
[408688] = {name = "Earth Shock", additional_info = "{240 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\n[q]Instantly shocks the target with concussive force, causing 307 to 321 Nature damage. It also interrupts spellcasting and prevents any spell in that school from being cast for 2 sec. Causes a high amount of threat and taunts the target."},
