[409428] = {name = "Master Marksman", additional_info = "[q]Increases your critical strike chance by 5%, and reduces the Mana cost of all your Shot abilities by 25%."},
[409433] = {name = "Chimera Shot", additional_info = "{6% of base mana} {8 - 35 yd range}\n6 sec cooldown\nRequires Ranged Weapon\n[q]You deal 135% weapon damage, refreshing the current Sting on your target and triggering an effect:\n\n Serpent Sting - Instantly deals 48% of the damage done by your Serpent Sting.\n\n Viper Sting - Instantly restores mana to you equal to 60% of the total amount drained by your Viper Sting.\n\n Scorpid Sting - Attempts to Disarm the target for 10 sec. This effect cannot occur more than once per 1 minute."},
[409493] = {name = "Chimera Shot - Serpent", additional_info = "100 yd range\n[q]You deal 135% weapon damage, refreshing the current Sting on your target and triggering an effect:\n\n Serpent Sting - Instantly deals 48% of the damage done by your Serpent Sting.\n\n Viper Sting - Instantly restores mana to you equal to 60% of the total amount drained by your Viper Sting.\n\n Scorpid Sting - Attempts to Disarm the target for 10 sec. This effect cannot occur more than once per 1 minute."},
[409494] = {name = "Chimera Shot - Viper", additional_info = "100 yd range\n[q]You deal 135% weapon damage, refreshing the current Sting on your target and triggering an effect:\n\n Serpent Sting - Instantly deals 48% of the damage done by your Serpent Sting.\n\n Viper Sting - Instantly restores mana to you equal to 60% of the total amount drained by your Viper Sting.\n\n Scorpid Sting - Attempts to Disarm the target for 10 sec. This effect cannot occur more than once per 1 minute."},
[409495] = {name = "Chimera Shot - Scorpid", additional_info = "100 yd range\n[q]You deal 135% weapon damage, refreshing the current Sting on your target and triggering an effect:\n\n Serpent Sting - Instantly deals 48% of the damage done by your Serpent Sting.\n\n Viper Sting - Instantly restores mana to you equal to 60% of the total amount drained by your Viper Sting.\n\n Scorpid Sting - Attempts to Disarm the target for 10 sec. This effect cannot occur more than once per 1 minute."},
[409504] = {name = "Expose Weakness", additional_info = "[q]Your melee and ranged criticals increase your attack power by 40% of your current Agility for 7 sec."},
[409507] = {name = "Expose Weakness", additional_info = "Instant\n[q]Your ranged criticals increase your attack power by 40% of your Agility for 7 sec."},
[409580] = {name = "Heart of the Lion", additional_info = "8% of base mana\nInstant\n[q]The hunter invokes the heart of a lion, increasing total stats by 10% and Attack Power by 280 for all nearby allies, and increasing total stats for the Hunter by an additional 10%."},
[409583] = {name = "Heart of the Lion", additional_info = "100 yd range\nInstant\n[q]The hunter invokes the heart of a lion, increasing total stats by 10% for all nearby allies, and increasing total stats for the Hunter by an additional 10%."},
[409593] = {name = "Kill Shot", additional_info = "{3% of base mana} {35 yd range}\n12 sec cooldown\nRequires Ranged Weapon\n[q]You attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health."},
[409687] = {name = "Dual Wield Specialization", additional_info = "[q]Increases the damage done by your offhand weapon by 60% and causes your Raptor Strike to strike with both weapons when you are dual-wielding."},
[409691] = {name = "Raptor Strike", additional_info = "Melee Range\nInstant\nRequires Melee Weapon\n[q]A strong attack that increases melee damage by 2 to 3."},
[409693] = {name = "Raptor Strike", additional_info = "Melee Range\nInstant\nRequires Melee Weapon\n[q]A strong attack that increases melee damage by 5."},
