[409750] = {name = "Raptor Strike", additional_info = "Melee Range\nInstant\nRequires Melee Weapon\n[q]A strong attack that increases melee damage by 17."},
[409751] = {name = "Raptor Strike", additional_info = "Melee Range\nInstant\nRequires Melee Weapon\n[q]A strong attack that increases melee damage by 25."},
