[409918] = {name = "Inspiration (Judgement)", additional_info = nil},
[409920] = {name = "Learn Relic (Judgement)", additional_info = nil},
[409922] = {name = "Hammer of the Righteous", additional_info = "[q]Gain the Hammer of the Righteous ability:\n\n\nHammer the current target and up to 3 additional nearby targets, causing Holy damage to each equal to 3 times the damage per second of your main hand weapon. Cooldown shared with Crusader Strike."},
[409924] = {name = "Divine Storm", additional_info = "[q]Gain the Divine Storm ability:\n\n\nAn instant weapon attack that causes 110% of weapon damage to up to 4 enemies within 8 yards. The Divine Storm heals up to 3 party or raid members totaling 25% of the damage caused."},
[409925] = {name = "Divine Light", additional_info = "[q]Gain the Divine Light ability:\n\n\nHeals a friendly target for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100] to [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100]. 50% of any excess healing on the target is converted into an absorption shield that lasts 15 sec. Multiple casts of Divine Light do not accumulate this shield.\n\n Divine Light benefits from all talents and effects that trigger from or modify Holy Light."},
[409930] = {name = "Libram of Judgement", additional_info = nil},
[409932] = {name = "Aura Mastery", additional_info = "[q]Gain the Aura Mastery ability:"},
[409933] = {name = "Avenger's Shield", additional_info = "[q]Gain the Avenger's Shield ability:"},
[409934] = {name = "Avenging Wrath", additional_info = "[q]Gain the Avenging Wrath ability:\n\n\nIncreases all damage and healing caused by 20% for 20 sec. Causes Forbearance and cannot be used while Forebearance is active."},
[409935] = {name = "Hand of Sacrifice", additional_info = "[q]Gain the Hand of Sacrifice ability:\n\n\nCauses target party or raid member to transfer 30% of damage taken to the caster. Lasts 12 sec or until the caster has transferred 100% of their maximum health."},
[409936] = {name = "Inspiration Exemplar", additional_info = "[q]Gain the Inspiration Exemplar\n ability:\n\n\nYour inspiring presence periodically dispels Fear and Sleep effects on nearby party members."},
[409938] = {name = "Fire Nova", additional_info = "[q]Gain the Fire Nova ability, replacing your Fire Nova Totem:\n\n\nYour Fire Nova Totem spell is replaced with Fire Nova, which causes your current Fire totem to emit damage at its location."},
[409940] = {name = "Dual Wield Specialization", additional_info = "[q]Gain the Dual Wield Specialization ability:\n\n\nIncreases your chance to hit with both spells and melee attacks by 5% while dual wielding, your Stormstrike ability now hits with both weapons while dual wielding, and increases the damage done by your offhand weapon by 60%."},
[409941] = {name = "Water Shield", additional_info = "[q]Gain the Water Shield ability:\n\n\nThe caster is surrounded by 3 globes of water. When a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, 2% of maximum mana is restored to the caster, expending one water globe. Only one globe will activate every few seconds. Lasts 10 min.\n\n Only one Elemental Shield can be active on the Shaman at any one time."},
[409943] = {name = "Shield Mastery", additional_info = "[q]Gain the Shield Mastery ability:\n\n\nEach time you Block, you regenerate mana equal to 8% of your maximum mana and you gain Armor equal to 30% of your shield's armor value, stacking up to 5 times. You also always gain 10% increased chance to Block and 15% increased Block value.\n\n In addition, each time you use a Shock ability, you gain 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec."},
[409944] = {name = "Ancestral Guidance", additional_info = "[q]Gain the Ancestral Guidance ability:\n\n\nFor the next 10 sec, 25% of your damage is converted to healing on up to 3 nearby party members, and 100% of your healing is converted to damage on your most recent Flame Shock target."},
[409945] = {name = "Overload", additional_info = "[q]Gain the Overload ability:\n\n\nGives your Lightning Bolt and Chain Lightning spells a 30% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat."},
[409946] = {name = "Maelstrom Weapon", additional_info = "[q]Gain the Maelstrom Weapon ability:\n\n\nWhen you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 20%. Stacks up to 5 times. Lasts 30 sec."},
[409947] = {name = "Earth Shield", additional_info = "[q]Gain the Earth Shield ability:\n\n\nProtects the target with an earthen shield, reducing casting or channeling time lost when damaged by 30% and causing attacks to heal the shielded target for [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100]. This effect can only occur once every few seconds. 9 charges. Lasts 10 min. Earth Shield can only be placed on one target at a time."},
[409951] = {name = "Spirit of the Alpha", additional_info = "[q]Gain the Spirit of the Alpha ability:\n\n\nInfuses the target with the spirit of an alpha wolf, increasing all threat generated by the target by 45% for 30 min. Limit 1 target. If cast on a target other than self, the Shaman also gains Loyal Beta, increasing Physical damage done by 5% and reducing all threat generated by 30% for 30 min. A target cannot have both Spirit of the Alpha and Loyal Beta at the same time."},
[409952] = {name = "Lava Burst", additional_info = "[q]Gain the Lava Burst ability:\n\n\nYou hurl molten lava at the target, dealing 150 to 192 Fire damage. If your Flame Shock is on the target, Lava Burst deals 20% increased damage."},
[409953] = {name = "Lava Lash", additional_info = "[q]Gain the Lava Lash ability:\n\n\nYou charge your off-hand weapon with lava, instantly dealing 100% off-hand Weapon damage. Damage is increased by 100% if your off-hand weapon is enchanted with Flametongue."},
[409954] = {name = "Riptide", additional_info = "[q]Gain the Riptide ability:\n\n\nHeals a friendly target for 486 to 534, an additional 445 over 15 sec, and increases the effectiveness of your Chain Heal casts directly on that target by 25%."},
[409955] = {name = "Way of Earth", additional_info = "[q]Gain the Way of Earth ability:\n\n\nWhile Rockbiter Weapon is active on your main hand weapon and you have a shield equipped, you deal 65% increased threat, gain 30% increased health, take 10% reduced damage, gain 6% reduced chance to be critically hit by melee attacks, and Earth Shock taunts targets to attack you and has a separate cooldown from other Shock spells but has its range reduced to melee range. However, the range of your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells is reduced by 20 yards."},
[409957] = {name = "Steady Shot", additional_info = "[q]Gain the Steady Shot ability:\n\n\nA steady shot that causes 100% ranged weapon damage."},
[409958] = {name = "Master Marksman", additional_info = "[q]Gain the Master Marksman ability:\n\n\nIncreases your critical strike chance by 5%, and reduces the Mana cost of all your Shot abilities by 25%."},
[409959] = {name = "Expose Weakness", additional_info = "[q]Gain the Expose Weakness ability:\n\n\nYour melee and ranged criticals increase your attack power by 40% of your current Agility for 7 sec."},
[409960] = {name = "Cobra Slayer", additional_info = "[q]Gain the Cobra Slayer ability:\n\n\nMongoose Bite now has a 10% chance to activate on each of your melee attacks, a 100% chance when an enemy dodges. This chance accumulates, with the chance rising by 10% from each subsequent attack if it does not reset. Mongoose Bite also deals additional damage equal to 45% of your Attack Power."},
[409961] = {name = "Dual Wield Specialization", additional_info = "[q]Gain the Dual Wield Specialist ability:\n\n\nIncreases the damage done by your offhand weapon by 60% and causes your Raptor Strike to strike with both weapons when you are dual-wielding."},
[409962] = {name = "Beast Mastery", additional_info = "[q]Gain the Beast Mastery ability:\n\n\nYour pet's damage and health are increased by 15%, and its Focus regeneration by 50%. In addition, your pet's Growl now also Taunts the target to attack it for 3 sec."},
[409963] = {name = "Summon Spirit", additional_info = nil},
[409968] = {name = "Trap Launcher", additional_info = "[q]Gain the Trap Launcher ability:"},
[409974] = {name = "Kill Shot", additional_info = "[q]Gain the Kill Shot ability:\n\n\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health."},
[409976] = {name = "Chimera Shot", additional_info = "[q]Gain the Chimera Shot ability:\n\n\n You deal 135% weapon damage, refreshing the current Sting on your target and triggering an effect:\n\n Serpent Sting - Instantly deals 48% of the damage done by your Serpent Sting.\n\n Viper Sting - Instantly restores mana to you equal to 60% of the total amount drained by your Viper Sting.\n\n Scorpid Sting - Attempts to Disarm the target for 10 sec. This effect cannot occur more than once per 1 minute."},
[409979] = {name = "Lone Wolf", additional_info = "[q]Gain the Lone Wolf ability:\n\n\nYou deal 20% increased damage with all attacks while you do not have an active pet."},
[409988] = {name = "Force Player Cast Delayed Banish", additional_info = nil},
[409999] = {name = "Engrave Gloves - Beacon of Light", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Beacon of Light rune:"},
[410001] = {name = "Engrave Gloves - Hand of Reckoning", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Hand of Reckoning rune:"},
[410002] = {name = "Engrave Gloves - Crusader Strike", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Crusader Strike rune:"},
[410005] = {name = "Engrave Pants - Aura Mastery", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Aura Mastery rune:"},
[410008] = {name = "Engrave Pants - Avenger's Shield", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Avenger's Shield rune:"},
[410010] = {name = "Engrave Pants - Hand of Sacrifice", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Hand of Sacrifice rune:\n\n\nCauses target party or raid member to transfer 30% of damage taken to the caster. Lasts 12 sec or until the caster has transferred 100% of their maximum health."},
[410011] = {name = "Engrave Pants - Inspiration Exemplar", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Inspiration Exemplar rune:\n\n\nYour inspiring presence periodically dispels Fear and Sleep effects on nearby party members."},
[410013] = {name = "Engrave Bracers - Hammer of the Righteous", additional_info = "3 sec cast\nRequires Bracers\n[q]Engrave your bracers with the Hammer of the Righteous rune:\n\n\nHammer the current target and up to 3 additional nearby targets, causing Holy damage to each equal to 3 times the damage per second of your main hand weapon. Cooldown shared with Crusader Strike."},
[410014] = {name = "Engrave Chest - Divine Storm", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest with the Divine Storm rune:\n\n\nAn instant weapon attack that causes 110% of weapon damage to up to 4 enemies within 8 yards. The Divine Storm heals up to 3 party or raid members totaling 25% of the damage caused."},
[410015] = {name = "Engrave Cloak - Divine Light", additional_info = "3 sec cast\nRequires Cloak\n[q]Engrave your cloak with the Divine Light rune:\n\n\nHeals a friendly target for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100] to [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100]. 50% of any excess healing on the target is converted into an absorption shield that lasts 15 sec. Multiple casts of Divine Light do not accumulate this shield.\n\n Divine Light benefits from all talents and effects that trigger from or modify Holy Light."},
[410021] = {name = "Engrave Chest - Wild Strikes", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Wild Strikes rune:\n\n\nWhile you are in Cat Form, Bear Form, or Dire Bear Form, party or raid members within 100 yards gain increased combat ferocity. Each melee hit has a 20% chance of granting the attacker an extra attack with 20% additional Attack Power. No effect if the target is already benefitting from Windfury Totem."},
[410023] = {name = "Engrave Pants - Savage Roar", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Savage Roar rune:\n\n\nRequires Cat Form\n Finishing move that increases Physical damage done by 30% while in Cat Form. Lasts longer per combo point:\n 1 point : (14 + 0 ) seconds\n 2 points: (19 + 0 ) seconds\n 3 points: (24 + 0 ) seconds\n 4 points: (29 + 0 ) seconds\n 5 points: (34 + 0 ) seconds"},
[410025] = {name = "Engrave Gloves - Mangle", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Mangle rune:\n\n\nBite the target, dealing 100% normal damage plus 26 and generating a high amount of threat."},
[410027] = {name = "Engrave Boots - Survival Instincts", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the Survival Instincts rune:\n\n\nWhen activated, this grants you 30% of your maximum health and increases all non-Physical healing you deal by 20% for 20 sec. After the effect expires, the health is lost. Useable in all forms except Moonkin Form.\n\n In addition, you regenerate 3 rage every time you dodge while in Bear Form or Dire Bear Form, 10 energy while in Cat Form, or 1% of your maximum mana while in any other form."},
[410028] = {name = "Engrave Gloves - Wild Growth", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Wild Growth rune:\n\n\nHeals the target and their party for 336 over 7 sec. Party members must be within 43.5 yards of target. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration."},
[410029] = {name = "Engrave Belt - Eclipse", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Eclipse rune:\n\n\nYour Wrath spell reduces the cast time of your next 2 Starfire spells by 0.03 sec. Stores up to 4 charges. Lasts 15 sec."},
[410033] = {name = "Engrave Pants - Lifebloom", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Lifebloom rune:\n\nReduces the global cooldown on your Rejuvenation and Lifebloom abilities by 0.5 sec and you gain the Lifebloom ability:\n\n\nHeals the target for [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] over 7 sec. When Lifebloom completes its duration or is dispelled, the target instantly heals for [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] and the Druid regains half the cost of the spell. This effect can stack up to 3 times on the same target."},
[410059] = {name = "Engrave Belt - Nourish", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Nourish rune:\n\n\nHeals a friendly target for [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] to [189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)]. Heals for an additional 20% if you have a Rejuvenation, Regrowth, Lifebloom, or Wild Growth effect active on the target. This spell benefits from and triggers all effects associated with Healing Touch or Regrowth."},
[410060] = {name = "Engrave Boots - Dreamstate", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the Dreamstate rune:\n\n\nYour damaging non-periodic spell critical strikes grant you 50% of your mana regeneration while casting for 8 sec."},
[410061] = {name = "Engrave Chest - Fury of Stormrage", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Fury of Stormrage rune:\n\n\nReduces the mana cost of Wrath by 100% and each time you deal damage with Wrath you have a 12% chance for your next cast of Healing Touch within 15 sec to be instant and castable in any shapeshift form. Allows Wrath to be cast while in Tree of Life form."},
[410093] = {name = "Engrave Belt - Fire Nova", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Fire Nova rune:\n\n\nYour Fire Nova Totem spell is replaced with Fire Nova, which causes your current Fire totem to emit damage at its location."},
[410094] = {name = "Engrave Chest - Overload", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Overload rune:\n\n\nGives your Lightning Bolt and Chain Lightning spells a 30% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat."},
[410095] = {name = "Engrave Gloves - Lava Burst", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Lava Burst rune:\n\n\nYou hurl molten lava at the target, dealing 150 to 192 Fire damage. If your Flame Shock is on the target, Lava Burst deals 20% increased damage."},
[410096] = {name = "Engrave Chest - Dual Wield Specialization", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Dual Wield Specialization rune:\n\n\nIncreases your chance to hit with both spells and melee attacks by 5% while dual wielding, your Stormstrike ability now hits with both weapons while dual wielding, and increases the damage done by your offhand weapon by 60%."},
[410097] = {name = "Engrave Gloves - Water Shield", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Water Shield rune:\n\n\nThe caster is surrounded by 3 globes of water. When a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, 2% of maximum mana is restored to the caster, expending one water globe. Only one globe will activate every few seconds. Lasts 10 min.\n\n Only one Elemental Shield can be active on the Shaman at any one time."},
[410098] = {name = "Engrave Chest - Shield Mastery", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Shield Mastery rune:\n\n\nEach time you Block, you regenerate mana equal to 8% of your maximum mana and you gain Armor equal to 30% of your shield's armor value, stacking up to 5 times. You also always gain 10% increased chance to Block and 15% increased Block value.\n\n In addition, each time you use a Shock ability, you gain 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec."},
