[415068] = {name = "Exorcism", additional_info = "{85 Mana} {30 yd range}\n{Instant} {15 sec cooldown}\n[q]Causes 114 to 126 Holy damage to an enemy target and has 100% chance to crit against Demons and Undead."},
[415069] = {name = "Exorcism", additional_info = "{135 Mana} {30 yd range}\n{Instant} {15 sec cooldown}\n[q]Causes 205 to 225 Holy damage to an enemy target and has 100% chance to crit against Demons and Undead."},
