[415096] = {name = "Coherence", additional_info = "[q]Causes your Chain heal effectiveness to only reduce by 35% per jump, and Chain Lightning effectiveness to only reduce by 20% per jump. Each also jumps to 1 additional target."},
[415100] = {name = "Power Surge", additional_info = "[q]Each time Flame Shock deals damage, it has a 5% chance to reset the cooldown on Lava Burst and Chain Lightning and make your next Lava Burst or Chain Lightning within 10 sec instant. Each time Riptide heals, it has a 5% chance to make your next Chain Heal within 10 sec instant. Additionally, every 5 sec you gain mana equal to 15% of your Intellect.\n(Proc chance: 5%)"},
[415105] = {name = "Power Surge", additional_info = "Instant\n[q]Modifies Cast Time -99%:\nChain Lightning , Chain Lightning , Chain Lightning , Chain Lightning , Chain Lightning , Chain Lightning , Chain Lightning , Chain Lightning , Lava Burst , Lava Burst , Lava Burst , Lava Burst , Lava Burst , Lava Burst"},
