[415231] = {name = "Burn", additional_info = "[q]Your Flame Shock now strikes up to 5 targets, gains 6 sec increased duration, and deals 100% increased damage. In addition, while you have Flametongue Weapon imbued on your main hand equipped weapon, you gain increased spell damage equal to 150% of your Intellect."},
[415233] = {name = "Ghost Wolf", additional_info = "100 Mana\n3 sec cast\n[q]Turns the Shaman into a Ghost Wolf, increasing speed by 40% and decreasing all damage taken by 10%."},
[415236] = {name = "Healing Rain", additional_info = "{21% of base mana} {40 yd range}\n{2 sec cast} {10 sec cooldown}\n[q]Selects the area 15 yards around target player, and heals all of target player's party members within that area for [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100] every second."},
[415240] = {name = "Healing Rain", additional_info = nil},
[415242] = {name = "Healing Rain", additional_info = "100 yd range\nInstant\n[q]Heals up to 5 friendly party or raid members within 15 yards of the target for [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100]."},
[415292] = {name = "Earthliving", additional_info = "100 yd range\nInstant\n[q]Heals [16 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 4] over 12 sec sec."},
[415320] = {name = "Flanking Strike", additional_info = "{1.5% of base mana} {Melee Range}\n{Instant} {30 sec cooldown}\nRequires Melee Weapon\n[q]You and your pet deal simultaneous instant 100% melee damage. Afterward, you deal 8% increased damage for 10 sec, stacking up to 3 times. Your pet's Basic attacks have a 50% chance to reset the cooldown on Flanking Strike."},
[415326] = {name = "Flanking Strike", additional_info = "Melee Range\nInstant\n[q]You and your pet deal simultaneous instant 100% melee damage. Afterward, your Mongoose Bite and Raptor Strike deal 0% increased damage for until canceled, stacking up to 1 times. Raptor Strike has a 0% chance to reset the cooldown on Flanking Strike."},
[415327] = {name = "Flanking Strike", additional_info = nil},
[415335] = {name = "Raptor Strike", additional_info = "{15 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\nRequires Melee Weapon\n[q]A strong attack that increases melee damage by 5."},
[415336] = {name = "Raptor Strike", additional_info = "{25 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\nRequires Melee Weapon\n[q]A strong attack that increases melee damage by 11."},
[415337] = {name = "Raptor Strike", additional_info = "{35 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\nRequires Melee Weapon\n[q]A strong attack that increases melee damage by 21."},
[415338] = {name = "Raptor Strike", additional_info = "{45 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\nRequires Melee Weapon\n[q]A strong attack that increases melee damage by 34."},
[415340] = {name = "Raptor Strike", additional_info = "{55 Mana} {Melee Range}\n{Instant} {6 sec cooldown}\nRequires Melee Weapon\n[q]A strong attack that increases melee damage by 50."},
