[415352] = {name = "Melee Specialist", additional_info = "[q]Your Raptor Strike is now instant, and Mongoose Bite and Raptor Strike have a 30% chance on each attack to reset the cooldowns of Mongoose Bite and Raptor Strike."},
[415358] = {name = "Raptor Fury", additional_info = "[q]Raptor Strike increases damage done by Raptor Strike and Mongoose Bite by 15% for 30 sec, stacking up to 5 times. Subsequent doses do not extend the duration of this effect."},
[415362] = {name = "Raptor Fury", additional_info = "Instant\n[q]Modifies Damage/Healing Done +16%:\nMongoose Bite , Mongoose Bite , Mongoose Bite , Mongoose Bite , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike"},
[415370] = {name = "Lone Wolf", additional_info = "[q]You deal 20% increased damage with all attacks while you do not have an active pet."},
[415372] = {name = "Lone Wolf", additional_info = nil},
[415399] = {name = "Sniper Training", additional_info = "[q]When you have not moved for the last 1 sec, you have a 20% chance to gain Sniper's Aim, stacking up to 5 times. Sniper's Aim increases the critical strike chance of your Shot abilities by 2%."},
[415401] = {name = "Sniper's Aim", additional_info = "Instant\n[q]Modifies Critical Strike Chance +3:\nAimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Concussive Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Multi-Shot , Scatter Shot , Summon Hawk , Summon Hawk , Summon Hawk , Summon Hawk , Tranquilizing Shot"},
[415405] = {name = "Rapid Killing", additional_info = "[q]Reduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%."},
[415407] = {name = "Rapid Killing", additional_info = "Instant\n[q]Increases the damage of your next Shot ability by 20%."},
[415413] = {name = "Lock and Load", additional_info = "[q]Each time you place a trap, your next Shot (except Scatter Shot) ability within 20 sec costs no mana and does not incur a cooldown."},
[415414] = {name = "Lock and Load", additional_info = "Instant\n[q]Modifies Cooldown -99%:\nAimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Chimera Shot , Chimera Shot - Serpent , Concussive Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Multi-Shot , Tranquilizing Shot\n\nModifies Power Cost -99%:\nAimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Chimera Shot , Chimera Shot - Serpent , Concussive Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Multi-Shot , Tranquilizing Shot"},
[415423] = {name = "Aspect of the Viper", additional_info = "Instant\n[q]The hunter takes on the aspect of the viper, causing your ranged and melee auto attacks to regenerate mana but reducing your total damage done by 10%. In addition, you gain 10% of maximum mana every 3 sec. Mana gained is based on the speed of your weapon. Only one Aspect can be active at a time."},
[415424] = {name = "Aspect of the Viper", additional_info = nil},
[415428] = {name = "Catlike Reflexes", additional_info = "[q]Increases your chance to dodge by 20% and your pet's chance to dodge by 9%. In addition, reduces the cooldown of your Flanking Strike ability by 50%."},
[415429] = {name = "Hunter Pet Scaling", additional_info = "(2s cooldown)"},
[415431] = {name = "Avoidance", additional_info = nil},
[415449] = {name = "Waist Rune Ability", additional_info = "Instant\n[q]Equip a Waist slot item with a Rune engraved to activate an ability in this slot."},
[415450] = {name = "Feet Rune Ability", additional_info = "Instant\n[q]Equip a Feet slot item with a Rune engraved to activate an ability in this slot."},
[415452] = {name = "Improved Swipe", additional_info = "[q]Gain the Improved Swipe ability:\n\n\nWhile in Cat Form, your Swipe ability becomes Swipe (Cat), and while in Bear Form, your Swipe ability strikes up to 7 additional enemies.\n\n Swipe (Cat)\n\nSwipe nearby enemies, inflicting 250% weapon damage and generating 1 combo point on your current target."},
[415457] = {name = "Fan of Knives", additional_info = "[q]Gain the Fan of Knives ability:\n\n\n Instantly throw both weapons at all targets within 8 yards, causing 75% weapon damage with daggers, and 50% weapon damage with all other weapons."},
[415459] = {name = "Spell Power", additional_info = "[q]Gain the Spell Power ability:\n\n\nIncreases critical strike damage bonus of all spells by 50%."},
[415460] = {name = "Burnout", additional_info = "[q]Gain the Burnout ability:\n\n\nIncreases your spell critical strike chance with all spells by 15%, but your non-periodic spell critical strikes now have an additional mana cost of 1% of your base mana."},
[415467] = {name = "Mass Regeneration", additional_info = "[q]Gain the Mass Regeneration ability:\n\n\nHeals all of target player's party members within 43.5 yards of target player for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 42 / 100 * 3] health over 3 sec and applies Temporal Beacon to each target for 15 sec.\n\n Temporal Beacon\n\nRecords the subject's space-time position. 80% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets."},
[415481] = {name = "Pain and Suffering", additional_info = "[q]Gain the Pain and Suffering ability:\n\n\nMind Blast, Mind Spike, and Mind Flay refresh the duration of your one of your Shadow Word: Pain, Void Plague, or Vampiric Touch abilities on the target back to its maximum duration. The ability with the shortest remaining duration will always be the one refreshed."},
[415596] = {name = "Shield Mastery", additional_info = "[q]Gain the Shield Mastery ability:"},
[415598] = {name = "Gladiator Stance", additional_info = "[q]Gain the Gladiator Stance ability:\n\n\nAn aggressive stance that increases damage while you are wearing a shield by 10% and increases block chance by 10%, but reduces armor by 30% and threat generated by 30%. In addition, you gain 50% increased Rage when your auto-attack damages an enemy not targeting you.\n\n While wearing a shield in Gladiator Stance, you may use all abilities that are restricted to other stances."},
[415599] = {name = "Single-Minded Fury", additional_info = "[q]Gain the Single-Minded Fury ability:\n\n\nWhile dual-wielding, your movement speed is increased by 10% and you gain 3% attack speed each time your melee auto-attack strikes the same target as your previous auto-attack, stacking up to 5 times. Lasts 10 sec or until your auto-attack strikes a different target."},
[415604] = {name = "Everlasting Affliction", additional_info = "[q]Gain the Everlasting Affliction ability:\n\n\nEach time your Drain Life, Drain Soul, or Shadowbolt spell deals damage, your Corruption on the target is refreshed to its maximum duration."},
[415605] = {name = "Demonic Tactics", additional_info = "[q]Gain the Demonic Tactics ability:\n\n\nIncreases the critical strike chance of all attacks for you and your summoned Demon by 10% while the Demon is active."},
[415703] = {name = "Sacred Shield", additional_info = "[q]Gain the Sacred Shield ability:\n\n\nEach time the target takes damage they gain a Sacred Shield, absorbing [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] damage and increasing the Paladin's chance to critically hit with Flash of Light by 50% for up to 6 sec. In addition, causes your Flash of Light to heal targets with Sacred Shield for an additional 100% over 12 sec. They cannot gain this effect more than once every 6 sec. Lasts 1 min. This spell cannot be on more than one target at any one time."},
[415706] = {name = "The Art of War", additional_info = "[q]Gain the The Art of War ability:\n\n\nIncreases all Holy damage you deal by 10%, and your melee and spell critical strikes reduce the remaining cooldown on your Exorcism spell by 2 sec."},
[415709] = {name = "Survival of the Fittest", additional_info = "[q]Gain the Survival of the Fittest ability:\n\n\nReduces the chance you'll be critically hit by melee attacks by 6% and reduces all damage taken by 10%. Damage taken reduced by an additional 10% while in Bear Form or Dire Bear Form."},
[415712] = {name = "Power Surge", additional_info = "[q]Gain the Power Surge ability:\n\n\nEach time Flame Shock deals damage, it has a 5% chance to reset the cooldown on Lava Burst and Chain Lightning and make your next Lava Burst or Chain Lightning within 10 sec instant. Each time Riptide heals, it has a 5% chance to make your next Chain Heal within 10 sec instant. Additionally, every 5 sec you gain mana equal to 15% of your Intellect."},
[415713] = {name = "Mental Dexterity", additional_info = "[q]Gain the Mental Dexterity ability:\n\n\nIncreases your Attack Power by an amount equal to 100% of your Intellect."},
[415714] = {name = "Healing Rain", additional_info = "[q]Gain the Healing Rain ability:\n\n\nSelects the area 15 yards around target player, and heals all of target player's party members within that area for [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100] every second."},
[415717] = {name = "Catlike Reflexes", additional_info = "[q]Gain the Catlike Reflexes ability:\n\n\nIncreases your chance to dodge by 20% and your pet's chance to dodge by 9%. In addition, reduces the cooldown of your Flanking Strike ability by 50%."},
[415718] = {name = "Aspect of the Viper", additional_info = "[q]Gain the Aspect of the Viper ability:\n\n\nThe hunter takes on the aspect of the viper, causing your ranged and melee auto attacks to regenerate mana but reducing your total damage done by 10%. In addition, you gain 10% of maximum mana every 3 sec. Mana gained is based on the speed of your weapon. Only one Aspect can be active at a time."},
[415719] = {name = "Lock and Load", additional_info = "[q]Gain the Lock and Load ability:\n\n\nEach time you place a trap, your next Shot (except Scatter Shot) ability within 20 sec costs no mana and does not incur a cooldown."},
[415720] = {name = "Kill Shot", additional_info = "[q]Gain the Kill Shot ability:\n\n\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health."},
[415723] = {name = "Melee Specialist", additional_info = "[q]Gain the Melee Specialist ability:\n\n\nYour Raptor Strike is now instant, and Mongoose Bite and Raptor Strike have a 30% chance on each attack to reset the cooldowns of Mongoose Bite and Raptor Strike."},
[415725] = {name = "Waylay", additional_info = "[q]Gain the Waylay ability:\n\n\nYour Ambush and Backstab hits unbalance your target, increasing the time between their melee attacks by 10%, and reducing movement speed by 50% for 8 sec."},
[415729] = {name = "Enlightenment", additional_info = "[q]Gain the Enlightenment ability:\n\n\nYou deal 10% more damage while you have more than 70% mana. While below 30% mana 10% of your mana regeneration continues while casting."},
[415734] = {name = "Spellfrost Bolt", additional_info = "[q]Gain the Spellfrost Bolt ability:\n\n\nLaunches a bolt of spellfrost at the enemy, causing [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 305 / 100 * 1 ] to [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 355 / 100 * 1 ] Spellfrost damage and slowing movement speed by 40% for 9 sec. This spell will be checked against the lower of the target's Frost and Arcane resists and counts as both Frost and Arcane damage."},
[415737] = {name = "Serendipity", additional_info = "[q]Gain the Serendipity ability:\n\n\nHealing with Flash Heal reduces the cast time of your next Lesser Heal, Heal, Greater Heal, or Prayer of Healing by 20% for 20 sec, stacking up to 3 times."},
[415738] = {name = "Mind Sear", additional_info = "[q]Gain the Mind Sear ability:\n\n\nCauses an explosion of shadow magic damaging the enemy target and other nearby enemies, causing [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] to [78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] Shadow damage every 1 sec for 6 sec to all enemies within 10 yards of the target."},
[415739] = {name = "Strength of Soul", additional_info = "[q]Lesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal."},
[415740] = {name = "Strength of Soul", additional_info = "[q]Gain the Strength of Soul ability:\n\n\nLesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal."},
[415743] = {name = "Blood Surge", additional_info = "[q]Gain the Blood Surge ability:\n\n\nHeroic Strike, Bloodthirst, and Whirlwind have a 30% chance to make your next Slam within 15 sec instant, strike with both melee weapons, and cost no Rage."},
[415744] = {name = "Precise Timing", additional_info = "[q]Gain the Precision Timing ability:\n\n\nSlam is now instant but has a 6 sec cooldown."},
[415745] = {name = "Focused Rage", additional_info = "[q]Gain the Focused Rage ability:\n\n\nReduces the Rage cost of your offensive abilities by 3."},
[415749] = {name = "Demonic Knowledge", additional_info = "[q]Gain the Demonic Knowledge ability:\n\n\nIncreases your spell damage and your Demon pet's spell damage by up to 100% of your level while you have a summoned Demon pet active."},
[415750] = {name = "Incinerate", additional_info = "[q]Gain the Incinerate ability:\n\n\nDeals 100 to 114 Fire damage to your target and an additional 25% damage if the target is afflicted by Immolate."},
[415751] = {name = "Dance of the Wicked", additional_info = "[q]Gain the Dance of the Wicked ability:\n\n\nYou and your demon pet gain dodge chance equal to 100% of your spell critical strike chance each time you deal a critical strike to an enemy, and also both regain 2% of maximum mana."},
[415755] = {name = "Guarded by the Light", additional_info = "[q]Gain the Guarded by the Light ability:\n\n\nYou gain 5% of your maximum mana every 3 sec for 15 sec after Blocking a melee attack. This effect is cancelled by casting Flash of Light, Holy Light, or Holy Shock."},
[415756] = {name = "Aura Mastery", additional_info = "[q]Gain the Aura Mastery ability:"},
[415759] = {name = "Skull Bash", additional_info = "[q]Gain the Skull Bash ability:\n\n\nCharge to a target within 13 yards and bash the target's skull, interrupting spellcasting and preventing any spell in that school from being cast for 2 sec. Shares a cooldown with Feral Charge."},
[415760] = {name = "Lacerate", additional_info = "[q]Gain the Lacerate ability:\n\n\nLacerates the enemy target, making them bleed for 50 damage over 15 sec plus 10% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to 5 times on the same target."},
[415761] = {name = "Living Seed", additional_info = "[q]Gain the Living Seed ability:\n\n\nWhen you critically heal your target with any non-periodic healing spell you plant a Living Seed on the target for 50% of the amount healed. The Living Seed will bloom the next time the target takes damage or receives non-periodic healing. Lasts 15 sec."},
[415762] = {name = "Elune's Fires", additional_info = "[q]Gain the Elune's Fires ability:\n\n\nSome of your spells and abilities extend the duration of your damage and healing over time effects on their target:\n\n Starfire extends Moonfire by 6 sec.\n Wrath extends Sunfire by 3 sec.\n Regrowth extends Rejuvenation by 6 sec.\n Shred extends Rip by 2 sec.\n\n Each effect can only be extended up to its initial duration."},
[415768] = {name = "Burn", additional_info = "[q]Gain the Burn ability:\n\n\nYour Flame Shock now strikes up to 5 targets, gains 6 sec increased duration, and deals 100% increased damage. In addition, while you have Flametongue Weapon imbued on your main hand equipped weapon, you gain increased spell damage equal to 150% of your Intellect."},
[415813] = {name = "Greater Ghost Wolf", additional_info = "[q]Your Ghost Wolf ability can now be used indoors, and reduces all damage you take by 10% while active."},
[415816] = {name = "Wyvern Strike", additional_info = "[q]Gain the Wyvern Strike ability:\n\n\nReplaces your Wyvern Sting ability with Wyvern Strike, a vicious strike that deals 140% weapon damage and causes the target to Bleed for damage over time.\n\n Wyvern Strike requires you to have the Wyvern Sting talent, and replaces the Wyvern Sting abilities found in the Survival spellbook."},
[415817] = {name = "Rapid Killing", additional_info = "[q]Gain the Rapid Killing ability:\n\n\nReduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%."},
[415818] = {name = "Sniper Training", additional_info = "[q]Gain the Sniper Training ability:\n\n\nWhen you have not moved for the last 1 sec, you have a 20% chance to gain Sniper's Aim, stacking up to 5 times. Sniper's Aim increases the critical strike chance of your Shot abilities by 2%."},
[415822] = {name = "Raptor Fury", additional_info = "[q]Gain the Raptor Fury ability:\n\n\nRaptor Strike increases damage done by Raptor Strike and Mongoose Bite by 15% for 30 sec, stacking up to 5 times. Subsequent doses do not extend the duration of this effect."},
[415918] = {name = "Engrave Cloak - Crimson Tempest", additional_info = "3 sec cast\nRequires Cloak\n[q]Engrave your cloak with the Crimson Tempest rune:\n\n\nFinishing move that slashes all enemies within 8 yards, causing victims to Bleed over time. Lasts longer and deals more damage per combo point.\n\n 1 point : (Attack Power * 0.30) damage over 4 sec.\n 2 points: (Attack Power * 0.45) damage over 6 sec.\n 3 points: (Attack Power * 0.60) damage over 8 sec.\n 4 points: (Attack Power * 0.75) damage over 10 sec.\n 5 points: (Attack Power * 0.90) damage over 12 sec.\n\n Crimson Tempest benefits from all talents and effects that trigger from or modify Rupture."},
[415922] = {name = "Engrave Cloak - Blunderbuss", additional_info = "3 sec cast\nRequires Cloak\n[q]Engrave your cloak with the Blunderbuss rune:\n\n\nFire a musket blast at up to 4 enemies in a cone in front of you for [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 192 / 100 + 48 / 100 * Attack Power] to [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 288 / 100 + 48 / 100 * Attack Power] Physical damage."},
[415926] = {name = "Engrave Boots - Waylay", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the Waylay rune:\n\n\nYour Ambush and Backstab hits unbalance your target, increasing the time between their melee attacks by 10%, and reducing movement speed by 50% for 8 sec."},
[415934] = {name = "Engrave Boots - Spell Power", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the Spell Power rune:\n\n\nIncreases critical strike damage bonus of all spells by 50%."},
[415936] = {name = "Engrave Gloves - Living Bomb", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Living Bomb rune:\n\n\nThe target becomes a Living Bomb, taking [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 85 / 100 * 4] Fire damage over 12 sec. After 12 sec or when the spell is dispelled, the target explodes dealing [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 171 / 100] Fire damage to all enemies within 10 yards.\n\n Living Bomb benefits from all talents and effects that trigger from or modify Scorch."},
[415939] = {name = "Engrave Pants - Mass Regeneration", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Mass Regeneration rune:\n\n\nHeals all of target player's party members within 43.5 yards of target player for [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 42 / 100 * 3] health over 3 sec and applies Temporal Beacon to each target for 15 sec.\n\n Temporal Beacon\n\nRecords the subject's space-time position. 80% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets."},
[415942] = {name = "Engrave Chest - Enlightenment", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Enlightenment rune:\n\n\nYou deal 10% more damage while you have more than 70% mana. While below 30% mana 10% of your mana regeneration continues while casting."},
[415948] = {name = "Engrave Belt - Spellfrost Bolt", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Spellfrost Bolt rune:\n\n\nLaunches a bolt of spellfrost at the enemy, causing [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 305 / 100 * 1 ] to [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 355 / 100 * 1 ] Spellfrost damage and slowing movement speed by 40% for 9 sec. This spell will be checked against the lower of the target's Frost and Arcane resists and counts as both Frost and Arcane damage."},
[415988] = {name = "Vahi Bonesplitter - Trade Centaur Head For Rune Fragment", additional_info = nil},
[415991] = {name = "Engrave Helm - Pain and Suffering", additional_info = "3 sec cast\nRequires Helms\n[q]Engrave your helm with the Pain and Suffering rune:\n\n\nMind Blast, Mind Spike, and Mind Flay refresh the duration of your one of your Shadow Word: Pain, Void Plague, or Vampiric Touch abilities on the target back to its maximum duration. The ability with the shortest remaining duration will always be the one refreshed."},
[415995] = {name = "Engrave Chest - Serendipity", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Serendipity rune:\n\n\nHealing with Flash Heal reduces the cast time of your next Lesser Heal, Heal, Greater Heal, or Prayer of Healing by 20% for 20 sec, stacking up to 3 times."},
[415996] = {name = "Engrave Gloves - Mind Sear", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Mind Sear rune:\n\n\nCauses an explosion of shadow magic damaging the enemy target and other nearby enemies, causing [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] to [78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] Shadow damage every 1 sec for 6 sec to all enemies within 10 yards of the target."},
[415997] = {name = "Engrave Chest - Strength of Soul", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Strength of Soul rune:\n\n\nLesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal."},
[416002] = {name = "Engrave Boots - Gladiator Stance", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the Gladiator Stance rune:\n\n\nAn aggressive stance that increases damage while you are wearing a shield by 10% and increases block chance by 10%, but reduces armor by 30% and threat generated by 30%. In addition, you gain 50% increased Rage when your auto-attack damages an enemy not targeting you.\n\n While wearing a shield in Gladiator Stance, you may use all abilities that are restricted to other stances."},
[416003] = {name = "Engrave Gloves - Single-Minded Fury", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Single-Minded Fury rune:\n\n\nWhile dual-wielding, your movement speed is increased by 10% and you gain 3% attack speed each time your melee auto-attack strikes the same target as your previous auto-attack, stacking up to 5 times. Lasts 10 sec or until your auto-attack strikes a different target."},
[416004] = {name = "Engrave Belt - Blood Surge", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Blood Surge rune:\n\n\nHeroic Strike, Bloodthirst, and Whirlwind have a 30% chance to make your next Slam within 15 sec instant, strike with both melee weapons, and cost no Rage."},
[416005] = {name = "Engrave Belt - Precise Timing", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Precision Timing rune:\n\n\nSlam is now instant but has a 6 sec cooldown."},
[416008] = {name = "Engrave Pants - Everlasting Affliction", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Everlasting Affliction rune:\n\n\nEach time your Drain Life, Drain Soul, or Shadowbolt spell deals damage, your Corruption on the target is refreshed to its maximum duration."},
[416009] = {name = "Engrave Chest - Demonic Tactics", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Demonic Tactics rune:\n\n\nIncreases the critical strike chance of all attacks for you and your summoned Demon by 10% while the Demon is active."},
[416014] = {name = "Engrave Boots - Demonic Knowledge", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the Demonic Knowledge rune:\n\n\nIncreases your spell damage and your Demon pet's spell damage by up to 100% of your level while you have a summoned Demon pet active."},
[416015] = {name = "Engrave Bracers - Incinerate", additional_info = "3 sec cast\nRequires Bracers\n[q]Engrave your bracers with the Incinerate rune:\n\n\nDeals 100 to 114 Fire damage to your target and an additional 25% damage if the target is afflicted by Immolate."},
[416017] = {name = "Engrave Boots - Dance of the Wicked", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the Dance of the Wicked rune:\n\n\nYou and your demon pet gain dodge chance equal to 100% of your spell critical strike chance each time you deal a critical strike to an enemy, and also both regain 2% of maximum mana."},
[416028] = {name = "Engrave Boots - Sacred Shield", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the Sacred Shield rune:\n\n\nEach time the target takes damage they gain a Sacred Shield, absorbing [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] damage and increasing the Paladin's chance to critically hit with Flash of Light by 50% for up to 6 sec. In addition, causes your Flash of Light to heal targets with Sacred Shield for an additional 100% over 12 sec. They cannot gain this effect more than once every 6 sec. Lasts 1 min. This spell cannot be on more than one target at any one time."},
[416031] = {name = "Engrave Boots - The Art of War", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the The Art of War rune:\n\n\nIncreases all Holy damage you deal by 10%, and your melee and spell critical strikes reduce the remaining cooldown on your Exorcism spell by 2 sec."},
[416035] = {name = "Engrave Boots - Guarded by the Light", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the Guarded by the Light rune:\n\n\nYou gain 5% of your maximum mana every 3 sec for 15 sec after Blocking a melee attack. This effect is cancelled by casting Flash of Light, Holy Light, or Holy Shock."},
[416037] = {name = "Engrave Pants - Aura Mastery", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Aura Mastery rune:"},
[416042] = {name = "Engrave Chest - Survival of the Fittest", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Survival of the Fittest rune:\n\n\nReduces the chance you'll be critically hit by melee attacks by 6% and reduces all damage taken by 10%. Damage taken reduced by an additional 10% while in Bear Form or Dire Bear Form."},
[416044] = {name = "Engrave Gloves - Sunfire", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Sunfire rune:\n\n\nBurns the enemy for [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] to [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage and then an additional [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage over 12 sec.\n\n In addition, while in Bear Form, Cat Form, or Dire Bear Form, your Moonfire is replaced with Sunfire (Bear) or Sunfire (Cat). This spell benefits from and triggers all effects associated with Moonfire.\n\n Sunfire (Bear)\nBurns the enemy for [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] to [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage and then an additional [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage over 12 sec.\n\n Sunfire (Cat)\nBurns the enemy for [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] to [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage and then an additional [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] Nature damage over 12 sec. Awards 1 combo point."},
[416046] = {name = "Engrave Gloves - Skull Bash", additional_info = "3 sec cast\nRequires Gloves\n[q]Engrave your gloves with the Skull Bash rune:\n\n\nCharge to a target within 13 yards and bash the target's skull, interrupting spellcasting and preventing any spell in that school from being cast for 2 sec. Shares a cooldown with Feral Charge."},
[416049] = {name = "Engrave Pants - Lacerate", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Lacerate\n rune:\n\n\nLacerates the enemy target, making them bleed for 50 damage over 15 sec plus 10% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to 5 times on the same target."},
[416050] = {name = "Engrave Chest - Living Seed", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Living Seed rune:\n\n\nWhen you critically heal your target with any non-periodic healing spell you plant a Living Seed on the target for 50% of the amount healed. The Living Seed will bloom the next time the target takes damage or receives non-periodic healing. Lasts 15 sec."},
[416051] = {name = "Engrave Bracers - Elune's Fires", additional_info = "3 sec cast\nRequires Bracers\n[q]Engrave your bracers with the Elune's Fires rune:\n\n\nSome of your spells and abilities extend the duration of your damage and healing over time effects on their target:\n\n Starfire extends Moonfire by 6 sec.\n Wrath extends Sunfire by 3 sec.\n Regrowth extends Rejuvenation by 6 sec.\n Shred extends Rip by 2 sec.\n\n Each effect can only be extended up to its initial duration."},
[416054] = {name = "Engrave Belt - Power Surge", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Power Surge rune:\n\n\nEach time Flame Shock deals damage, it has a 5% chance to reset the cooldown on Lava Burst and Chain Lightning and make your next Lava Burst or Chain Lightning within 10 sec instant. Each time Riptide heals, it has a 5% chance to make your next Chain Heal within 10 sec instant. Additionally, every 5 sec you gain mana equal to 15% of your Intellect."},
[416055] = {name = "Engrave Helm - Mental Dexterity", additional_info = "3 sec cast\nRequires Helms\n[q]Engrave your helm with the Mental Dexterity rune:\n\n\nIncreases your Attack Power by an amount equal to 100% of your Intellect."},
[416057] = {name = "Engrave Chest - Healing Rain", additional_info = "3 sec cast\nRequires Chest, Chest\n[q]Engrave your chest or robe with the Healing Rain rune:\n\n\nSelects the area 15 yards around target player, and heals all of target player's party members within that area for [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100] every second."},
[416062] = {name = "Engrave Cloak - Coherence", additional_info = "3 sec cast\nRequires Cloak\n[q]Engrave your cloak with the Coherence rune:\n\n\nCauses your Chain heal effectiveness to only reduce by 35% per jump, and Chain Lightning effectiveness to only reduce by 20% per jump. Each also jumps to 1 additional target."},
[416066] = {name = "Engrave Helm - Burn", additional_info = "3 sec cast\nRequires Helms\n[q]Engrave your helm with the Burn rune:\n\n\nYour Flame Shock now strikes up to 5 targets, gains 6 sec increased duration, and deals 100% increased damage. In addition, while you have Flametongue Weapon imbued on your main hand equipped weapon, you gain increased spell damage equal to 150% of your Intellect."},
[416081] = {name = "Coherence", additional_info = "[q]Gain the Coherence ability:\n\n\nCauses your Chain heal effectiveness to only reduce by 35% per jump, and Chain Lightning effectiveness to only reduce by 20% per jump. Each also jumps to 1 additional target."},
[416083] = {name = "Engrave Helm - Catlike Reflexes", additional_info = "3 sec cast\nRequires Helms\n[q]Engrave your helm with the Catlike Reflexes rune:\n\n\nIncreases your chance to dodge by 20% and your pet's chance to dodge by 9%. In addition, reduces the cooldown of your Flanking Strike ability by 50%."},
[416084] = {name = "Engrave Belt - Aspect of the Viper", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Aspect of the Viper rune:\n\n\nThe hunter takes on the aspect of the viper, causing your ranged and melee auto attacks to regenerate mana but reducing your total damage done by 10%. In addition, you gain 10% of maximum mana every 3 sec. Mana gained is based on the speed of your weapon. Only one Aspect can be active at a time."},
[416085] = {name = "Engrave Helm - Lock and Load", additional_info = "3 sec cast\nRequires Helms\n[q]Engrave your helm with the Lock and Load rune:\n\n\nEach time you place a trap, your next Shot (except Scatter Shot) ability within 20 sec costs no mana and does not incur a cooldown."},
[416086] = {name = "Engrave Belt - Melee Specialist", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Melee Specialist rune:\n\n\nYour Raptor Strike is now instant, and Mongoose Bite and Raptor Strike have a 30% chance on each attack to reset the cooldowns of Mongoose Bite and Raptor Strike."},
[416087] = {name = "Engrave Belt - Kill Shot", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Kill Shot rune:\n\n\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health."},
[416089] = {name = "Engrave Boots - Wyvern Strike", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the Wyvern Strike rune:\n\n\nReplaces your Wyvern Sting ability with Wyvern Strike, a vicious strike that deals 140% weapon damage and causes the target to Bleed for damage over time.\n\n Wyvern Strike requires you to have the Wyvern Sting talent, and replaces the Wyvern Sting abilities found in the Survival spellbook."},
[416090] = {name = "Engrave Helm - Rapid Killing", additional_info = "3 sec cast\nRequires Helms\n[q]Engrave your helm with the Rapid Killing rune:\n\n\nReduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%."},
[416091] = {name = "Engrave Pants - Sniper Training", additional_info = "3 sec cast\nRequires Pants\n[q]Engrave your pants with the Sniper Training rune:\n\n\nWhen you have not moved for the last 1 sec, you have a 20% chance to gain Sniper's Aim, stacking up to 5 times. Sniper's Aim increases the critical strike chance of your Shot abilities by 2%."},
[416093] = {name = "Engrave Bracers - Raptor Fury", additional_info = "3 sec cast\nRequires Bracers\n[q]Engrave your bracers with the Raptor Fury rune:\n\n\nRaptor Strike increases damage done by Raptor Strike and Mongoose Bite by 15% for 30 sec, stacking up to 5 times. Subsequent doses do not extend the duration of this effect."},
