[417135] = {name = "Gale Winds", additional_info = "[q]Increases the damage done by your Hurricane by 100%, it no longer has a cooldown, and its mana cost is reduced by 60%."},
[417141] = {name = "Berserk", additional_info = "{Instant} {3 min cooldown}\n[q]Requires Cat Form, Bear Form, Dire Bear Form\n Causes your Primal Bite ability to strike up to 3 targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by 100%. Clears and grants immunity to Fear effects for the duration. Lasts 15 sec."},
[417145] = {name = "Gore", additional_info = "[q]Striking a target with Lacerate, Swipe, or Maul has a 15% chance to reset the cooldown on Mangle (Bear) and grant 10 Rage. Striking a target with Mangle (Cat) or Shred has a 15% chance to reset the cooldown on Tiger's Fury.\n(Proc chance: 15%, 100ms cooldown)"},
[417146] = {name = "Efflorescence", additional_info = nil},
[417147] = {name = "Efflorescence", additional_info = "100 yd range\n{Instant} {10 sec cooldown}\n[q]Heals all party or raid members within 15 yards of the selected area for [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100] every 5.2 sec for 15 sec."},
[417148] = {name = "Efflorescence", additional_info = "100 yd range\nInstant\n[q]Heals all party members within 15 yards of the target for [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100]."},
[417149] = {name = "Efflorescence", additional_info = "[q]Your Swiftmend now also causes Efflorescence, healing all party members within 15 yards of the Swiftmend target's location for [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100] every 1 sec for 15 sec."},
[417157] = {name = "Starsurge", additional_info = "30 yd range\n{Instant} {6 sec cooldown}\n[q]Launch surging stellar energies that cause [248 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1)] to [304 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1)] Arcane damage, and increases the damage done by your next 1 Starfire cast by 80% for 15 sec.\n\n Starsurge benefits from and triggers most talents and effects that trigger or benefit from Wrath or Starfire."},
