[424759] = {name = "Berserk", additional_info = "[q]Gain the Berserk ability:\n\n\nRequires Cat Form, Bear Form, Dire Bear Form\n Causes your Primal Bite ability to strike up to 3 targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by 100%. Clears and grants immunity to Fear effects for the duration. Lasts 15 sec."},
[424760] = {name = "Engrave Belt - Berserk", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Berserk rune:\n\n\nRequires Cat Form, Bear Form, Dire Bear Form\n Causes your Primal Bite ability to strike up to 3 targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by 100%. Clears and grants immunity to Fear effects for the duration. Lasts 15 sec."},
[424762] = {name = "King of the Jungle", additional_info = "[q]Gain the King of the Jungle ability:\n\n\nTiger's Fury now instantly grants you 60 Energy."},
[424765] = {name = "Engrave Boots - King of the Jungle", additional_info = "3 sec cast\nRequires Boots\n[q]Engrave your boots with the King of the Jungle rune:\n\n\nTiger's Fury now instantly grants you 60 Energy."},
[424785] = {name = "Saber Slash", additional_info = "{45 Energy} {Melee Range}\nInstant\nRequires Melee Weapon\n[q]Viciously slash an enemy for 100% weapon damage, and cause the target to bleed for (Attack Power * 5 / 100) damage every 2 sec for 12 sec, stacking up to 3 times. Each stack also increases damage done by your Saber Slash and Sinister Strike by 33%. Awards 1 combo point.\n\n Saber Slash benefits from all talents and effects that trigger from or modify Sinister Strike."},
[424788] = {name = "Salvage", additional_info = "Melee Range\n1 sec cast\n[q]Salvage the wreckage of a shredder for spare parts."},
[424799] = {name = "Shiv", additional_info = "{20 Energy} {Melee Range}\nInstant\nRequires Melee Weapon\n[q]Instantly attack with your off-hand weapon to deal normal off-hand weapon damage with a 100% chance to apply the poison from your off-hand weapon to the target. Slower weapons require more energy. Awards 1 combo point.\n\n Shiv benefits from all talents and effects that trigger from or modify Sinister Strike."},
[424800] = {name = "Shiv", additional_info = "Melee Range\nInstant\nRequires Melee Weapon\n[q]Instantly attack with your off-hand weapon with a 100% chance to apply the poison from your off-hand weapon to the target. Slower weapons require more energy. Awards 1 combo point."},
[424919] = {name = "Main Gauche", additional_info = "{15 Energy} {Melee Range}\n{Instant} {15 sec cooldown}\nRequires Melee Weapon\n[q]Instantly strike with your off-hand weapon for normal off-hand weapon damage and increase your chance to parry by 100% for 5 sec or until you successfully parry. For 20 sec after using Main Gauche, Sinister Strike costs 20 less Energy, deals 50% more threat, grants stacks of Rolling with the Punches, and both Sinister Strike and Eviscerate deal 50% more damage. Awards 1 combo point.\n\n Main Gauche benefits from most talents and effects that trigger from or modify Sinister Strike. Main Gauche's effect will not discount or empower Main Gauche."},
[424925] = {name = "Slaughter from the Shadows", additional_info = "[q]Reduces the Energy cost of your Backstab and Ambush abilities by 30, and increases the damage they deal to non-player controlled targets by 60%. [ Engrave Gloves - Mutilate : Does not apply to Mutilate / Does not apply to abilities learned from other runes.]"},
