[425284] = {name = "Spirit of the Redeemer", additional_info = "{Instant} {2 min cooldown}\n[q]Activate to become the Spirit of Redemption for 10 sec. While in this form, you can cast any healing spell free of cost, but you cannot move, attack, be attacked, or be targeted by any spells or effects. Requires Spirit of Redemption talent to activate, and you will no longer enter Spirit of Redemption upon dying."},
[425285] = {name = "Summon Decayed Elemental", additional_info = "10 yd range\nInstant\n[q]Call to the spirits of the elements."},
[425294] = {name = "Dispersion", additional_info = "{Instant} {2 min cooldown}\n[q]You disperse into pure Shadow energy, reducing all damage taken by 90%. You are unable to attack or cast spells, but you regenerate 6% mana every 1 sec for 6 sec. Dispersion can be cast while stunned, feared or silenced and clears all snare and movement impairing effects when cast, and makes you immune to them while dispersed."},
[425302] = {name = "Empowered Renew", additional_info = "[q]Gain the Empowered Renew ability:\n\n\nYour Renew now heals one extra time immediately when applied, and gains 15% increased benefit each time it heals from your bonus healing effects.\n\n In addition, your Renew can now be active on targets affected by another Priest's Renew."},
[425303] = {name = "Renewed Hope", additional_info = "[q]Gain the Renewed Hope ability:\n\n\nYour heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 10% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 5 sec."},
[425304] = {name = "Spirit of the Redeemer", additional_info = "[q]Gain the Spirit of the Redeemer ability:\n\n\nActivate to become the Spirit of Redemption for 10 sec. While in this form, you can cast any healing spell free of cost, but you cannot move, attack, be attacked, or be targeted by any spells or effects. Requires Spirit of Redemption talent to activate, and you will no longer enter Spirit of Redemption upon dying."},
[425307] = {name = "Dispersion", additional_info = "[q]Gain the Dispersion ability:\n\n\nYou disperse into pure Shadow energy, reducing all damage taken by 90%. You are unable to attack or cast spells, but you regenerate 6% mana every 1 sec for 6 sec. Dispersion can be cast while stunned, feared or silenced and clears all snare and movement impairing effects when cast, and makes you immune to them while dispersed."},
[425309] = {name = "Engrave Belt - Empowered Renew", additional_info = "3 sec cast\nRequires Belt\n[q]Engrave your belt with the Empowered Renew rune:\n\n\nYour Renew now heals one extra time immediately when applied, and gains 15% increased benefit each time it heals from your bonus healing effects.\n\n In addition, your Renew can now be active on targets affected by another Priest's Renew."},
