[1219557] = {name = "Power of the Guardian", additional_info = "Instant\n[q]Increases spell casting speed of all party members within 30 yards by 2%. This specific effect does not stack from multiple sources."},
[1219558] = {name = "Power of the Guardian", additional_info = "Instant\n[q]Increases the spell critical chance of all party members within 30 yards by 2%. This specific effect does not stack from multiple sources."},
[1219577] = {name = "Enchant Off-Hand - Superior Intellect", additional_info = "5 sec cast\nRequires Armor\nTools: Runed Arcanite Rod\nReagents:\nNexus Crystal (2), Illusion Dust (18), Essence of Air (2)\n[q]Permanently enchant an Off-Hand to add 9 to intellect."},
[1219578] = {name = "Enchant Off-Hand - Excellent Spirit", additional_info = "5 sec cast\nRequires Armor\nTools: Runed Arcanite Rod\nReagents:\nNexus Crystal (2), Illusion Dust (18), Essence of Water (2)\n[q]Permanently enchant an Off-Hand to add 12 to spirit."},
[1219579] = {name = "Enchant Off-Hand - Wisdom", additional_info = "5 sec cast\nRequires Armor\nTools: Runed Arcanite Rod\nReagents:\nLarge Brilliant Shard (6), Illusion Dust (18), Essence of Air , Essence of Water\n[q]Permanently enchant an Off-Hand to add 6 to intellect and 5 to spirit."},
[1219580] = {name = "Enchant 2H Weapon - Spellblasting", additional_info = "5 sec cast\nTools: Runed Arcanite Rod\nReagents:\nNexus Crystal (3), Illusion Dust (24), Blood of Heroes , Purple Lotus (6)\n[q]Permanently enchant a 2H Weapon to add 65 Spell Power."},
[1219581] = {name = "Enchant Shield - Excellent Stamina", additional_info = "5 sec cast\nRequires Armor\nTools: Runed Arcanite Rod\nReagents:\nLarge Brilliant Shard (6), Illusion Dust (18), Essence of Earth (2)\n[q]Permanently enchant a Shield to add 12 to stamina."},
[1219587] = {name = "Enchant Cloak - Agility", additional_info = "5 sec cast\nRequires Armor\nTools: Runed Arcanite Rod\nReagents:\nGreater Eternal Essence (3), Illusion Dust (9), Essence of Fire\n[q]Permanently enchant a Cloak to add 5 to agility."},
