[1219707] = {name = "Rejuvenation", additional_info = "Unlimited range\nInstant\n[q]Restores 20 rage."},
[1219708] = {name = "Rejuvenation", additional_info = "Unlimited range\nInstant\n[q]Restores 60 mana."},
