[1219740] = {name = "Soul of the Tactician", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Tactician:\n\nAfter changing stances, your next offensive ability's rage cost is reduced by 10."},
[1219741] = {name = "Grasping Spirits", additional_info = "Unlimited range\nInstant\n[q]Deals 462 to 538 Shadow damage every 1 sec. Slows movement speed by 35%."},
[1219742] = {name = "Soul of the War Veteran", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the War Veteran:\n\nFor 15 sec after leaving a stance, you can use abilities requiring that stance as if you were still in that stance."},
[1219743] = {name = "Soul of the Battle Forecaster", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Battle Forecaster:\n\nFor the first 15 sec after activating a stance, you can gain an additional benefit:\n\n Battle Stance/Gladiator Stance: 10% increased damage done.\n\n Berserker Stance: 10% increased critical strike chance.\n\n Defensive Stance: 10% reduced Physical damage taken."},
[1219744] = {name = "Grasping Spirits", additional_info = nil},
[1219745] = {name = "Soul of the Bloodseeker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Bloodseeker:\n\nOverpower critical strikes refresh the duration of Rend on your target back to its maximum duration."},
[1219747] = {name = "Soul of the Titan", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Titan:\n\nYour Heroic Strike, Slam, and Overpower abilities deal 25 + (5 * Combo Points)% more damage."},
[1219748] = {name = "Soul of the Destroyer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Destroyer:\n\nYour Slam hits reset the remaining cooldown on your Mortal Strike, Bloodthirst, and Shield Slam abilities."},
[1219749] = {name = "Soul of the Deathbound", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Deathbound:\n\nReduces the cooldown on your Death Wish by 50%."},
[1219751] = {name = "Soul of the Sanguinist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Sanguinist:\n\nYou deal 20% increased damage while any nearby enemy is afflicted with both your Rend and your Deep Wounds."},
[1219752] = {name = "Soul of the Pristine Blocker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Pristine Blocker:\n\nIncreases the block value of your shield by 30."},
[1219753] = {name = "Soul of the Savage", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Savage:\n\nYou gain 1 extra Rage every time you take any damage or deal auto attack damage."},
[1219754] = {name = "Soul of Enmity", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of Enmity:\n\nIncreases all threat you generate in Defensive Stance by an additional 10% and increases all damage you deal in Gladiator Stance by 4%."},
[1219755] = {name = "Soul of the Deflective", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Deflective:\n\nYou gain 10 Rage every time you Parry or one of your attacks is Parried."},
[1219756] = {name = "Soul of the Revenger", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Revenger:\n\nRevenge also grants you Flurry, increasing your attack speed by 100 + (5 * Combo Points)% for the next 0 swings."},
[1219757] = {name = "Soul of the Incessant", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Incessant:\n\nWhen your target Parries an attack, you instantly Retaliate for 200% weapon damage to that target. Retaliate cannot be Dodged, Blocked, or Parried, but can only occur once every 30 sec per target."},
[1219758] = {name = "Soul of the Thunderbringer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Thunderbringer:\n\nReduces the cooldown on Thunder Clap by 100%."},
[1219760] = {name = "Soul of the Sentinel", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Sentinel:\n\nYour Shield Slam deals 100% increased threat and its cooldown is reset if it is Dodged, Parried, or Blocked."},
[1219762] = {name = "Soul of the Southpaw", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Southpaw:\n\nReduces the cooldown on your Shield Slam ability by 2 sec."},
[1219763] = {name = "Soul of the Gladiator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Gladiator:\n\nReduces the cooldown on your Bloodrage ability by 30 sec while you are in Gladiator Stance."},
[1219764] = {name = "Soul of the Aftershock", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Aftershock:\n\nReduces the cooldown on Shockwave by 50%."},
[1219766] = {name = "Soul of the Avoidant", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Avoidant:\n\nFeint also grants Avoidance for 6 sec, reducing all damage taken from area of effect attacks from non-players by 50%."},
[1219767] = {name = "Soul of the Toxicologist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Toxicologist:\n\nIncreases the critical strike damage bonus of your Poisons by 100%."},
[1219768] = {name = "Soul of the Executioner", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Executioner:\n\nYour finishing moves have a 5% chance per combo point to make your next ability cost no energy."},
[1219769] = {name = "Soul of the Opportunist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Opportunist:\n\nYour opening moves have a 100% chance to make your next ability cost no energy."},
[1219770] = {name = "Soul of the Butcher", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Butcher:\n\nIncreases damage dealt by your main hand weapon from combo-generating abilities by 20%."},
[1219771] = {name = "Soul of the Phantom", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Phantom:\n\nReduces the cooldown on Vanish to 1 min. Cannot be combined with Elusiveness."},
[1219772] = {name = "Soul of the Scoundrel", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Scoundrel:\n\nIncreases Mutilate and Saber Slash damage by 20%."},
[1219773] = {name = "Soul of the Thrill Seeker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Thrill Seeker:\n\nReduces the cooldown on Adrenaline Rush by 4 min."},
[1219774] = {name = "Soul of the Shiv Savant", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Shiv Savant:\n\nIncreases your chance to get a critical strike with Daggers by 5%."},
[1219775] = {name = "Soul of the Stalker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Stalker:\n\nIncreases the critical strike chance of your Ambush ability by 30%."},
[1219776] = {name = "Soul of the Efficient", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Efficient:\n\nYour finishing moves cost 50% less Energy."},
[1219777] = {name = "Soul of the Knife Juggler", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Knife Juggler:\n\nWhile Just a Flesh Wound and Blade Dance are active, Crimson Tempest, Blunderbuss, and Fan of Knives cost 20 less Energy and generate 100% increased threat."},
[1219778] = {name = "Soul of the Shadow Master", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Shadow Master:\n\nVanish now reduces all Magic damage you take by 50% for its duration, but it no longer grants Stealth or breaks movement impairing effects."},
[1219779] = {name = "Soul of the Equilibrist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Equilibrist:\n\nYour finishing moves have a 20% chance per combo point to make you take 50% less Physical damage from the next melee attack that hits you within 10 sec."},
[1219780] = {name = "Soul of the Poised Brawler", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Poised Brawler:\n\nYour Rolling with the Punches now also activates every time you gain a combo point."},
[1219781] = {name = "Soul of the Black Belt", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Black Belt:\n\nYour Rolling with the Punches also grants you 20% increased Armor from items per stack (capped at 100%)."},
[1219782] = {name = "Soul of the Fencer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Fencer:\n\nThe cooldown on your Main Gauche resets every time your target Dodges or Parries."},
[1219783] = {name = "Soul of the Swashbuckler", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Swashbuckler:\n\nYour Main Gauche now strikes 1 additional nearby target and also causes your Sinister Strike to strike 1 additional nearby target for 10 sec. These additional strikes are not duplicated by Blade Flurry."},
[1219784] = {name = "Soul of the Bloodthirsty", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Bloodthirsty:\n\nWhile active, your Main Gauche also causes you to heal for 15% of all damage done by Sinister Strike. Any excess healing becomes a Blood Barrier, absorbing damage up to 20% of your maximum health."},
[1219785] = {name = "Soul of the Transfusionist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Transfusionist:\n\nLifetap generates 50% more mana and 100% less threat."},
[1219786] = {name = "Soul of the Refined", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%."},
[1219787] = {name = "Soul of the Decimator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Decimator:\n\nYour Nightfall talent has a 4% increased chance to trigger. Your Incinerate has a 4% chance to trigger your Decimation regardless of the target's health."},
[1219788] = {name = "Soul of the Rotbringer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Rotbringer:\n\nIncreases the damage of your periodic spells and Felguard pet by 10 + (5 * Combo Points)%."},
[1219789] = {name = "Soul of the Malevolent", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Malevolent:\n\nPeriodic damage from your Shadowflame, Unstable Affliction, and Curse of Agony spells and damage done by your Felguard have a 4% chance to grant the Shadow Trance effect."},
[1219790] = {name = "Soul of the Shadowmancer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Shadowmancer:\n\nShadowbolt deals 10 + (5 * Combo Points)% increased damage for each of your effects afflicting the target, up to a maximum of 30 + (5 * Combo Points)%."},
[1219791] = {name = "Soul of the Chaos Harbinger", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Chaos Harbinger:\n\nReduces the cooldown on your Chaos Bolt by 50% and increases Chaos Bolt and Shadow Bolt damage done by 10%. In addition, Chaos Bolt can now trigger your Improved Shadow Bolt talent and causes it to have 26 additional charges (does not stack with Shadowflame's additional charges)."},
[1219792] = {name = "Soul of the Arsonist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Arsonist:\n\nEach time you hit a target with Conflagrate, you gain 5% increased Fire damage for 20 sec, stacking up to 2 times."},
[1219793] = {name = "Soul of the Infernal Shepherd", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Infernal Shepherd:\n\nIncreases the Attack Power and Spell Damage your Demon pet gains from your attributes by 20%."},
[1219794] = {name = "Soul of the Demonlord", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Demonlord:\n\nIncreases the benefits of your Master Demonologist talent by 50%."},
[1219795] = {name = "Soul of the Demonic Exorcist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Demonic Exorcist:\n\nBanish is now instant cast, and can be cast on yourself while you are a Demon. You cannot Banish yourself while you have Forbearance, and doing so will give you Forbearance for 1 min."},
[1219796] = {name = "Soul of the Pained", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Pained:\n\nEach time you take damage, you and your pet gain mana equal to the damage taken, up to a maximum of 420 mana per event. Can only occur once every few seconds."},
[1219797] = {name = "Soul of the Flamewraith", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Flamewraith:\n\nYour Shadow Cleave hits have a 20% chance to grant you a Soul Shard, reset the cooldown on Soul Fire, and make your next Soul Fire within 10 sec instant."},
[1219798] = {name = "Soul of the Fleshfeaster", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Fleshfeaster:\n\nWhile you are targeting an enemy within 30 yards, Life Tap grants you mana at the expense of your target's health but deals 50 + (5 * Combo Points)% reduced damage to them. Mana gained remains unchanged."},
[1219799] = {name = "Soul of the Abyssal", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Abyssal:\n\nWhile Metamorphosis is active, your offensive abilities and Demon summons cost no Soul Shards. In addition, you heal for 15% of your maximum health when you damage a target with Shadowburn."},
[1219800] = {name = "Soul of the Voidborne", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Voidborne:\n\nAny excess healing you deal to yourself is converted into a shield that absorbs damage. This shield can absorb up to 30 + (5 * Combo Points)% of your maximum health, and stacks from multiple heals."},
[1219801] = {name = "Soul of the Umbral Blade", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Umbral Blade:\n\nReduces the cooldown on your Shadow Cleave by 1.5 sec."},
[1219802] = {name = "Soul of the Ritualist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Ritualist:\n\nThe effects of your Demonic Sacrifice now persist while you have a Demon pet active, as long as you do not resummon the sacrificed pet. You may have only one Demonic Sacrifice effect active at a time."},
[1219803] = {name = "Soul of the Pain Spreader", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Pain Spreader:\n\nFor 6 sec after using Shadowcleave, your Searing Pain strikes 1 additional target within melee range."},
[1219804] = {name = "Soul of the Misleader", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Misleader:\n\nYou generate 100% more threat for 8 sec after using Distracting Shot."},
[1219805] = {name = "Soul of the Preyseeker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Preyseeker:\n\nWhile tracking a creature type, you deal 3% increased damage to that creature type."},
[1219806] = {name = "Soul of the Sharpshooter", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Sharpshooter:\n\nYour next Shot ability within 12 sec after Aimed Shot deals 20% more damage."},
[1219807] = {name = "Soul of the Hazard Harrier", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Hazard Harrier:\n\nYour Aimed Shot deals 20% more damage to targets afflicted by one of your trap effects."},
[1219808] = {name = "Soul of the Alternator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Alternator:\n\nYour damaging Shot abilities deal 10% increased damage if the previous damaging Shot used was different than the current one."},
[1219809] = {name = "Soul of the Toxinologist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Toxinologist:\n\nYour Serpent Sting damage is increased by 25% of your Attack Power over its normal duration."},
[1219810] = {name = "Soul of the Bounty Hunter", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Bounty Hunter:\n\nIncreases Kill Shot's damage against non-player controlled targets by 30%."},
[1219811] = {name = "Soul of the Trick Shooter", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Trick Shooter:\n\nKill Shot's cooldown is reduced by 50%. While Rapid Fire is active with Rapid Killing engraved, Kill Shot has no cooldown, and when used against a non-player controlled target, fires 3 additional Kill Shots at 30% damage, with a minimum range."},
[1219812] = {name = "Soul of the Beast Tender", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Beast Tender:\n\nIncreases the Attack Power your Beast pet gains from your attributes by 20%."},
[1219813] = {name = "Soul of the Hound Master", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Hound Master:\n\nIncreases the Focus regeneration of your Beast pet by 20%."},
[1219814] = {name = "Grasping Spirits", additional_info = nil},
[1219815] = {name = "Soul of the Alpha Tamer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Alpha Tamer:\n\nIncreases the Focus regeneration of your pets by 100%."},
[1219816] = {name = "Soul of the Huntsman", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Huntsman:\n\nYour Mongoose Bite also reduces its target's chance to Dodge by 1% and increases your chance to hit by 1% for 30 sec."},
[1219818] = {name = "Soul of the Retaliator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Retaliator:\n\nMongoose Bite also activates for 5 sec whenever your target Parries or Blocks or when your melee attack misses."},
[1219819] = {name = "Soul of Echoes", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of Echoes:\n\nRaptor Strike increases the damage done by your next other melee ability (excluding Wing Clip) within 5 sec by 20%."},
[1219820] = {name = "Soul of the Lethal Lasher", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Lethal Lasher:\n\nIncreases damage dealt by your main hand weapon with Raptor Strike and Wyvern Strike by 20%."},
[1219821] = {name = "Soul of the Kineticist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Kineticist:\n\nYour periodic damage has a 5% chance to reset the cooldown on one of your Strike abilities. The Strike with the longest remaining cooldown is always chosen."},
[1219822] = {name = "Soul of the Strategist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Strategist:\n\nIncreases Wyvern Strike damage over time by 50% and increases your pet's maximum focus by 50."},
[1219823] = {name = "Soul of the Deadly Striker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Deadly Striker:\n\nIncreases the impact damage of Mongoose Bite and all Strikes by 20%."},
[1219824] = {name = "Soul of the Hastened Healer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Hastened Healer:\n\n-0 sec to the casting time of Flash Heal and -0 sec to the casting time of Greater Heal."},
[1219825] = {name = "Soul of the Refined", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%."},
[1219826] = {name = "Soul of the Celebrant", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Celebrant:\n\nIncreases your critical strike chance with Prayer of Healing and Circle of Healing by 25%."},
[1219827] = {name = "Soul of the Faithful", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Faithful:\n\nAllows 15% of your Mana regeneration to continue while casting."},
[1219828] = {name = "Soul of the Serendipitous", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Serendipitous:\n\nYour periodic healing has a 2% chance to make your next spell with a casting time less than 10 seconds an instant cast spell."},
[1219829] = {name = "Soul of the Resonant", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Resonant:\n\nCircle of Healing and Penance also place a heal over time effect on their targets that heals for 25% as much over 15 sec."},
[1219830] = {name = "Soul of the Devotee", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Devotee:\n\nYour Prayer of Mending gains 2 additional charges."},
[1219831] = {name = "Soul of the Archbishop", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Archbishop:\n\nYour Circle of Healing now heals the most injured member of the target party for 100% more."},
[1219832] = {name = "Soul of the Penitent", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Penitent:\n\nReduces the cooldown of your Penance spell by 6 sec."},
[1219833] = {name = "Soul of the Soul Warder", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Soul Warder:\n\nIncreases the damage absorbed by your Power Word: Shield spell by 10%."},
[1219834] = {name = "Soul of the Twilight Walker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Twilight Walker:\n\nYou may cast Flash Heal while in Shadowform."},
[1219835] = {name = "Soul of the Mind Breaker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Mind Breaker:\n\nMind Blast critical strikes reduce the duration of your next Mind Flay by 50% while increasing its total damage by 50%."},
[1219836] = {name = "Soul of the Deathdealer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Deathdealer:\n\nReduces the cooldown of your Shadow Word: Death spell by 6 sec."},
[1219837] = {name = "Soul of the Spirit Font", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Spirit Font:\n\nYour Shadow Word: Pain has a 2.0% chance per talent point in Spirit Tap to trigger your Spirit Tap talent when it deals damage, or a 20% chance per talent point when a target dies with your Shadow Word: Pain active. Inner Focus also has a 20% chance per talent point to trigger Spirit Tap."},
[1219838] = {name = "Soul of the Zealot", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Zealot:\n\nWhile Spirit Tap is active, you deal 25% more Shadow damage."},
[1219839] = {name = "Soul of the Unwavering Defiler", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Unwavering Defiler:\n\nYour Mind Flay no longer loses duration from taking damage and launches a free Mind Spike at the target on cast."},
[1219840] = {name = "Soul of the Contemnor", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Contemnor:\n\nYour Mind Spike is now instant, deals 10% more damage, and can be cast while channeling another spell."},
[1219841] = {name = "Soul of the Plaguebringer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Plaguebringer:\n\nYour Pain and Suffering rune can now refresh the duration of Devouring Plague."},
[1219842] = {name = "Soul of the Reverberant", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Reverberant:\n\nYour Temporal Beacons last 20% longer."},
[1219843] = {name = "Soul of the Chronohealer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Chronohealer:\n\nIncreases all chronomantic healing you deal by 10%."},
[1219844] = {name = "Soul of Temporal Longing", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of Temporal Longing:\n\nEach time you heal a target with Regeneration, the remaining cooldown on Rewind Time is reduced by 1 sec."},
[1219845] = {name = "Soul of the Precognitive", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Precognitive:\n\nYour Arcane Missiles refunds 10% of its base mana cost each time it deals damage."},
[1219846] = {name = "Soul of the Arcanist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Arcanist:\n\nArcane Blast gains a 10% additional chance to trigger Missile Barrage, and Missile Barrage now affects Regeneration the same way it affects Arcane Missiles."},
[1219847] = {name = "Soul of the Eternal Caretaker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Eternal Caretaker:\n\nYour Temporal Beacons caused by Mass Regeneration now last 21 sec."},
[1219848] = {name = "Soul of the Spellbider", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Spellbider:\n\nYour Arcane Blast increases damage done by an additional 10% per stack."},
[1219849] = {name = "Soul of the Wardshaper", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Wardshaper:\n\nYour Mana Shield, Fire Ward, and Frost Ward absorb 50% more damage and also place a Temporal Beacon on the target for 30 sec."},
[1219850] = {name = "Soul of Winter's Grasp", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of Winter's Grasp:\n\nIncreases the chance to trigger your Fingers of Frost rune by an additional 15%."},
[1219851] = {name = "Soul of the Cryomancer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Cryomancer:\n\nIncreases damage done by your Frostbolt and Spellfrost Bolt spells by 65%."},
[1219852] = {name = "Soul of the Evoker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Evoker:\n\nYou are immune to all damage while channeling Evocation."},
[1219853] = {name = "Soul of the Elementalist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Elementalist:\n\nYou gain 1% increased damage for 15 sec each time you cast a spell from a different school of magic."},
[1219854] = {name = "Soul of the Magical Armorer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Magical Armorer:\n\nMage Armor increases your mana regeneration while casting by an additional 15%. Molten Armor increases your spell damage and healing by 18. Ice Armor grants 20% increased chance to trigger Fingers of Frost."},
[1219855] = {name = "Soul of the Kindler", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Kindler:\n\nDecreases the threat generated by your Fire spells by 20%."},
[1219856] = {name = "Soul of Fiery Convergence", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of Fiery Convergence:\n\nYour Pyroblast deals 20% increased damage to targets afflicted with your Fireball's periodic effect."},
[1219857] = {name = "Soul of the Perpetual Blaze", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Perpetual Blaze:\n\nYour Fireball's periodic effect gains increased damage over its duration equal to 100% of its impact damage."},
[1219858] = {name = "Soul of the Pyromaniac", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Pyromaniac:\n\nYour Fire Blast now also causes your next Fire spell to gain 50% increased critical strike chance for 10 sec."},
[1219859] = {name = "Soul of the Igniter", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Igniter:\n\nIncreases the damage done by your Ignite talent by 10%."},
[1219860] = {name = "Soul of the Torcher", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Torcher:\n\nYour Fireball, Frostfire Bolt, and Balefire Bolt spells gain 3% increased damage for each of your Fire effects on your target, up to a maximum increased of 9%."},
[1219861] = {name = "Soul of the Pristine Blocker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Pristine Blocker:\n\nIncreases the block value of your shield by 30."},
[1219862] = {name = "Soul of the Lightwarden", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Lightwarden:\n\nHeal for 189 to 211 when you Block. Can only heal once every few seconds."},
[1219863] = {name = "Soul of the Radiant Defender", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Radiant Defender:\n\nHoly Shield no longer has charges and instead always lasts its full duration. In addition, its damage is increased by 80% of your shield block value."},
[1219864] = {name = "Soul of the Shieldbearer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Shieldbearer:\n\nIncreases the bonus chance to Block from Holy Shield by 10%."},
[1219865] = {name = "Soul of the Bastion", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Bastion:\n\nYou take 10% reduced damage while Holy Shield is active."},
[1219866] = {name = "Soul of the Reckoner", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Reckoner:\n\nYour Reckoning talent now has a 20% chance per talent point to trigger when you Block."},
[1219867] = {name = "Soul of the Ironclad", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Ironclad:\n\nYour Blessing of Sanctuary also grants 10% increase to all stats when cast on yourself."},
[1219868] = {name = "Soul of the Guardian", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Guardian:\n\nShield of the Righteous causes your next Holy Light to be instant cast. If cast on self, it will refund 100% of its mana cost and be unaffected by Guarded by the Light."},
[1219869] = {name = "Soul of the Peacekeeper", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Peacekeeper:\n\nIncreases the chance for allies to trigger your Judgement of Light or Judgement of Wisdom to 70%."},
[1219870] = {name = "Soul of the Refined", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%."},
[1219871] = {name = "Soul of the Exemplar", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Exemplar:\n\nWhenever your Flash of Light, Holy Light, or Beacon of Light heals a target to full health, you also heal all members of their party for 189 to 211 health."},
[1219872] = {name = "Soul of the Inquisitor", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Inquisitor:\n\nIncreases the critical strike chance of Holy Shock by 5%."},
[1219873] = {name = "Soul of the Sovereign", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Sovereign:\n\nIncreases the damage done by your Consecration by 50%."},
[1219874] = {name = "Soul of the Dominus", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Dominus:\n\nWhile you are not your Beacon of Light target, your Beacon of Light target is also healed by 75% of the damage you deal with Consecration, Exorcism, Holy Shock, Holy Wrath, and Hammer of Wrath."},
[1219875] = {name = "Soul of the Vindicator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Vindicator:\n\nReduces the cooldown on Divine Light by 25%."},
[1219876] = {name = "Soul of the Altruist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Altruist:\n\nYour heals on your Beacon of Light target also heal the nearest friendly injured target for 90% as much."},
[1219877] = {name = "Soul of the Arbiter", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Arbiter:\n\nYour Judgement of Light and Judgement of Wisdom also grant the effects of Judgement of the Crusader."},
[1219878] = {name = "Soul of the Sealbearer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Sealbearer:\n\nYour Seal of Command, Seal of Righteousness, Seal of Martyrdom, and Sunlight deal 35% less damage, but now persist for 6 seconds after you cast another Seal, or until you cast a third Seal. Your Judgements can now trigger multiple Seals if active."},
[1219879] = {name = "Soul of the Justicar", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Justicar:\n\nIncreases damage done by your damaging Judgements by 20% and your Judgements no longer consume your Seals on the target. Your Judgements can now trigger multiple Seals if active."},
[1219880] = {name = "Soul of the Judicator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Judicator:\n\nReduces the cooldown on your Judgement ability by 5 sec, but reduces the damage your Judgements deal by 45%."},
[1219881] = {name = "Soul of the Ascendant", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Ascendant:\n\nYour Judgement grants 1% increased Holy damage for 8 sec, stacking up to 5 times."},
[1219882] = {name = "Soul of the Retributor", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Retributor:\n\nIncreases Crusader Strike damage by 50%."},
[1219883] = {name = "Soul of the Excommunicator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Excommunicator:\n\nYour basic attacks with two-handed melee weapons increase the damage of your next Exorcism cast within 20 sec by 35%. Stacking up to 3 times."},
[1219884] = {name = "Soul of the Lightbringer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Lightbringer:\n\nIncreases damage done by your Holy Shock spell by 50%."},
[1219885] = {name = "Soul of the Exile", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Exile:\n\nReduces the cooldown of your Exorcism spell by 3 sec and increases its damage done by 50%."},
[1219886] = {name = "Soul of the Templar", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Templar:\n\nWhile a one-handed weapon is equipped, Crusader Strike now unleashes the Judgement effect of your Seals, but does not consume the Seal."},
[1219887] = {name = "Soul of the Windwalker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Windwalker:\n\nIncreases your attack speed by 1% for your next 3 swings after you parry, dodge, or block."},
[1219888] = {name = "Soul of the Shield Master", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Shield Master:\n\nYour parries and dodges also activate your Shield Mastery rune ability."},
[1219889] = {name = "Soul of the Totemic Protector", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Totemic Protector:\n\nYour Stoneskin Totem also reduces Physical damage taken by 5% and your Windwall Totem also reduces Magical damage taken by 5%."},
[1219890] = {name = "Soul of the Shock-Absorber", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Shock-Absorber:\n\nYour Flame Shock also grants 30% increased chance to Block for 5 sec or until you Block an attack."},
[1219891] = {name = "Soul of the Spiritual Bulwark", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Spiritual Bulwark:\n\nEach time you Block, your Block amount is increased by 10% of your Spell Damage for 6 sec, stacking up to 3 times."},
[1219892] = {name = "Soul of the Maelstrombringer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Maelstrombringer:\n\nEach time you Block an attack, you have a 50% chance to trigger your Maelstrom Weapon rune."},
[1219893] = {name = "Soul of the Lavawalker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Lavawalker:\n\nDamaging a target with Stormstrike, Lava Burst, or Molten Blast also reduces all damage you take by 10% for 10 sec."},
[1219894] = {name = "Soul of the True Alpha", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the True Alpha:\n\nWhen your Spirit of the Alpha is cast on yourself, it also increases your health by 10%, your threat generated by 20%, and all damage you deal by 10%."},
[1219895] = {name = "Soul of the Totemkeeper", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Totemkeeper:\n\nThe radius of your totems that affect friendly targets is increased to 40 yd."},
[1219896] = {name = "Soul of the Ancestors", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Ancestors:\n\nAfter casting your Healing Wave, Lesser Healing Wave, or Riptide spell, gives you a 25% chance to gain Mana equal to 35% of the base cost of the spell."},
[1219897] = {name = "Soul of the Spiritweaver", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Spiritweaver:\n\nYour Healing Wave will now jump to additional nearby targets. Each jump reduces the effectiveness of the heal by 60%, and the spell will jump to up to 2 additional targets."},
[1219898] = {name = "Soul of the Waterwalker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Waterwalker:\n\nYour non-periodic damaging and healing critical strikes now have a 100% chance to trigger your Water Shield, but do not consume a charge or trigger its cooldown."},
[1219899] = {name = "Soul of the Stormtender", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Stormtender:\n\nYour Chain Lightning now also heals the target of your most recent Earth Shield for 100% of the damage done."},
[1219900] = {name = "Soul of the Elemental Seer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Elemental Seer:\n\nIncreases the healing of Chain Heal and the damage of Chain Lightning by 20%."},
[1219901] = {name = "Soul of the Vitalist", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Vitalist:\n\nYour Riptide increases the amount healed by Chain Heal by an additional 25%."},
[1219902] = {name = "Soul of the Spirithealer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Spirithealer:\n\nReduces the cast time of Chain Heal by 0.5 sec."},
[1219903] = {name = "Soul of the Refined", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%."},
[1219904] = {name = "Soul of the Chieftain", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Chieftain:\n\nYour Flurry talent grants an additional 10% increase to your attack speed."},
[1219905] = {name = "Soul of the Furycharged", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Furycharged:\n\nYour chance to trigger Static Shock is increased by 12% (6% while dual - wielding)."},
[1219906] = {name = "Soul of the Stormbreaker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Stormbreaker:\n\nIncreases the main hand damage done by your Stormstrike by 50%."},
[1219907] = {name = "Soul of the Tempest", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Tempest:\n\nWhile Static Shock is engraved, your Lightning Shield now gains a charge each time you hit a target with Lightning Bolt or Chain Lightning, up to a maximum of 9 charges. In addition, while Static Shock is engraved, your Lightning Shield can now deal critical damage."},
[1219908] = {name = "Soul of the Seismic Smasher", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Seismic Smasher:\n\nIncreases Stormstrike and Lava Lash damage by 50%. This effect is increased to 100% if using a two-handed weapon."},
[1219909] = {name = "Soul of the Flamebringer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Flamebringer:\n\nYour Stormstrike, Lava Lash and Lava Burst critical strikes cause your target to burn for 30% of the damage done over 4 sec."},
[1219910] = {name = "Soul of the Volcano", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Volcano:\n\nYour Lightning Bolt critical strikes have a 35% chance to reset the cooldown on Lava Burst and Chain Lightning and make the next Lava Burst or Chain Lightning within 10 sec instant."},
[1219911] = {name = "Soul of the Raging Flame", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Raging Flame:\n\nLava Burst now also refreshes the duration of Flame Shock on your target back to 12 sec."},
[1219912] = {name = "Soul of the Elemental Master", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Elemental Master:\n\nYour spell critical strikes now have a 100% chance trigger your Elemental Focus talent."},
[1219913] = {name = "Soul of the Tribesman", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Tribesman:\n\nLoyal Beta from your Spirit of the Alpha ability now also increases Fire, Frost, and Nature damage by 5 + (5 * Combo Points)%."},
[1219914] = {name = "Soul of the Spirit Guide", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Spirit Guide:\n\nWhile Clearcasting is active, you deal 15 + (5 * Combo Points)% more non-Physical damage."},
[1219915] = {name = "Soul of the Elder", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Elder:\n\nYou have a 70% chance to avoid interruption caused by damage while casting Lightning Bolt, Chain Lightning, or Lava Burst, and a 10% increased chance to trigger your Elemental Focus talent."},
[1219916] = {name = "Soul of the Elements", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Elements:\n\nIncreases the critical strike damage bonus of your Fire, Frost, and Nature spells by 60%."},
[1219917] = {name = "Soul of the Lava Sage", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Lava Sage:\n\nYour Lava Burst damage is increased by a percentage equal to your spell critical strike chance."},
[1219918] = {name = "Soul of the Ancestral Warden", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Ancestral Warden:\n\nIncreases your chance to block attacks with a shield by 10%."},
[1219919] = {name = "Soul of the Corrupt", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Corrupt:\n\nIncreases the chance to trigger your Power Surge rune by an additional 5%."},
[1219920] = {name = "Soul of the Gentle Paw", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Gentle Paw:\n\nYou may cast Rebirth and Innervate while in Bear Form or Dire Bear Form."},
[1219921] = {name = "Soul of the Ferocious", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Ferocious:\n\nReduces the cooldown of Enrage by 30 sec and it no longer reduces your armor."},
[1219922] = {name = "Soul of the Shifter", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Shifter:\n\nBear Form and Dire Bear Form increase all threat you generate by an additional 20%, and Cower now removes all your threat against the target but has a 20 sec longer cooldown."},
[1219923] = {name = "Soul of the Territorial", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Territorial:\n\nSwipe(Bear) also causes your Maul to hit 1 additional target for the next 6 sec."},
[1219924] = {name = "Soul of the Beast", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Beast:\n\nYour Mangle(Bear), Swipe(Bear), Maul, and Lacerate abilities gain 5% increased critical strike chance against targets afflicted by your Lacerate."},
[1219925] = {name = "Soul of the Lacerator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Lacerator:\n\nYour Swipe now spreads your Lacerate from your primary target to other targets it strikes."},
[1219926] = {name = "Soul of the Furious", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Furious:\n\nEach time you Dodge while in Dire Bear Form, you gain 10% increased damage on your next Mangle or Swipe, stacking up to 5 times."},
[1219927] = {name = "Soul of the Mangler", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Mangler:\n\nReduces the cooldown on Mangle (Bear) by 1.5 sec."},
[1219928] = {name = "Soul of the Innervator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Innervator:\n\nWhen you cast Innervate on another player, it is also cast on you."},
[1219929] = {name = "Soul of the Nurturer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Nurturer:\n\nCasting your Healing Touch or Nourish spells gives you a 25% chance to gain Mana equal to 35% of the base cost of the spell."},
[1219930] = {name = "Soul of the Tranquil", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Tranquil:\n\nReduces the cooldown on Tranquility by 100% and increases its healing by 100%."},
[1219931] = {name = "Soul of the Dreamwalker", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Dreamwalker:\n\nYour healing spell critical strikes trigger the Dreamstate effect, granting you 50% of your mana regeneration while casting for 8 sec."},
[1219932] = {name = "Soul of the Grove Tender", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Grove Tender:\n\nYour non-periodic spell critical strikes reduce the casting time of your next Healing Touch, Regrowth, or Nourish spell by 0.5 sec."},
[1219933] = {name = "Soul of the Feathered Sage", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Feathered Sage:\n\nIncreases healing from Wild Growth by 10%. In addition, Wild Growth can now be used in Moonkin Form, and its healing is increased by an additional 50% in that form."},
[1219934] = {name = "Soul of the Benevolent Seer", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Benevolent Seer:\n\nReduces the cooldown of your Rebirth and Innervate spells by 65%."},
[1219935] = {name = "Soul of the Lifeweaver", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Lifeweaver:\n\nYour critical heals with Healing Touch, Regrowth, and Nourish instantly heal the target for another 50% of the healing they dealt."},
[1219936] = {name = "Soul of the Illuminator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Illuminator:\n\nYour Faerie Fire (Feral) also increases the chance for all attacks to hit that target by 1% for 40 sec."},
[1219937] = {name = "Soul of Predatory Instincts", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of Predatory Instincts:\n\nPeriodic damage from your Rake and Rip can now be critical strikes."},
[1219938] = {name = "Soul of the Ripper", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Ripper:\n\nYour Rip and Ferocious Bite have a 20% chance per combo point spent to refresh the duration of Savage Roar back to its initial value."},
[1219939] = {name = "Soul of the Claw", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Claw:\n\nIncreases the duration of Rake by 6 sec and its periodic damage by 40%."},
[1219940] = {name = "Soul of the Prideful", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Prideful:\n\nYour critical strike chance is increased by 15% while Tiger's Fury is active."},
[1219941] = {name = "Soul of the Barbaric", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Barbaric:\n\nYour Shred, Ferocious Bite, and Mangle(Cat) abilities deal 10% increased damage per your Bleed effect on the target, up to a maximum of 20% increase."},
[1219942] = {name = "Soul of the Frenetic", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Frenetic:\n\nYour Shred no longer has a positional requirement, but deals 15% more damage if you are behind the target."},
[1219943] = {name = "Soul of the Exsanguinator", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Exsanguinator:\n\nYour Mangle, Shred, and Ferocious Bite critical strikes cause your target to Bleed for 30% of the damage done over the next 4 sec sec."},
[1219944] = {name = "Soul of the Thornkeeper", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Thornkeeper:\n\nDamage dealt by Thorns increased by 100% and duration increased by 200%."},
[1219945] = {name = "Soul of the Lunatic", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Lunatic:\n\nIncreases your chance to hit with spells and attacks by 3%."},
[1219946] = {name = "Soul of the Starcaller", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Starcaller:\n\nReduces the cooldown on Starfall by 50%."},
[1219947] = {name = "Soul of the Night", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Night:\n\nIncreases the damage done and damage radius of Starfall's stars and Hurricane by 25%."},
[1219948] = {name = "Soul of the Keepers", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Keepers:\n\nYour Wrath casts have a 10% chance to summon a stand of 3 Treants to attack your target for 15 sec."},
[1219949] = {name = "Soul of the Wrathful", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Wrathful:\n\nYour Wrath critical strikes have a 50% chance to make your next Starfire deal 10% increased damage, stacking up to 3 times."},
[1219950] = {name = "Soul of the Graceful", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Graceful:\n\nYour Nature's Grace talent gains 1 additional charge each time it triggers."},
[1219951] = {name = "Soul of the Astral Ascendant", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Astral Ascendant:\n\nIncreases the critical strike damage bonus of your Starfire, Starsurge, and Wrath by 60%."},
[1219952] = {name = "Soul of the Cometcaller", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Cometcaller:\n\nReduces the cast time and global cooldown of Starfire by 0.5 sec."},
[1219953] = {name = "Soul of the Forest", additional_info = "3 sec cast\nRequires Shoulders\n[q]Permanently imbue your shoulders with the Soul of the Forest:\n\nIncreases the critical strike chance of Wrath by 10%."},
[1219954] = {name = "Soul of Animalistic Expertise", additional_info = "3 sec cast\nRequires Shoulders"},
[1219955] = {name = "Soul Engraving", additional_info = "Instant\n[q]The Soul of a fallen warrior can be engraved into this slot."},
[1219956] = {name = "Soul of the Tactician", additional_info = nil},
[1219957] = {name = "Soul of the Tactician", additional_info = "[q]After changing stances, your next offensive ability's rage cost is reduced by 10."},
[1219958] = {name = "Soul of the War Veteran", additional_info = "[q]For 15 sec after leaving a stance, you can use abilities requiring that stance as if you were still in that stance."},
[1219959] = {name = "Soul of the War Veteran", additional_info = nil},
[1219960] = {name = "Soul of the Battle Forecaster", additional_info = "[q]For the first 15 sec after activating a stance, you can gain an additional benefit:\n\n Battle Stance/Gladiator Stance: 10% increased damage done.\n\n Berserker Stance: 10% increased critical strike chance.\n\n Defensive Stance: 10% reduced Physical damage taken."},
[1219961] = {name = "Soul of the Battle Forecaster", additional_info = nil},
[1219962] = {name = "Soul of the Bloodseeker", additional_info = "[q]Overpower critical strikes refresh the duration of Rend on your target back to its maximum duration."},
[1219963] = {name = "Soul of the Bloodseeker", additional_info = nil},
[1219964] = {name = "Soul of the Titan", additional_info = "[q]Your Heroic Strike, Slam, and Overpower abilities deal 25 + (5 * Combo Points)% more damage."},
[1219965] = {name = "Soul of the Titan", additional_info = nil},
[1219966] = {name = "Soul of the Destroyer", additional_info = "[q]Your Slam hits reset the remaining cooldown on your Mortal Strike, Bloodthirst, and Shield Slam abilities."},
[1219967] = {name = "Soul of the Destroyer", additional_info = nil},
[1219968] = {name = "Soul of the Deathbound", additional_info = "[q]Reduces the cooldown on your Death Wish by 50%."},
[1219969] = {name = "Soul of the Deathbound", additional_info = nil},
[1219970] = {name = "Soul of the Sanguinist", additional_info = "[q]You deal 20% increased damage while any nearby enemy is afflicted with both your Rend and your Deep Wounds."},
[1219971] = {name = "Soul of the Sanguinist", additional_info = nil},
[1219972] = {name = "Soul of the Pristine Blocker", additional_info = "[q]Increases the block value of your shield by 30."},
[1219973] = {name = "Soul of the Pristine Blocker", additional_info = nil},
[1219974] = {name = "Soul of the Savage", additional_info = "[q]You gain 1 extra Rage every time you take any damage or deal auto attack damage."},
[1219975] = {name = "Soul of the Savage", additional_info = nil},
[1219976] = {name = "Soul of Enmity", additional_info = "[q]Increases all threat you generate in Defensive Stance by an additional 10% and increases all damage you deal in Gladiator Stance by 4%."},
[1219977] = {name = "Soul of Enmity", additional_info = nil},
[1219978] = {name = "Soul of the Deflective", additional_info = "[q]You gain 10 Rage every time you Parry or one of your attacks is Parried."},
[1219979] = {name = "Soul of the Deflective", additional_info = nil},
[1219980] = {name = "Soul of the Revenger", additional_info = "[q]Revenge also grants you Flurry, increasing your attack speed by 100 + (5 * Combo Points)% for the next 0 swings."},
[1219981] = {name = "Soul of the Revenger", additional_info = nil},
[1219982] = {name = "Soul of the Incessant", additional_info = "[q]When your target Parries an attack, you instantly Retaliate for 200% weapon damage to that target. Retaliate cannot be Dodged, Blocked, or Parried, but can only occur once every 30 sec per target."},
[1219983] = {name = "Soul of the Incessant", additional_info = nil},
[1219984] = {name = "Soul of the Thunderbringer", additional_info = "[q]Reduces the cooldown on Thunder Clap by 100%."},
[1219985] = {name = "Soul of the Thunderbringer", additional_info = nil},
[1219986] = {name = "Soul of the Sentinel", additional_info = "[q]Your Shield Slam deals 100% increased threat and its cooldown is reset if it is Dodged, Parried, or Blocked."},
[1219987] = {name = "Soul of the Sentinel", additional_info = nil},
[1219988] = {name = "Soul of the Southpaw", additional_info = "[q]Reduces the cooldown on your Shield Slam ability by 2 sec."},
[1219989] = {name = "Soul of the Southpaw", additional_info = nil},
[1219990] = {name = "Soul of the Gladiator", additional_info = "[q]Reduces the cooldown on your Bloodrage ability by 30 sec while you are in Gladiator Stance."},
[1219991] = {name = "Soul of the Gladiator", additional_info = nil},
[1219992] = {name = "Soul of the Aftershock", additional_info = "[q]Reduces the cooldown on Shockwave by 50%."},
[1219993] = {name = "Soul of the Aftershock", additional_info = nil},
[1219994] = {name = "Soul of the Avoidant", additional_info = "[q]Feint also grants Avoidance for 6 sec, reducing all damage taken from area of effect attacks from non-players by 50%."},
[1219995] = {name = "Soul of the Avoidant", additional_info = nil},
[1219996] = {name = "Soul of the Toxicologist", additional_info = "[q]Increases the critical strike damage bonus of your Poisons by 100%."},
[1219997] = {name = "Soul of the Toxicologist", additional_info = nil},
[1219998] = {name = "Soul of the Executioner", additional_info = "[q]Your finishing moves have a 5% chance per combo point to make your next ability cost no energy."},
[1219999] = {name = "Soul of the Executioner", additional_info = nil},
[1220000] = {name = "Soul of the Opportunist", additional_info = "[q]Your opening moves have a 100% chance to make your next ability cost no energy."},
[1220001] = {name = "Soul of the Opportunist", additional_info = nil},
[1220002] = {name = "Soul of the Butcher", additional_info = "[q]Increases damage dealt by your main hand weapon from combo-generating abilities by 20%."},
[1220003] = {name = "Soul of the Butcher", additional_info = nil},
[1220004] = {name = "Soul of the Phantom", additional_info = "[q]Reduces the cooldown on Vanish to 1 min. Cannot be combined with Elusiveness."},
[1220005] = {name = "Soul of the Phantom", additional_info = nil},
[1220006] = {name = "Soul of the Scoundrel", additional_info = "[q]Increases Mutilate and Saber Slash damage by 20%."},
[1220007] = {name = "Soul of the Scoundrel", additional_info = nil},
[1220008] = {name = "Soul of the Thrill Seeker", additional_info = "[q]Reduces the cooldown on Adrenaline Rush by 4 min."},
[1220009] = {name = "Soul of the Thrill Seeker", additional_info = nil},
[1220010] = {name = "Soul of the Shiv Savant", additional_info = "[q]Increases your chance to get a critical strike with Daggers by 5%."},
[1220011] = {name = "Soul of the Shiv Savant", additional_info = nil},
[1220012] = {name = "Soul of the Stalker", additional_info = "[q]Increases the critical strike chance of your Ambush ability by 30%."},
[1220013] = {name = "Soul of the Stalker", additional_info = nil},
[1220014] = {name = "Soul of the Efficient", additional_info = "[q]Your finishing moves cost 50% less Energy."},
[1220015] = {name = "Soul of the Efficient", additional_info = nil},
[1220016] = {name = "Soul of the Knife Juggler", additional_info = "[q]While Just a Flesh Wound and Blade Dance are active, Crimson Tempest, Blunderbuss, and Fan of Knives cost 20 less Energy and generate 100% increased threat."},
[1220017] = {name = "Soul of the Knife Juggler", additional_info = nil},
[1220018] = {name = "Soul of the Shadow Master", additional_info = "[q]Vanish now reduces all Magic damage you take by 50% for its duration, but it no longer grants Stealth or breaks movement impairing effects."},
[1220019] = {name = "Soul of the Shadow Master", additional_info = nil},
[1220020] = {name = "Soul of the Equilibrist", additional_info = "[q]Your finishing moves have a 20% chance per combo point to make you take 50% less Physical damage from the next melee attack that hits you within 10 sec."},
[1220021] = {name = "Soul of the Equilibrist", additional_info = nil},
[1220022] = {name = "Soul of the Poised Brawler", additional_info = "[q]Your Rolling with the Punches now also activates every time you gain a combo point."},
[1220023] = {name = "Soul of the Black Belt", additional_info = "[q]Your Rolling with the Punches also grants you 20% increased Armor from items per stack (capped at 100%)."},
[1220024] = {name = "Soul of the Poised Brawler", additional_info = nil},
[1220025] = {name = "Soul of the Black Belt", additional_info = nil},
[1220026] = {name = "Soul of the Fencer", additional_info = "[q]The cooldown on your Main Gauche resets every time your target Dodges or Parries."},
[1220027] = {name = "Soul of the Fencer", additional_info = nil},
[1220028] = {name = "Soul of the Swashbuckler", additional_info = "[q]Your Main Gauche now strikes 1 additional nearby target and also causes your Sinister Strike to strike 1 additional nearby target for 10 sec. These additional strikes are not duplicated by Blade Flurry."},
[1220029] = {name = "Soul of the Swashbuckler", additional_info = nil},
[1220030] = {name = "Soul of the Bloodthirsty", additional_info = "[q]While active, your Main Gauche also causes you to heal for 15% of all damage done by Sinister Strike. Any excess healing becomes a Blood Barrier, absorbing damage up to 20% of your maximum health."},
[1220031] = {name = "Soul of the Bloodthirsty", additional_info = nil},
[1220032] = {name = "Soul of the Transfusionist", additional_info = "[q]Lifetap generates 50% more mana and 100% less threat."},
[1220033] = {name = "Soul of the Transfusionist", additional_info = nil},
[1220034] = {name = "Soul of the Refined", additional_info = "[q]Increases your critical strike chance with spells and attacks by 2%."},
[1220035] = {name = "Soul of the Decimator", additional_info = "[q]Your Nightfall talent has a 4% increased chance to trigger. Your Incinerate has a 4% chance to trigger your Decimation regardless of the target's health."},
[1220036] = {name = "Soul of the Refined", additional_info = nil},
[1220037] = {name = "Soul of the Decimator", additional_info = nil},
[1220038] = {name = "Soul of the Rotbringer", additional_info = "[q]Increases the damage of your periodic spells and Felguard pet by 10 + (5 * Combo Points)%."},
[1220039] = {name = "Soul of the Rotbringer", additional_info = nil},
[1220040] = {name = "Soul of the Malevolent", additional_info = "[q]Periodic damage from your Shadowflame, Unstable Affliction, and Curse of Agony spells and damage done by your Felguard have a 4% chance to grant the Shadow Trance effect."},
[1220041] = {name = "Soul of the Malevolent", additional_info = nil},
[1220042] = {name = "Soul of the Shadowmancer", additional_info = "[q]Shadowbolt deals 10 + (5 * Combo Points)% increased damage for each of your effects afflicting the target, up to a maximum of 30 + (5 * Combo Points)%."},
[1220043] = {name = "Soul of the Shadowmancer", additional_info = nil},
[1220044] = {name = "Soul of the Chaos Harbinger", additional_info = "[q]Reduces the cooldown on your Chaos Bolt by 50% and increases Chaos Bolt and Shadow Bolt damage done by 10%. In addition, Chaos Bolt can now trigger your Improved Shadow Bolt talent and causes it to have 26 additional charges (does not stack with Shadowflame's additional charges)."},
[1220045] = {name = "Soul of the Chaos Harbinger", additional_info = nil},
[1220046] = {name = "Soul of the Arsonist", additional_info = "[q]Each time you hit a target with Conflagrate, you gain 5% increased Fire damage for 20 sec, stacking up to 2 times."},
[1220047] = {name = "Soul of the Arsonist", additional_info = nil},
[1220048] = {name = "Soul of the Infernal Shepherd", additional_info = "[q]Increases the Attack Power and Spell Damage your Demon pet gains from your attributes by 20%."},
[1220049] = {name = "Soul of the Infernal Shepherd", additional_info = nil},
[1220050] = {name = "Soul of the Demonlord", additional_info = "[q]Increases the benefits of your Master Demonologist talent by 50%."},
[1220051] = {name = "Soul of the Demonlord", additional_info = nil},
[1220052] = {name = "Soul of the Demonic Exorcist", additional_info = "[q]Banish is now instant cast, and can be cast on yourself while you are a Demon. You cannot Banish yourself while you have Forbearance, and doing so will give you Forbearance for 1 min."},
[1220053] = {name = "Soul of the Demonic Exorcist", additional_info = nil},
[1220054] = {name = "Soul of the Pained", additional_info = "[q]Each time you take damage, you and your pet gain mana equal to the damage taken, up to a maximum of 420 mana per event. Can only occur once every few seconds."},
[1220055] = {name = "Soul of the Pained", additional_info = nil},
[1220056] = {name = "Soul of the Flamewraith", additional_info = "[q]Your Shadow Cleave hits have a 20% chance to grant you a Soul Shard, reset the cooldown on Soul Fire, and make your next Soul Fire within 10 sec instant."},
[1220057] = {name = "Soul of the Flamewraith", additional_info = nil},
[1220058] = {name = "Soul of the Fleshfeaster", additional_info = "[q]While you are targeting an enemy within 30 yards, Life Tap grants you mana at the expense of your target's health but deals 50 + (5 * Combo Points)% reduced damage to them. Mana gained remains unchanged."},
[1220059] = {name = "Soul of the Fleshfeaster", additional_info = nil},
[1220060] = {name = "Soul of the Abyssal", additional_info = "[q]While Metamorphosis is active, your offensive abilities and Demon summons cost no Soul Shards. In addition, you heal for 15% of your maximum health when you damage a target with Shadowburn."},
[1220061] = {name = "Soul of the Abyssal", additional_info = nil},
[1220062] = {name = "Soul of the Voidborne", additional_info = "[q]Any excess healing you deal to yourself is converted into a shield that absorbs damage. This shield can absorb up to 30 + (5 * Combo Points)% of your maximum health, and stacks from multiple heals."},
[1220063] = {name = "Soul of the Voidborne", additional_info = nil},
[1220064] = {name = "Soul of the Umbral Blade", additional_info = "[q]Reduces the cooldown on your Shadow Cleave by 1.5 sec."},
[1220065] = {name = "Soul of the Umbral Blade", additional_info = nil},
[1220066] = {name = "Soul of the Ritualist", additional_info = "[q]The effects of your Demonic Sacrifice now persist while you have a Demon pet active, as long as you do not resummon the sacrificed pet. You may have only one Demonic Sacrifice effect active at a time."},
[1220067] = {name = "Soul of the Ritualist", additional_info = nil},
[1220068] = {name = "Soul of the Pain Spreader", additional_info = "[q]For 6 sec after using Shadowcleave, your Searing Pain strikes 1 additional target within melee range."},
[1220069] = {name = "Soul of the Pain Spreader", additional_info = nil},
[1220070] = {name = "Soul of the Misleader", additional_info = "[q]You generate 100% more threat for 8 sec after using Distracting Shot."},
[1220071] = {name = "Soul of the Misleader", additional_info = nil},
[1220072] = {name = "Soul of the Preyseeker", additional_info = "[q]While tracking a creature type, you deal 3% increased damage to that creature type."},
[1220073] = {name = "Soul of the Preyseeker", additional_info = nil},
[1220074] = {name = "Soul of the Sharpshooter", additional_info = "[q]Your next Shot ability within 12 sec after Aimed Shot deals 20% more damage."},
[1220075] = {name = "Soul of the Sharpshooter", additional_info = nil},
[1220076] = {name = "Soul of the Hazard Harrier", additional_info = "[q]Your Aimed Shot deals 20% more damage to targets afflicted by one of your trap effects."},
[1220077] = {name = "Soul of the Hazard Harrier", additional_info = nil},
[1220078] = {name = "Soul of the Alternator", additional_info = "[q]Your damaging Shot abilities deal 10% increased damage if the previous damaging Shot used was different than the current one."},
[1220079] = {name = "Soul of the Alternator", additional_info = nil},
[1220080] = {name = "Soul of the Toxinologist", additional_info = "[q]Your Serpent Sting damage is increased by 25% of your Attack Power over its normal duration."},
[1220081] = {name = "Soul of the Toxinologist", additional_info = nil},
[1220082] = {name = "Soul of the Bounty Hunter", additional_info = "[q]Increases Kill Shot's damage against non-player controlled targets by 30%."},
[1220083] = {name = "Soul of the Bounty Hunter", additional_info = nil},
[1220084] = {name = "Soul of the Trick Shooter", additional_info = "[q]Kill Shot's cooldown is reduced by 50%. While Rapid Fire is active with Rapid Killing engraved, Kill Shot has no cooldown, and when used against a non-player controlled target, fires 3 additional Kill Shots at 30% damage, with a minimum range."},
[1220085] = {name = "Soul of the Trick Shooter", additional_info = nil},
[1220086] = {name = "Soul of the Beast Tender", additional_info = "[q]Increases the Attack Power your Beast pet gains from your attributes by 20%."},
[1220087] = {name = "Soul of the Beast Tender", additional_info = nil},
[1220088] = {name = "Soul of the Hound Master", additional_info = "[q]Increases the Focus regeneration of your Beast pet by 20%."},
[1220089] = {name = "Soul of the Hound Master", additional_info = nil},
[1220090] = {name = "Soul of the Alpha Tamer", additional_info = "[q]Increases the Focus regeneration of your pets by 100%."},
[1220091] = {name = "Soul of the Alpha Tamer", additional_info = nil},
