[1225468] = {name = "Master Forager", additional_info = "[q]Gain 5 increased skill in Skinning, Mining, and Herbalism, and 25 increased skill in Fishing."},
[1225469] = {name = "Dedicated Study", additional_info = "25 sec cast 23 hrs cooldown\n[q]Increases your skill by 1 in your lowest tradeskill among your Primary and Secondary tradeskills. If you have already reached 300 skill in your two current Primary Tradeskills and all three Secondary Tradeskills, you will gain 2 to 4 of a random Elemental Essence."},
[1225470] = {name = "[q3]Essence of Innovation", additional_info = "25 sec cast 23 hrs cooldown\nReagents:\nEssence of Earth , Essence of Fire , Essence of Water , Essence of Air , Pristine Scale , Viridian Dye , Azerothium Bar\n[q]Craft an Essence of Innovation and research a new recipe for a non-gathering Primary tradeskill in which you have reached 300 skill."},
[1225472] = {name = "Thrill of Adventure", additional_info = "[q]You gain 5% of your maximum Health and Mana over 10 sec each time you deliver the killing blow to a non-trivial enemy. Ineffective in dungeons, raids, and battlegrounds."},
[1225474] = {name = "Talented", additional_info = "[q]You gain talent points every level starting at level 5 instead of starting at level 10, but you still may not have more than 51 total talent points."},
[1225475] = {name = "Field Medicine", additional_info = "[q]Reduces the duration of the Recently Bandaged effect by 10 sec when you use a bandage. Ineffective in dungeons, raids, and battlegrounds."},
[1225477] = {name = "High Alert", additional_info = "[q]Increases your ability to detect nearby targets with Stealth as if your level were increased by 2. Ineffective in Battlegrounds."},
[1225478] = {name = "Well Rested", additional_info = "[q]Your rested experience accumulates 20% faster and your rested experience cap is increased by 20%."},
[1225479] = {name = "Field Guide", additional_info = "[q]Reduces your cooldown on adding Camp features by 25%"},
[1225481] = {name = "Shoot", additional_info = "30 yd range\n2 sec cast\n[q]Shoot down a Wasp Nest."},
[1225482] = {name = "Shadow Bolt", additional_info = "60 yd range\n2 sec cast\n[q]Hurls a bolt of dark magic at an enemy, inflicting Shadow damage."},
[1225484] = {name = "Unyielding Pain", additional_info = "2 sec cast\n[q]Dark magic lashes out at every enemy, inflicting 5655 to 6345 Shadow damage"},
[1225485] = {name = "Diplomat", additional_info = "[q]Increases your reputation gains by 10%."},
[1225486] = {name = "Wasp Nest", additional_info = nil},
[1225487] = {name = "Iron Stomach", additional_info = "[q]Reduces your cooldown for using potions by 18 sec. Ineffective in dungeons, raids, and battlegrounds."},
[1225490] = {name = "Frequent Flier", additional_info = "[q]You receive a 50% discount on all flight paths, and your flight path mount flies 20% faster."},
[1225491] = {name = "Master Swimmer", additional_info = "[q]Your underwater breath lasts 100% longer than normal and you swim 30% faster."},
[1225492] = {name = "Play Dead", additional_info = "[q]Gives you a 25% chance of being able to resurrect with 20% Health and Mana. Ineffective in dungeons, raids, and battlegrounds. This effect cannot trigger more often than once every 5 min."},
[1225493] = {name = "Personal Banking", additional_info = "[q]All innkeepers can now also grant you access to your bank. This access has a 1 hour cooldown."},
[1225494] = {name = "Second Home", additional_info = "10 sec cast 1 hour cooldown\n[q]Returns you to the rest area where you most recently set your Second Home. When used in a rest area, makes that location your Second Home. This ability shares a cooldown with Hearthstones."},
[1225497] = {name = "Reinforce", additional_info = "[q]You take 20% less durability loss when you die."},
[1225498] = {name = "Mount Up", additional_info = "[q]Increases speed while mounted by 10%. Not active in battlegrounds. Does not stack with other effects that increase mounted movement speed."},
[1225499] = {name = "Gourmand", additional_info = "[q]Increases the duration of beneficial effects from eating food by 100%."},
[1225500] = {name = "The Quick and the Dead", additional_info = "[q]Increases movement speed while dead by 10% and your helpful spells and abilities cost no resources for 2 min after being resurrected or until you enter combat."},
[1225501] = {name = "For Great Honor", additional_info = "[q]Increases Honor Points gained by 10%."},
[1225502] = {name = "Permanence", additional_info = "[q]Your class abilities which grant long-duration stat or attribute benefits to all party or raid members last 100% longer, and the benefits you gain from resting at a camp last 50% longer."},
[1225503] = {name = "Reagent Economy", additional_info = "[q]Your class abilities no longer require reagents purchaseable from vendors."},
[1225504] = {name = "Better Living Through Chemistry", additional_info = "[q]Increases the duration of beneficial effects from elixirs and flasks by 100%."},
[1225505] = {name = "Fast Recovery", additional_info = "[q]You recover an additional 2.5% of your Health and Mana every 5 sec while not in combat."},
[1225506] = {name = "Conquering Hero", additional_info = "[q]Beneficial effects you gain from celebrating the defeat of bosses gain 100% increased duration."},
[1225508] = {name = "Second Chance", additional_info = "30 min cooldown\n[q]Effects gained from celebrating the defeat of bosses will not cancel the first time you die while they are active."},
[1225509] = {name = "Adaptability", additional_info = "6 sec cast 4 hrs cooldown\n[q]Reset your spent class talent points."},
[1225700] = {name = "Find Boomfizz Goblin", additional_info = nil},
[1225719] = {name = "1.50 Sound - Sound Squisher - Interior Zone Tone Obliterator", additional_info = nil},
[1225758] = {name = "Prowler Steak", additional_info = "3 sec cast\nReagents:\nTiger Meat (2), Holy Salts\n(3)\n55\n\n[q2]Use: Restores 2452 health over 30 sec. Must remain seated while eating. If you spend at least 10 sec eating you will become Well Fed and gain 25 Strength and 10 Stamina for 15 min."},
[1225759] = {name = "Filet o' Flank", additional_info = "3 sec cast\nReagents:\nRed Wolf Meat (2), Holy Salts\n(3)\n55\n\n[q2]Use: Restores 2452 health over 30 sec. Must remain seated while eating. If you spend at least 10 sec eating you will become Well Fed and gain 25 Agility and 10 Stamina for 15 min."},
[1225760] = {name = "Sunrise Omelette", additional_info = "3 sec cast\nReagents:\nGiant Egg (2), Holy Salts\n(3)\n55\n\n[q2]Use: Restores 2452 health over 30 sec. Must remain seated while eating. If you spend at least 10 sec eating you will become Well Fed and gain 25 Spell Damage, 55 Healing Power, and 10 Stamina for 15 min."},
[1225762] = {name = "[q2]Specklefin Feast", additional_info = "3 sec cast\nReagents:\nRaw Spotted Yellowtail (12), Raptor Flesh (4), Raw Rockscale Cod (3), Exquisite Spices\n[q2]Specklefin Feast\n(2)\n55\n\n[q2]Use: Serve a delicious feast that lasts for 3 min and serves up to 40 players.\n\n Food\nRestores 2452 health over 30 sec. Must remain seated while eating. If you spend at least 10 sec eating you will become Well Fed and gain 20 Attack Power, 23 Spell Damage, 44 Healing Power, and 10 Stamina for 45 min. (5 Min Cooldown)"},
[1225763] = {name = "[q2]Grand Lobster Banquet", additional_info = "3 sec cast\nReagents:\nDarkclaw Lobster (12), Turtle Meat (4), Buzzard Wing (3), Exquisite Spices\n[q2]Grand Lobster Banquet\n(2)\n55\n\n[q2]Use: Serve a delicious feast that lasts for 3 min and serves up to 40 players.\n\n Food\nRestores 2452 health over 30 sec. Must remain seated while eating. If you spend at least 10 sec eating you will become Well Fed and gain 20 Attack Power, 23 Spell Damage, 44 Healing Power, and 10 Stamina for 45 min. (5 Min Cooldown)"},
