[1225841] = {name = "Curse of Recklessness", additional_info = "30 yd range\nInstant\n[q]Curses the target with recklessness, increasing melee attack power by 90 but reducing armor by 640 for 2 min. Cursed enemies will not flee and will ignore Fear and Horror effects. Only one Curse per Warlock can be active on any one target."},
[1225906] = {name = "Specklefin Feast", additional_info = "2 sec cast\n[q]Serve a delicious feast that lasts for 3 min and serves up to 40 players.\n\n Food\nRestores 2452 health over 30 sec. Must remain seated while eating. If you spend at least 10 sec eating you will become Well Fed and gain 20 Attack Power, 23 Spell Damage, 44 Healing Power, and 10 Stamina for 45 min."},
