[1226022] = {name = "Tinker: Magnetic Displacement", additional_info = "100 yd range\nInstant\n[q]Disrupt a magnetic field between you and your nearby enemy target, knocking you both away.\n\n Can only affect targets up to 2 levels higher than you. Some targets cannot be displaced. Targets can only be affected by this effect once every 2 min."},
[1226032] = {name = "S03 - Item - Scarlet Enclave - Druid - Restoration 2P Bonus", additional_info = "[q]Each time your Lifebloom heals a target, it has a 5% chance to make your next Healing Touch, Nourish, or Regrowth within 15 sec instant cast.\n(Proc chance: 5%)"},
[1226035] = {name = "Swiftbloom", additional_info = "Instant\n[q]Reduces the cast time of your next Healing Touch, Regrowth, or Nourish by 100%."},
[1226038] = {name = "Rejuvenating", additional_info = "100 yd range\nInstant\n[q]Reduces the cast time of your next Healing Touch, Regrowth, or Nourish by 20%."},
[1226040] = {name = "S03 - Item - Scarlet Enclave - Druid - Restoration 4P Bonus", additional_info = nil},
[1226044] = {name = "S03 - Item - Scarlet Enclave - Druid - Restoration 6P Bonus", additional_info = nil},
[1226045] = {name = "Demagnetized", additional_info = "Unlimited range\nInstant\n[q]Disrupt a magnetic field between you and your nearby enemy target, knocking you both away.\n\n Can only affect targets up to 2 levels higher than you. Some targets cannot be displaced. Targets can only be affected by this effect once every 2 min."},
[1226046] = {name = "Wild Rejuvenation", additional_info = "Instant"},
[1226092] = {name = "S03 - Item - Scarlet Enclave - Druid - Balance 2P Bonus", additional_info = "[q]Your Starfire deals 20% more damage to targets with your Moonfire, and your Wrath deals 20% more damage to targets with your Sunfire."},
[1226103] = {name = "S03 - Item - Scarlet Enclave - Druid - Balance 4P Bonus", additional_info = "[q]Your Starsurge now increases the damage of your next 2 Starfires."},
[1226105] = {name = "Sunsurge", additional_info = "Instant\n[q]Modifies Damage/Healing Done +11%:\nWrath , Wrath , Wrath , Wrath , Wrath , Wrath , Wrath , Wrath"},
[1226106] = {name = "Moonsurge", additional_info = "Instant\n[q]Modifies Damage/Healing Done +11%:\nStarfire , Starfire , Starfire , Starfire , Starfire , Starfire , Starfire"},
[1226108] = {name = "S03 - Item - Scarlet Enclave - Druid - Balance 6P Bonus", additional_info = "[q]Each time your Sunfire deals periodic damage, you gain 10% increased damage to your next Wrath, stacking up to 5 times. Each time your Moonfire deals periodic damage, you gain 10% increased damage to your next Starfire, stacking up to 5 times. These bonuses do not apply to Starsurge."},
[1226109] = {name = "S03 - Item - Scarlet Enclave - Druid - Feral 2P Bonus", additional_info = "[q]You gain 2 Energy each time Rake or Rip deals periodic damage."},
[1226113] = {name = "Scent of Blood", additional_info = nil},
[1226116] = {name = "S03 - Item - Scarlet Enclave - Druid - Feral 4P Bonus", additional_info = "[q]Multiplies the damage bonus from Tiger's Fury by 2."},
[1226118] = {name = "S03 - Item - Scarlet Enclave - Druid - Feral 6P Bonus Trigger", additional_info = nil},
[1226119] = {name = "S03 - Item - Scarlet Enclave - Druid - Feral 6P Bonus", additional_info = "[q]Your Finishing Moves have a 20% chance per combo point spent to trigger Clearcasting and extend the duration of your active Tiger's Fury by 6 sec."},
[1226121] = {name = "S03 - Item - Scarlet Enclave - Druid - Guardian 2P Bonus", additional_info = "[q]Your melee critical strikes in Bear Form or Dire Bear Form grant you a shield lasting 10 sec that absorbs Physical damage equal to 25% of your Attack Power the next time you take Physical damage. Stacks up to 3 times."},
[1226125] = {name = "S03 - Item - Scarlet Enclave - Druid - Guardian 4P Bonus", additional_info = "[q]Increases the duration of your Berserk ability by 15 sec."},
[1226126] = {name = "S03 - Item - Scarlet Enclave - Druid - Guardian 6P Bonus", additional_info = "[q]You gain 4% increased attack speed for 10 sec every time you deal a critical strike."},
[1226127] = {name = "Savage Flurry", additional_info = nil},
[1226132] = {name = "S03 - Item - Scarlet Enclave - Hunter - Ranged 2P Bonus", additional_info = "[q]Your Shots deal 20% increased damage to targets afflicted with your Serpent Sting."},
[1226136] = {name = "Wicked Shot", additional_info = nil},
[1226137] = {name = "S03 - Item - Scarlet Enclave - Hunter - Ranged 4P Bonus", additional_info = "[q]Your ranged critical strikes increase your Attack Power by 20% for 10 sec."},
[1226138] = {name = "S03 - Item - Scarlet Enclave - Hunter - Ranged 6P Bonus", additional_info = "[q]Your Multi-Shot hits 2 additional targets, and your Kill Shot and Chimera Shot hits increase the damage done by your next Multi-Shot cast within 12 sec by 75%, stacking up to 4 times."},
[1226206] = {name = "Tinkerbox", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nMithril Casing , Gold Power Core (2)\n(2)\nCrafting Reagent\n[q]\"A simplistic control module used by engineers when creating tinkers.\""},
[1226207] = {name = "[q2]Tinkerbox: Teleport", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nTinkerbox , Unstable Trigger , Thorium Widget\n[q2]Tinkerbox: Teleport\n(2)\n45\n\n[q2]Use: Teleport forward 20 yds."},
[1226208] = {name = "[q2]Tinkerbox: Nitro Boosts", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nTinkerbox , Unstable Trigger , Thorium Tube\n[q2]Tinkerbox: Nitro Boosts\n(2)\n45\n\n[q2]Use: Activate a set of jets to increase your movement speed by up to 160%, for up to 8 sec."},
[1226209] = {name = "[q2]Tinkerbox: Magnetic Displacement", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nTinkerbox , Unstable Trigger , Iron Strut (2)\n[q2]Tinkerbox: Magnetic Displacement\n(2)\n45\n\n[q2]Use: Disrupt a magnetic field between you and your nearby enemy target, knocking you both away.\n\n Can only affect targets up to 2 levels higher than you. Some targets cannot be displaced. Targets can only be affected by this effect once every 2 min."},
[1226210] = {name = "Tinker: Teleport", additional_info = "2 sec cast\nRequires Belt\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nTinkerbox , Delicate Arcanite Converter , Thorium Widget\n[q]Augment your belt to give the following effect:\n\nTeleport forward 20 yds.\n\n This enhancement is permanent and cannot be removed or replaced."},
[1226211] = {name = "Tinker: Nitro Boosts", additional_info = "2 sec cast\nRequires Armor\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nTinkerbox , Delicate Arcanite Converter , Thorium Tube\n[q]Augment your belt to give the following effect:\n\nActivate a set of jets to increase your movement speed by up to 160%, for up to 8 sec.\n\n This enhancement is permanent and cannot be removed or replaced."},
[1226212] = {name = "Tinker: Magnetic Displacement", additional_info = "2 sec cast\nRequires Armor\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nTinkerbox , Delicate Arcanite Converter , Iron Strut (2)\n[q]Augment your belt to give the following effect:\n\nDisrupt a magnetic field between you and your nearby enemy target, knocking you both away.\n\n Can only affect targets up to 2 levels higher than you. Some targets cannot be displaced. Targets can only be affected by this effect once every 2 min.\n\n This enhancement is permanent and cannot be removed or replaced."},
[1226213] = {name = "Semisafe Transporter: New Avalon", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nDelicate Arcanite Converter , Truesilver Transformer (2), Unstable Trigger , Mithril Casing (2), Goblin Rocket Helmet (2), Righteous Orb"},
[1226215] = {name = "Semisafe Transporter: New Avalon", additional_info = "10 sec cast\n[q]Throw caution to the wind and test a goblin's attempt at a teleportation device. Hopefully you will arrive at New Avalon in one piece."},
[1226217] = {name = "Semisafe Transporter: New Avalon", additional_info = "Unlimited range\nInstant\n[q]Throw caution to the wind and test a goblin's attempt at a teleportation device. Hopefully you will arrive at New Avalon in one piece."},
