[1226377] = {name = "Timey-Bearimy", additional_info = nil},
[1226378] = {name = "S03 - Item - Scarlet Enclave - Mage - Healer 6P Bonus", additional_info = "[q]Reduces the cooldown of your Arcane Power by 0.0200 sec and increases its duration by 10 sec. While Arcane Power is active, your chance to gain Arcane Tunneling is increased by 10% and each cast of Arcane Blast reduces the remaining cooldown on Mass Regeneration by 1.0 sec."},
[1226388] = {name = "Apple", additional_info = nil},
[1226396] = {name = "Apple Scope", additional_info = "100 yd range\n1 sec cast\n[q]Allows you to look far into the distance in the pursuit of apples."},
[1226402] = {name = "Grab Apple", additional_info = "Unlimited range\n1.5 sec cast\n[q]Steal an apple from a safe distance."},
[1226406] = {name = "Arcane Tunneling", additional_info = nil},
[1226407] = {name = "S03 - Item - Scarlet Enclave - Mage - Healer 2P Bonus", additional_info = "[q]Your Arcane Blast has a 10% chance to cause Arcane Tunneling. Arcane Tunneling prevents your Arcane Blast effect from being consumed by the next other Arcane damage spell you cast. In addition, activating Arcane Power resets the cooldown on your Mass Regeneration.\n(Proc chance: 20%)"},
[1226414] = {name = "Temporal Anchor", additional_info = nil},
[1226415] = {name = "S03 - Item - Scarlet Enclave - Mage - Healer 4P Bonus", additional_info = "[q]Rewind Time also reduces all damage taken by your target by 20% for 8 sec."},
[1226423] = {name = "S03 - Item - Scarlet Enclave - Mage - Damage 2P Bonus", additional_info = "[q]Your Living Bomb now deals damage every 4000 sec, and will detonate if the target dies. In addition, the effect of Glaciate from the rune of Ice Lance now stacks up to 4 times, and Spellfrost Bolt grants 2 stacks each time it hits."},
[1226432] = {name = "S03 - Item - Scarlet Enclave - Mage - Damage 6P Bonus", additional_info = "[q]Reduces the cooldown on your Frozen Orb spell by 25 sec. Each time Glaciate is consumed, the cooldown on your Deep Freeze is reduced by 1.0 sec per stack consumed. Reduces the cooldown on Fire Blast by 5 sec and Fire Blast now refreshes the duration of your Living Bomb on the target."},
[1226446] = {name = "S03 - Item - Scarlet Enclave - Mage - Damage 4P Bonus", additional_info = "[q]Casting Deep Freeze increases the remaining duration of your Icy Veins spell by 10 sec. Casting Pyroblast cancels 2 stacks of the effect from your Balefire Bolt."},
[1226451] = {name = "Emergency", additional_info = "100 yd range\nInstant\n[q]Modifies Global Cooldown -499:\nDivine Light , Flash of Light , Flash of Light , Flash of Light , Flash of Light , Flash of Light , Flash of Light , Holy Light , Holy Light , Holy Light , Holy Light , Holy Light , Holy Light , Holy Light , Holy Light , Holy Light , Holy Shock , Holy Shock , Holy Shock , Holy Shock , Lay on Hands , Lay on Hands , Lay on Hands"},
[1226452] = {name = "S03 - Item - Scarlet Enclave - Paladin - Holy 2P Bonus", additional_info = "[q]Lay on Hands grants you 20% Spell Haste for 30 sec and reduces the Global Cooldown of your next 5 Divine Light, Holy Light, Flash of Light, or Holy Shock spells by 0.5 seconds."},
[1226454] = {name = "S03 - Item - Scarlet Enclave - Paladin - Holy 4P Bonus", additional_info = "[q]Your Beacon of Light now also triggers when you heal your Beacon of Light target, but at 100% reduced effectiveness."},
[1226455] = {name = "Charity", additional_info = nil},
