[1262975] = {name = "Rock Garden", additional_info = "10 sec cast\nReagents:\nHeavy Stone (2), Iron Ore , Silver Bar\n[q]Craft a Rock Garden.\n(2)\nRequiresMining\n(140)\n\n[q2]Use: Places a Rock Garden that spawns a common mining node over time, and provides all the benefits of a Lodestone. Requires a Campfire nearby.\n\n May be placed over a Lodestone to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1262978] = {name = "Cookie's Feast", additional_info = "10 sec cast\nReagents:\nMystery Meat (2), Heavy Kodo Meat , Soothing Spices\n[q]Craft Cookie's Feast.\n(2)\nRequiresCooking\n(140)\n\n[q2]Use: Lay out Cookie's Feast that contains Stamina-boosting food. Requires a Cooking Fire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1262980] = {name = "Greenhouse", additional_info = "10 sec cast\nReagents:\nSimple Wood (2), Arthas' Tears , Purple Lotus\n[q]Craft a Greenhouse.\n(2)\nRequiresHerbalism\n(140)\n\n[q2]Use: Places a Greenhouse that will grow herbs over time from seeds planted, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby.\n\n May be placed over an Incense Candle to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1262982] = {name = "Trapper's Workbench", additional_info = "10 sec cast\nReagents:\nSimple Wood (2), Heavy Leather (4), Iron Bar\n[q]Craft a Trapper's Workbench.\n(2)\nRequiresSkinning\n(300)\n\n[q2]Use: Places a Trapper's Workbench containing 1 trap, and provides all the benefits of a Camp Chair. Requires a Campfire nearby.\n\n May be placed over a Camp Chair to replace it.\n\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1262985] = {name = "Field Guide", additional_info = "10 sec cast\nReagents:\nMedium Leather (3), Slimy Murloc Scale (2), Fine Thread\n[q]Craft a Field Guide.\n(2)\nRequiresSkinning\n(140)\n\n[q2]Use: Places a Field Guide that allows players to read it and gain Track Beasts, and provides all the benefits of a Camp Chair. Requires a Campfire nearby.\n\n May be placed over a Camp Chair to replace it.\n\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1262990] = {name = "Fishing Rack", additional_info = "10 sec cast\nReagents:\nSimple Wood (2), Crystal Vial , Raw Mithril Head Trout (2)\n[q]Craft a Fishing Rack.\n(2)\nRequiresFishing\n(140)\n\n[q2]Use: Places a Fishing Rack that grants the ability to catch uncommon fish for 1 hour, provides Fishing Skill lures, and provides all of the benefits of a Fish Bowl. Requires a Campfire nearby.\n\n May be placed over a Fish Bowl to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1262996] = {name = "Toxin Study", additional_info = "10 sec cast\nReagents:\nAnti-Venom , Mageweave Bandage (2), Simple Wood (2)\n[q]Craft a Toxin Study."},
[1262998] = {name = "Fishing Hut", additional_info = "10 sec cast\nReagents:\nSimple Wood (5), Bolt of Runecloth (2), Seasonal Fish Steaks\n[q]Craft a Fishing Hut.\n(2)\nRequiresFishing\n(300)\n\n[q2]Use: Places a Fishing Hut that grants the ability to catch rare fish for 1 hour, provides Fishing Skill lures, and provides all of the benefits of a Fish Bowl. Requires a Campfire nearby.\n\n May be placed over a Fish Bowl to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263001] = {name = "Plague Doctor's Laboratory", additional_info = "10 sec cast\nReagents:\nSimple Wood (2), Strong Anti-Venom (2), Heavy Runecloth Bandage (5)\n[q]Craft a Plague Doctor's Laboratory."},
[1263005] = {name = "Fermenter", additional_info = "10 sec cast\nReagents:\nLeaded Vial , Kingsblood , Swiftthistle\n[q]Craft a Fermenter.\n(2)\nRequiresAlchemy\n(140)\n\n[q2]Use: Places a fermenter that allows the creation of certain reagents, and provides all of the benefits of a Mana Well. Requires a Campfire nearby. May be placed over a Mana Well to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263031] = {name = "Tanning Rack", additional_info = "10 sec cast\nReagents:\nMedium Leather (5), Fine Thread (3), Simple Wood (2)\n[q]Craft a Tanning Rack.\n(2)\nRequiresLeatherworking\n(140)\n\n[q2]Use: Places a Tanning Rack that allows the creation of certain reagents, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby.\n\n May be placed over a Camp Tent to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263032] = {name = "Spinning Wheel", additional_info = "10 sec cast\nReagents:\nSimple Wood (2), Bolt of Silk Cloth (5), Fine Thread (3)\n[q]Craft a Spinning Wheel.\n(2)\nRequiresTailoring\n(140)\n\n[q2]Use: Places a Spinning Wheel that allows the creation of certain reagents, and provides all the benefits of a Faction Banner. Requires a Campfire nearby.\n\n May be placed over a Faction Banner to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263034] = {name = "Repair Bot", additional_info = "10 sec cast\nTools: Arclight Spanner\nReagents:\nWhirring Bronze Gizmo (2), Bronze Tube , Heavy Leather\n[q]Craft a Repair Bot.\n(2)\nRequiresEngineering\n(140)\n\n[q2]Use: Summons a Repair Bot that allows you and others nearby to buy reagents and repair gear. Requires a Campfire nearby.\n\n May be placed over a Reagent Bot to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263041] = {name = "Anvil", additional_info = "10 sec cast\nReagents:\nBronze Bar (5), Coarse Grinding Stone (2), Medium Leather (2)\n[q]Craft an Anvil.\n(2)\nRequiresBlacksmithing\n(140)\n\n[q2]Use: Places an anvil, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby.\n\n May be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263056] = {name = "Arcane Salvager", additional_info = "10 sec cast\nTools: Runed Truesilver Rod\nReagents:\nVision Dust (2), Lesser Nether Essence\n[q]Craft an Arcane Salvager.\n(2)\nRequiresEnchanting\n(140)\n\n[q2]Use: Places an Arcane Salvager that enables more efficient disenchanting, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby.\n\n May be placed over an Enchanted Lute to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263067] = {name = "Iron Oven", additional_info = "10 sec cast\nReagents:\nSimple Flour (10), Refreshing Spring Water (5), Soothing Spices (4)\n[q]Craft an Iron Oven.\n(2)\nRequiresCooking\n(300)\n\n[q2]Use: Places an Iron Oven required for the most advanced cooking recipes. Requires a Cooking Fire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263070] = {name = "Seed Hybridizer", additional_info = "10 sec cast\nReagents:\nMountain Silversage (4), Crystal Vial , Runecloth (2)\n[q]Craft a Seed Hybridizer.\n(2)\nRequiresHerbalism\n(300)\n\n[q2]Use: Places a Seed Hybridizer that allows seeds to be multiplied or combined into rarer tiers, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby.\n\n May be placed over an Incense Candle to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263071] = {name = "Molten Foundry", additional_info = "10 sec cast\nReagents:\nThorium Bar (5), Dense Stone (2), Truesilver Bar\n[q]Craft a Molten Foundry.\n(2)\nRequiresMining\n(300)\n\n[q2]Use: Places a Molten Foundry usable for recipes that require it, and provides all the benefits of a Lodestone. Requires a Campfire nearby.\n\n May be placed over a Lodestone to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263073] = {name = "Master Forge", additional_info = "10 sec cast\nReagents:\nGolem Heart , Thorium Bar (5), Rugged Leather (2)\n[q]Craft a Master Forge.\n(2)\nRequiresBlacksmithing\n(300)\n\n[q2]Use: Places a Master Forge usable for recipes that require it, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby.\n\n May be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263078] = {name = "Alchemy Laboratory", additional_info = "10 sec cast\nReagents:\nLich's Index Finger , Crystal Vial , Dreamfoil (2)\n[q]Craft an Alchemy Laboratory.\n(2)\nRequiresAlchemy\n(300)\n\n[q2]Use: Places an Alchemy Laboratory usable for recipes that require it, and provides all of the benefits of a Mana Well. Requires a Campfire nearby.\n\n May be placed over a Mana Well to replace it.\n All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263079] = {name = "Sewing Machine", additional_info = "10 sec cast\nReagents:\nUndeath Engine , Rugged Leather (5), Rune Thread\n[q]Craft a Sewing Machine.\n(2)\nRequiresLeatherworking\n(300)\n\n[q2]Use: Places a Sewing Machine usable for recipes that require it, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby.\n\n May be placed over a Camp Tent to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263080] = {name = "Loom", additional_info = "10 sec cast\nReagents:\nBottled Screams , Bolt of Runecloth (4), Simple Wood (4)\n[q]Craft a Loom.\n(2)\nRequiresTailoring\n(300)\n\n[q2]Use: Places a Loom usable for recipes that require it, and provides all the benefits of a Faction Banner. Requires a Campfire nearby.\n\n May be placed over a Faction Banner to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263082] = {name = "Arcane Forge", additional_info = "10 sec cast\nReagents:\nMaker's Spark , Large Brilliant Shard (2), Greater Eternal Essence (4)\n[q]Craft an Arcane Forge.\n(2)\nRequiresEnchanting\n(300)\n\n[q2]Use: Places an Arcane Forge usable for recipes that require it, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby.\n\n May be placed over an Enchanted Lute to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
[1263083] = {name = "Anarchist's Workbench", additional_info = "10 sec cast\nTools: Arclight Spanner\nReagents:\nEssence of Anarchy , Thorium Widget (2)\n[q]Craft an Anarchist's Workbench.\n(2)\nRequiresEngineering\n(300)\n\n[q2]Use: Places an Anarchist's Workbench usable for recipes that require it. Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)"},
