[1266893] = {name = "SAF-T Tabs", additional_info = "5.125 sec cast\nReagents:\nLinen Cloak , Cerulean Dye\nCrafting Reagent\n[q]\"SAF-T brand tabs make it SAF to hand out dynamite to all your friends!\""},
[1266905] = {name = "SAF-T Dynamite", additional_info = "5.125 sec cast\nReagents:\nRough Blasting Powder (2), Linen Cloth\n\n[q2]Use: Inflicts 26 to 34 Fire damage in a 5 yd radius. (1 Min Cooldown)\n[q]\"Easy to throw, and SAF-T too!\""},
[1266906] = {name = "SAF-T Copper Bomb", additional_info = "8 sec cast\nTools: Blacksmith Hammer\nReagents:\nCopper Bar , Handful of Copper Bolts , Rough Blasting Powder (2), Linen Cloak , SAF-T Tabs (2)\n\n[q2]Use: Inflicts 22 to 28 Fire damage and stuns targets in a 3 yd radius for 1 sec. Any damage will break the effect. (1 Min Cooldown)\n[q]\"SAF-T Brand bombs *almost* never blow up in your hands (or your paws!)\""},
[1266907] = {name = "EZ-Thro Wrap", additional_info = "8 sec cast\nReagents:\nWool Cloth , Sulfuric Acid\nCrafting Reagent"},
[1266908] = {name = "EZ-Thro Copper Bomb XL", additional_info = "12.5 sec cast\nTools: Blacksmith Hammer\nReagents:\nCopper Bar (3), Coarse Blasting Powder (4), Silver Contact , EZ-Thro Wrap\n\n[q2]Use: Inflicts 43 to 57 Fire damage and stuns targets in a 5 yd radius for 1 sec. Any damage will break the effect. (1 Min Cooldown)"},
[1266909] = {name = "No Slip SAF-T Padding", additional_info = "12.5 sec cast\nReagents:\nHeavy Leather , Magenta Dye\nCrafting Reagent\n[q]\"SAF-T Padding prevents those easy throwing accidents.\""},
[1266910] = {name = "SAF-T Bronze Bomb", additional_info = "12.5 sec cast\nTools: Blacksmith Hammer\nReagents:\nCoarse Blasting Powder (4), Bronze Bar (2), Silver Contact , Wool Cloth , No Slip SAF-T Padding\n\n[q2]Use: Inflicts 73 to 97 Fire damage and stuns targets in a 3 yd radius for 2 sec. Any damage will break the effect. (1 Min Cooldown)"},
[1266911] = {name = "SAF-T Jumbo Dynamite", additional_info = "12.5 sec cast\nReagents:\nHeavy Blasting Powder (2), Wool Cloth , No Slip SAF-T Padding\n\n[q2]Use: Inflicts 128 to 172 Fire damage in a 5 yd radius. (1 Min Cooldown)\n[q]\"If it's easy to throw, it's not SAF-T!\""},
[1266912] = {name = "SAF-T Bell", additional_info = "25 sec cast\nTools: Blacksmith Hammer\nReagents:\nBronze Bar (2), Sandpaper\nCrafting Reagent\n[q]\"Do you know where your Sheep is?! SAF-T Knows.\""},
[1266913] = {name = "Shafety Sheep", additional_info = "25 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nBronze Framework , Whirring Bronze Gizmo , Heavy Blasting Powder (2), Wool Cloth (2), SAF-T Bell\n\n[q2]Use: Summons an Explosive Sheep which will charge at a nearby enemy and explode for 135 to 165 damage. Lasts for 3 min or until it explodes. (1 Min Cooldown)\n[q]\"Guaranteed to blow up only where it's SAF!\""},
[1266914] = {name = "EZ-Thro Fireproof Fuse", additional_info = "25 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nSilver Contact , Pristine Hide\nCrafting Reagent\n[q]\"Guaranteed not to burn!\""},
[1266915] = {name = "EZ-Thro Bronze Mortar", additional_info = "25 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nBronze Tube (4), Iron Strut , Heavy Blasting Powder (4), Medium Leather (4), EZ-Thro Fireproof Fuse\nBinds when equipped\nUnique-EquippedTrinket\n[q2]Use: Inflicts 85 to 115 Fire damage and stuns targets in a 5 yd radius for 2 sec. Any damage will break the effect. (10 Min Cooldown)\n8 Charges\n[q]\"Thro mo mo tar!\""},
[1266916] = {name = "EZ-Thro Grenade", additional_info = "25 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nIron Bar , Heavy Blasting Powder , Silk Cloth , EZ-Thro Fireproof Fuse\n\n[q2]Use: Inflicts 213 to 287 Fire damage in a 5 yd radius. (1 Min Cooldown)\n[q]\"Who needs safety when it's this easy to throw?\""},
[1266917] = {name = "SAF-T Casing", additional_info = "45 sec cast\nTools: Blacksmith Hammer\nReagents:\nMithril Casing , Heavy Leather\nCrafting Reagent\n[q]\"Extra padding for SAF-T!\""},
[1266918] = {name = "SAF-T Bomb", additional_info = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nIron Bar (3), Heavy Blasting Powder (3), Silver Contact , SAF-T Casing\n\n[q2]Use: Inflicts 149 to 201 Fire damage and stuns targets in a 5 yd radius for 3 sec. Any damage will break the effect. (1 Min Cooldown)\n[q]\"S. A. F. T. B. O. M. B. SAF-T. Bomb.\""},
[1266919] = {name = "Emergency Field Cloak", additional_info = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nGnomish Cloaking Device , SAF-T Casing\nBinds when picked up\nUnique-EquippedTrinket\n[q2]Use: Gives invisibility for 10 sec. (1 Hour Cooldown)\n3 Charges\n[q]\"SAF-T means not getting caught.\""},
[1266920] = {name = "Compact Critter Carrier", additional_info = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nHeavy Leather (10), Mithril Tube (10), Greater Nether Essence (2), Gold Power Core\nClasses: Hunter\n40\n\n[q2]Use: Place a Compact Critter Carrier for 3 min that allows Hunters in your group to access their stabled pets. (30 Min Cooldown)"},
[1266921] = {name = "EZ-Thro Tru-Trigger", additional_info = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nTruesilver Bar , Viridian Dye\nCrafting Reagent\n[q]\"EZ to use and almost never misfires!\""},
[1266922] = {name = "Tru-Trigger Frag Bomb", additional_info = "45 sec cast\nReagents:\nMithril Casing , Unstable Trigger , Solid Blasting Powder , EZ-Thro Tru-Trigger\n\n[q2]Use: Inflicts 149 to 201 Fire damage and stuns targets in an 8 yd radius for 2 sec. Any damage will break the effect. (1 Min Cooldown)\n[q]\"Tru-Trigger frags enemies, not in your hands.\""},
[1266923] = {name = "SAF-T Disposable Parachute", additional_info = "45 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nParachute Cloak , SAF-T Casing\nBinds when equipped\nBack\n31 Armor\n[q2]Use: Reduces your fall speed for 10 sec. (30 Min Cooldown)\n3 Charges\n[q]\"SAF-T in case you need to jump.\""},
[1266924] = {name = "Gnomish Army Knife", additional_info = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nMithril Casing , Gold Power Core , Thorium Widget (2)\n45\n[q]\"It's got everything: a spanner, a wrench, a hammer... even a mining pick.\""},
[1266925] = {name = "[q3]Loot-A-Rang", additional_info = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nThorium Bar (5), Greater Eternal Essence (5)\n[q3]Loot-A-Rang\nBinds when used\n50\nRequiresEngineering\n(250)\n\n[q2]Use: Retrieves the loot from a nearby corpse. (3 Sec Cooldown)"},
[1266926] = {name = "SAF-T Tube", additional_info = "1 min cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nThorium Bar , Azerothium Bar\nCrafting Reagent\n[q]\"Prevents accidental oxygen exposure. That wouldn't be SAF.\""},
[1266927] = {name = "SAF-T Clever Dynamite", additional_info = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nDense Blasting Powder (2), Runecloth (3), SAF-T Tube\n\n[q2]Use: Inflicts 340 to 460 Fire damage in a 5 yd radius. (1 Min Cooldown)\n[q]\"SAF-T isn't dense. It's clever!\""},
[1266928] = {name = "EZ-Thro Shell", additional_info = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nThorium Bar (2), Pristine Scale\nCrafting Reagent\n[q]\"Encase your explosives in EZ to Thro thorium-plated shells.\""},
[1266929] = {name = "EZ-Thro Thorium Grenade", additional_info = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nThorium Widget , Thorium Bar (3), Dense Blasting Powder (3), Runecloth (3), EZ-Thro Shell\n\n[q2]Use: Inflicts 300 to 500 Fire damage and stuns targets for 3 sec in a 3 yd radius. Any damage will break the effect. (1 Min Cooldown)\n[q]\"Anyone can use grenades with EZ-Thro!\""},
[1266930] = {name = "EZ-Thro Dark Bomb", additional_info = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nThorium Widget (2), Dark Iron Bar , Dense Blasting Powder (3), Runecloth (3), EZ-Thro Shell\n\n[q2]Use: Inflicts 225 to 675 Fire damage and stuns targets in a 5 yd radius for 4 sec. Any damage will break the effect. (1 Min Cooldown)\n[q]\"So EZ, you can Thro it in the dark.\""},
[1266931] = {name = "EZ-Thro Mana Bomb", additional_info = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nDelicate Arcanite Converter , Thorium Bar (3), Runecloth , EZ-Thro Shell\n\n[q2]Use: Burns 675 to 1125 mana from those in the blast radius and deals 50% of the mana drained in damage to the target. Also Silences targets in the blast for 5 sec. (1 Min Cooldown)"},
[1266932] = {name = "[q2]EZ-Thro Field Transporter: Gadgetzan", additional_info = "1 min cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nUltrasafe Transporter: Gadgetzan , EZ-Thro Shell\n[q2]EZ-Thro Field Transporter: Gadgetzan\nBinds when used\nUnique-EquippedTrinket\n55\n[q2]Use: Safely transport yourself to Gadgetzan in Tanaris!  Emphasis on Safe!  Yup, nothing bad could ever happen while using this device! (4 Hrs Cooldown)\n3 Charges"},
[1266933] = {name = "[q2]SAF-T Emergency Ripper: Everlook", additional_info = "1 min cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nDimensional Ripper - Everlook , SAF-T Tube (2)\n[q2]SAF-T Emergency Ripper: Everlook\nBinds when used\nUnique-EquippedTrinket\n55\n[q2]Use: Rips the dimensional walls asunder and transports you to Everlook in Winterspring.  There are technical problems that sometimes occur, but that's what Goblin Engineering is all about! (4 Hrs Cooldown)\n3 Charges"},
[1266934] = {name = "[q2]EZ and SAF Field Transporter: Mt. Hyjal", additional_info = "1 min cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nDimensional Transporter - Mt. Hyjal , EZ-Thro Shell , SAF-T Tube\n[q2]EZ and SAF Field Transporter: Mt. Hyjal\nBinds when used\nUnique-EquippedTrinket\n60\n[q2]Use: Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering. (4 Hrs Cooldown)\n3 Charges\n[q]\"Not only combining Goblin and Gnome tech, but also combining plans from the EZ-Thro and SAF-T corporations. Who knows if this will even work?\""},
[1266935] = {name = "[q2]Ultrasafe Rechargeable Battery", additional_info = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSulfuric Acid (2), Pitchblende , Viridian Dye , Thorium Bar (3), Mithril Bar , Death Lotus\n[q2]Ultrasafe Rechargeable Battery\n60\n\n[q2]Use: Restores 3 charges to a SAF-T or EZ-Thro brand device in your possession that does not involve explosions. It would be completely Unsafe with explosives. (1 Min Cooldown)"},
[1266936] = {name = "[q2]Dimensional Transporter - Mt. Hyjal", additional_info = "1 min cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nMithril Bar (10), Truesilver Transformer , Core of Earth (4), Essence of Air (4), Legionite Bar (2)\n[q2]Dimensional Transporter - Mt. Hyjal\nBinds when used\n60\nRequiresEngineering\n(300)\n\n[q2]Use: Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering. (4 Hrs Cooldown)\n[q]\"A dangerous amalgamation of Goblin and Gnome engineering techniques.\""},
[1266937] = {name = "[q3]Gnomish Poultryizer", additional_info = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nIllusion Dust (10), Large Brilliant Shard (2), Azerothium Bar (2), Legionite Bar (2)\n[q3]Gnomish Poultryizer\nBinds when picked up\nUnique-EquippedTrinket\n60\n[q2]Use: Turns the target into a chicken for 15 sec. Well, that is assuming the transmogrification polarity has not been reversed... (5 Min Cooldown)"},
[1266938] = {name = "[q2]Ultralight Goblin Glider", additional_info = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nViridian Dye (2), Azerothium Bar (2), Pristine Scale (8), Thorium Bar (8)\n[q2]Ultralight Goblin Glider\nBinds when used\nRequiresEngineering\n(250)\n\n[q2]Use: Glide downward through the air for 10 sec while controlling your direction of travel. (3 Min Cooldown)"},
[1266939] = {name = "[q2]Gnomish Weather Machine", additional_info = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nEssence of Earth (2), Essence of Fire (2), Essence of Air (2), Essence of Water (2), Death Lotus (2)\n[q2]Gnomish Weather Machine NYI\nBinds when used\n60\nRequiresEngineering\n(300)"},
[1266940] = {name = "[q2]Stealthman 52", additional_info = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nEssence of Air (6), Illusion Dust (6), Torbernite (2), Legionite Bar (2), Marefoil (4)\n[q2]Stealthman 52\n55\nRequiresEngineering\n(250)\n\n[q2]Use: Cloaks the user in a stealth field for up to 1 min. Cannot be used in combat. The field lasts for up to 6 sec after moving. (5 Min Cooldown)\n[q]\"Used by real secret agents.\""},
[1266941] = {name = "[q2]SAF-T Nitro Boosts", additional_info = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSchematic: Tinker: Nitro Boosts , SAF-T Tube (2)\n[q2]SAF-T Nitro Boosts\nBinds when equipped\nWaist\n55\n[q2]Use: Activate a set of jets to increase your movement speed by up to 160%, for up to 8 sec.\n3 Charges\n[q]\"Rocket to safety with SAF-T.\""},
[1266942] = {name = "[q2]EZ-Thro Magnetic Displacer", additional_info = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSchematic: Tinker: Magnetic Displacement , EZ-Thro Shell\n[q2]EZ-Thro Magnetic Displacer\nBinds when equipped\nWaist\n55\n[q2]Use: Disrupt a magnetic field between you and your nearby enemy target, knocking you both away.\n\n Can only affect targets up to 2 levels higher than you. Some targets cannot be displaced. Targets can only be affected by this effect once every 2 min.\n3 Charges\n[q]\"EZ-Thro corporation not responsible for magnets preventing grenades from being thrown.\""},
[1266943] = {name = "[q2]SAF-T Teleport", additional_info = "1 min cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSchematic: Tinker: Teleport , SAF-T Tube (2)\n[q2]SAF-T Teleport\nBinds when equipped\nWaist\n55\n[q2]Use: Teleport forward 20 yds.\n3 Charges\n[q]\"Teleport to SAF-T!\""},
