[1307227] = {name = "Basic Campfire", additional_info = "2 - 3 yd range\n{10 sec cast} {5 min cooldown}\n[q]Builds a basic campfire that allows cooking and the placement of up to 3 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features."},
[1307229] = {name = "Camp Chair", additional_info = "1 yd range10 sec cast 1 hour cooldown\n[q]Assembles a camp chair that allows you and others sitting nearby to gain 2% increased critical strike chance with all spells and attacks, mutually exclusive with Moonkin Aura.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour."},
[1307230] = {name = "Camp Tent", additional_info = "1 yd range10 sec cast 1 hour cooldown\n[q]Builds a tent that allows you and others sitting nearby to increase Rested experience to 5% of a level. No effect if Rested experience already exceeds that value.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour."},
[1307234] = {name = "Enchanted Lute", additional_info = "1 yd range10 sec cast 1 hour cooldown\n[q]Summons an enchanted lute that allows you and others sitting nearby to gain [28][71][114][163][211][260][308] Armor[][and][,][13][12][9][7][4][2][increase to all stats][, and 22][, and 16][, and 12][, and 6][increase to all resistances], mutually exclusive with Mark of the Wild.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour."},
[1307237] = {name = "Expert Campfire", additional_info = "2 - 3 yd range\n{10 sec cast} {5 min cooldown}\n[q]Builds an expert campfire that allows cooking and the placement of up to 10 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features."},
[1307239] = {name = "Faction Banner", additional_info = "1 yd range10 sec cast 1 hour cooldown\n[q]Unrolls a banner that allows you and other members of the Alliance sitting nearby to gain [14][19][27][32] increased Spirit, mutually exclusive with Divine Spirit.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour."},
[1307240] = {name = "Faction Banner", additional_info = "1 yd range10 sec cast 1 hour cooldown\n[q]Unrolls a banner that allows you and other members of the Horde sitting nearby to gain [14][19][27][32] increased Spirit, mutually exclusive with Divine Spirit.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour."},
[1307242] = {name = "Fermenter", additional_info = "1 yd range10 sec cast 1 hour cooldown\n[q]Places a fermenter that allows the creation of certain reagents, and provides all of the benefits of a Mana Well. Requires a Campfire nearby. May be placed over a Mana Well to replace it. All camping features share a cooldown of 1 hour."},
[1307243] = {name = "Field Guide", additional_info = "1 yd range10 sec cast 1 hour cooldown\n[q]Places a Field Guide that allows players to read it and gain Track Beasts, and provides all the benefits of a Camp Chair. Requires a Campfire nearby.\n\n May be placed over a Camp Chair to replace it.\n\n All camping features share a cooldown of 1 hour."},
[1307244] = {name = "First Aid Kit", additional_info = "1 yd range10 sec cast 1 hour cooldown\n[q]Unpacks a first aid kit that allows you and others sitting nearby to gain [3][8][21][34][45][56] increased Stamina, mutually exclusive with Power Word: Fortitude.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour."},
[1307245] = {name = "Fish Bowl", additional_info = "1 yd range10 sec cast 1 hour cooldown\n[q]Places a small fish bowl that allows you and others sitting nearby to gain 8% increased stats, mutually exclusive with Blessing of Kings.\n\n Requires a Campfire nearby. All camping features share a cooldown of 1 hour."},
